/**
 * Bot Detection Utility
 * Analyzes avatar thumbnail similarity to detect potential bot servers
 */

// Configuration
const SIMILARITY_THRESHOLD = 7; // Lower values = more strict similarity detection
const MIN_THUMBNAILS_FOR_ANALYSIS = 2; // Minimum thumbnails needed for analysis
const CANVAS_SIZE = 8; // Size for image hash calculation (8x8 grid)

/**
 * Converts an image URL to a simplified hash for comparison
 * @param {string} imageUrl - The avatar thumbnail URL
 * @returns {Promise<string|null>} - Hash string or null if failed
 */
async function calculateImageHash(imageUrl) {
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.crossOrigin = "anonymous";

      img.onload = () => {
        try {
          // Create a small canvas for hash calculation
          const canvas = document.createElement("canvas");
          canvas.width = CANVAS_SIZE;
          canvas.height = CANVAS_SIZE;
          const ctx = canvas.getContext("2d");

          // Draw image scaled down to canvas size
          ctx.drawImage(img, 0, 0, CANVAS_SIZE, CANVAS_SIZE);

          // Get pixel data
          const imageData = ctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE);
          const data = imageData.data;

          // Calculate average brightness
          let totalBrightness = 0;
          const pixelCount = data.length / 4; // 4 values per pixel (RGBA)

          for (let i = 0; i < data.length; i += 4) {
            const brightness = (data[i] + data[i + 1] + data[i + 2]) / 3;
            totalBrightness += brightness;
          }

          const avgBrightness = totalBrightness / pixelCount;

          // Create hash based on whether each pixel is above or below average
          let hash = "";
          for (let i = 0; i < data.length; i += 4) {
            const pixelBrightness = (data[i] + data[i + 1] + data[i + 2]) / 3;
            hash += pixelBrightness > avgBrightness ? "1" : "0";
          }

          resolve(hash);
        } catch (canvasError) {
          console.warn("Canvas processing failed:", canvasError);
          resolve(null);
        }
      };

      img.onerror = () => {
        console.warn("Image load failed:", imageUrl);
        resolve(null);
      };

      // Add timestamp to prevent caching issues
      const separator = imageUrl.includes("?") ? "&" : "?";
      img.src = `${imageUrl}${separator}_t=${Date.now()}`;
    } catch (error) {
      console.warn("Image hash calculation failed:", error);
      resolve(null);
    }
  });
}

/**
 * Calculates the Hamming distance between two hash strings
 * @param {string} hash1 - First hash
 * @param {string} hash2 - Second hash
 * @returns {number} - Distance between hashes (0 = identical)
 */
function calculateHashDistance(hash1, hash2) {
  if (!hash1 || !hash2 || hash1.length !== hash2.length) {
    return Infinity;
  }

  let distance = 0;
  for (let i = 0; i < hash1.length; i++) {
    if (hash1[i] !== hash2[i]) {
      distance++;
    }
  }
  return distance;
}

/**
 * Analyzes a set of avatar URLs for similarity
 * @param {string[]} avatarUrls - Array of avatar thumbnail URLs
 * @returns {Promise<Object>} - Analysis results
 */
export async function analyzeBotProbability(avatarUrls) {
  // Validate input
  if (!avatarUrls || !Array.isArray(avatarUrls) || avatarUrls.length < MIN_THUMBNAILS_FOR_ANALYSIS) {
    return {
      botPercentage: 0,
      confidence: "low",
      similarPairs: 0,
      totalThumbnails: avatarUrls?.length || 0,
      analyzed: false,
      reason: "Insufficient thumbnails for analysis",
    };
  }

  try {
    // Calculate hashes for all images
    const hashPromises = avatarUrls.map((url) => calculateImageHash(url));
    const hashes = await Promise.all(hashPromises);

    // Filter out failed hash calculations
    const validHashes = hashes.filter((hash) => hash !== null);

    if (validHashes.length < MIN_THUMBNAILS_FOR_ANALYSIS) {
      return {
        botPercentage: 0,
        confidence: "low",
        similarPairs: 0,
        totalThumbnails: avatarUrls.length,
        analyzed: false,
        reason: "Failed to process enough thumbnails",
      };
    }

    // Find similar pairs
    const similarHashes = new Set();
    let similarPairs = 0;

    for (let i = 0; i < validHashes.length; i++) {
      for (let j = i + 1; j < validHashes.length; j++) {
        const distance = calculateHashDistance(validHashes[i], validHashes[j]);

        if (distance <= SIMILARITY_THRESHOLD) {
          similarPairs++;
          similarHashes.add(validHashes[i]);
          similarHashes.add(validHashes[j]);
        }
      }
    }

    // Calculate bot percentage
    const botCount = similarHashes.size;
    const botPercentage = Math.round((botCount / validHashes.length) * 100);

    // Determine confidence level
    let confidence = "low";
    if (validHashes.length >= 4 && similarPairs > 0) {
      confidence = "medium";
    }
    if (validHashes.length >= 5 && similarPairs >= 2) {
      confidence = "high";
    }

    return {
      botPercentage,
      confidence,
      similarPairs,
      totalThumbnails: avatarUrls.length,
      validThumbnails: validHashes.length,
      botCount,
      analyzed: true,
      reason: similarPairs > 0 ? `Found ${similarPairs} similar pair(s)` : "No similar avatars detected",
    };
  } catch (error) {
    console.error("Bot analysis failed:", error);
    return {
      botPercentage: 0,
      confidence: "low",
      similarPairs: 0,
      totalThumbnails: avatarUrls.length,
      analyzed: false,
      reason: "Analysis failed due to error",
    };
  }
}

/**
 * Gets a color class based on bot percentage
 * @param {number} botPercentage - Bot percentage (0-100)
 * @returns {string} - Tailwind color class
 */
export function getBotPercentageColor(botPercentage) {
  if (botPercentage >= 60) return "tw-text-red-500";
  if (botPercentage >= 40) return "tw-text-orange-500";
  if (botPercentage >= 20) return "tw-text-yellow-500";
  return "tw-text-green-500";
}

/**
 * Gets a background color class based on bot percentage
 * @param {number} botPercentage - Bot percentage (0-100)
 * @returns {string} - Tailwind background color class
 */
export function getBotPercentageBackground(botPercentage) {
  if (botPercentage >= 60) return "tw-bg-red-500/20";
  if (botPercentage >= 40) return "tw-bg-orange-500/20";
  if (botPercentage >= 20) return "tw-bg-yellow-500/20";
  return "tw-bg-green-500/20";
}

/**
 * Gets a descriptive label for bot percentage
 * @param {number} botPercentage - Bot percentage (0-100)
 * @param {string} confidence - Confidence level
 * @returns {string} - Descriptive label
 */
export function getBotPercentageLabel(botPercentage, confidence = "low") {
  if (confidence === "low") return "Unknown";

  if (botPercentage >= 80) return "Very High";
  if (botPercentage >= 60) return "High";
  if (botPercentage >= 40) return "Medium";
  if (botPercentage >= 20) return "Low";
  return "Very Low";
}
