import { getPNGIcon } from "../../utils/iconManager.js";
import { waitForClass } from "../../utils/selectorManager.js";
import { browserAPI } from "../../core/browserAPI.js";

// URL of the standalone settings page. It's a web-accessible extension page,
// so the in-page entry points just link straight to it in a new tab — no
// service-worker round-trip, so it opens even if the SW is asleep or stalled.
function settingsPageUrl() {
  return browserAPI.runtime.getURL("options.html");
}

export async function handleSidebarSettingButton() {
  if (!window.location.pathname.includes("my/account")) return;

  const params = new URLSearchParams(window.location.search);
  let paramCount = 0;
  params.forEach(() => paramCount++);
  if (paramCount > 0) return;

  const menuElement = await waitForClass("menu-vertical");
  const [navButton, navLink] = CreateSettingNavigationButton("BetterBLOX Settings");

  navLink.href = settingsPageUrl();
  navLink.target = "_blank";
  navLink.rel = "noopener";

  menuElement.appendChild(navButton);
}

export function addGearIconSettingsButton(element) {
  const li = document.createElement("li");
  const a = document.createElement("a");
  a.className = "rbx-menu-item";
  a.href = settingsPageUrl();
  a.target = "_blank";
  a.rel = "noopener";
  a.style.display = "flex";
  a.style.alignItems = "center";

  const img = document.createElement("img");
  img.src = getPNGIcon("logo32");
  img.style.marginRight = "5px";
  img.style.width = "16px";
  img.style.height = "16px";

  a.appendChild(img);
  a.appendChild(document.createTextNode("BetterBLOX Settings"));

  const span = document.createElement("span");
  span.className = "notification-blue notification nav-setting-highlight hidden";
  span.textContent = "0";

  a.appendChild(span);
  li.appendChild(a);

  element.insertBefore(li, element.firstChild);
}

export function CreateSettingNavigationButton(label) {
  const listItem = document.createElement("li");
  listItem.className = "menu-option ng-scope";
  listItem.setAttribute("ng-repeat", "tab in accountsTabs");
  listItem.setAttribute("ng-class", "{'active': currentData.activeTab == tab.name}");
  listItem.setAttribute("aria-label", `Navigate to ${label}`);

  const link = document.createElement("a");
  link.className = "menu-option-content";
  link.setAttribute("ui-sref", "qol-settings");
  link.style.display = "flex";
  link.style.alignItems = "center";

  const img = document.createElement("img");
  img.src = getPNGIcon("logo32");
  img.style.marginRight = "5px";
  img.style.width = "13px";
  img.style.height = "13px";

  const span = document.createElement("span");
  span.className = "font-caption-header ng-binding";
  span.setAttribute("ng-bind", "tab.label");
  span.innerText = label;

  link.appendChild(img);
  link.appendChild(span);
  listItem.appendChild(link);

  return [listItem, link, span];
}
