import { getProfileSelectors } from "../../../../core/profileSelectors.js";

function getUserID() {
  try {
    const url = window.location.href;
    const match = url.match(/\/users\/(\d+)\/profile/);
    if (match && match[1]) return parseInt(match[1]);
    return null;
  } catch (_) {
    return null;
  }
}

function formatTimestamp(timestamp) {
  const date = new Date(timestamp);
  const now = new Date();
  const diff = now - date;
  const minutes = Math.floor(diff / (1000 * 60));
  const hours = Math.floor(diff / (1000 * 60 * 60));
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
  if (hours < 24) return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
  if (days < 7) return `${days} day${days !== 1 ? "s" : ""} ago`;

  return date.toLocaleDateString() + " " + date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function filterHistoryByDate(history, startDate, endDate) {
  if (!startDate && !endDate) return history;
  const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
  const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
  return history.filter((entry) => {
    if (start && entry.timestamp < start) return false;
    if (end && entry.timestamp > end) return false;
    return true;
  });
}

// ── History widget (designed to sit inside .bblox-stats-container) ───

const INITIAL_DISPLAY = 10;

function createHistoryWidget(history) {
  const wrapper = document.createElement("div");
  wrapper.className = "tw-mt-3 tw-pt-3 tw-border-t tw-border-[#e5e5e5] dark:tw-border-[#3a3d40]";

  // Header row: title + date filters
  const header = document.createElement("div");
  header.className = "tw-flex tw-flex-wrap tw-items-center tw-justify-between tw-gap-2 tw-mb-2";

  const title = document.createElement("h3");
  title.className = "tw-text-base tw-font-semibold tw-text-[#1c1c1c] dark:tw-text-gray-200";
  title.textContent = "Friend Changes";
  header.appendChild(title);

  const filterDiv = document.createElement("div");
  filterDiv.className = "tw-flex tw-items-center tw-gap-2";

  const dateInputClass =
    "tw-text-xs tw-px-2 tw-py-1 tw-border tw-border-[#e5e5e5] dark:tw-border-gray-600 tw-rounded-md tw-bg-white dark:tw-bg-[#353840] tw-text-[#1c1c1c] dark:tw-text-gray-200";

  const fromInput = document.createElement("input");
  fromInput.type = "date";
  fromInput.className = dateInputClass;
  fromInput.title = "From date";

  const toInput = document.createElement("input");
  toInput.type = "date";
  toInput.className = dateInputClass;
  toInput.title = "To date";

  const clearBtn = document.createElement("button");
  clearBtn.className = "tw-text-xs tw-px-2 tw-py-1 tw-text-[#666] dark:tw-text-gray-400 hover:tw-text-[#1c1c1c] dark:hover:tw-text-gray-200 tw-rounded";
  clearBtn.textContent = "Clear";

  filterDiv.appendChild(fromInput);
  filterDiv.appendChild(document.createTextNode(" – "));
  filterDiv.appendChild(toInput);
  filterDiv.appendChild(clearBtn);
  header.appendChild(filterDiv);
  wrapper.appendChild(header);

  // Scrollable list
  const list = document.createElement("div");
  list.className =
    "tw-space-y-1.5 tw-max-h-[200px] tw-overflow-y-auto tw-pr-2 scrollbar-thin scrollbar-thumb-[#e5e5e5] dark:scrollbar-thumb-gray-600 scrollbar-track-transparent";
  wrapper.appendChild(list);

  // Show more / less button
  const btnWrap = document.createElement("div");
  btnWrap.className = "tw-mt-2 tw-flex tw-justify-center";
  wrapper.appendChild(btnWrap);

  let filtered = history;
  let showingAll = false;

  function render(data, count = INITIAL_DISPLAY) {
    list.innerHTML = "";
    if (data.length === 0) {
      list.innerHTML =
        '<div class="tw-text-xs tw-text-[#666] dark:tw-text-gray-400 tw-text-center tw-py-3">No friend changes recorded yet.</div>';
      return;
    }

    const slice = data.slice(0, count);
    const loading = document.createElement("div");
    loading.className = "tw-text-xs tw-text-gray-500 dark:tw-text-gray-400 tw-text-center tw-py-1";
    loading.textContent = "Loading…";
    list.appendChild(loading);

    (async () => {
      for (const entry of slice) {
        list.appendChild(await createHistoryItem(entry));
      }
      loading.remove();
    })().catch(() => {
      loading.textContent = "Error loading friend details";
      loading.className = "tw-text-xs tw-text-red-500 dark:tw-text-red-400 tw-text-center tw-py-1";
    });
  }

  function updateBtn() {
    btnWrap.innerHTML = "";
    if (filtered.length <= INITIAL_DISPLAY) return;
    const btn = document.createElement("button");
    btn.className =
      "tw-px-3 tw-py-1.5 tw-bg-[#e5e5e5] hover:tw-bg-[#d0d0d0] dark:tw-bg-[#404040] dark:hover:tw-bg-[#505050] tw-text-[#1c1c1c] dark:tw-text-gray-200 tw-rounded-lg tw-transition-colors tw-text-xs tw-font-medium";
    btn.textContent = showingAll ? "Show Less" : `Show All (${filtered.length})`;
    btn.addEventListener("click", async () => {
      if (!showingAll) {
        for (const entry of filtered.slice(INITIAL_DISPLAY)) {
          list.appendChild(await createHistoryItem(entry));
        }
        showingAll = true;
      } else {
        const items = list.querySelectorAll("[data-history-item]");
        for (let i = INITIAL_DISPLAY; i < items.length; i++) items[i].remove();
        showingAll = false;
      }
      updateBtn();
    });
    btnWrap.appendChild(btn);
  }

  function applyFilter() {
    filtered = filterHistoryByDate(history, fromInput.value, toInput.value);
    showingAll = false;
    render(filtered);
    updateBtn();
  }

  fromInput.addEventListener("change", applyFilter);
  toInput.addEventListener("change", applyFilter);
  clearBtn.addEventListener("click", () => {
    fromInput.value = "";
    toInput.value = "";
    applyFilter();
  });

  render(filtered);
  updateBtn();
  return wrapper;
}

// ── History item (async — fetches user data) ────────────────────────

async function fetchUserData(userIds) {
  if (!userIds || userIds.length === 0) return [];
  const unique = [...new Set(userIds.map((id) => String(id)))];
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ type: "GET_ROBLOX_USERS_DATA", userIds: unique }, (res) => {
      resolve(res?.success && res.users ? res.users : []);
    });
  });
}

function createFriendChip(userId, userData, isAdded) {
  const chip = document.createElement("div");
  chip.className = "tw-flex tw-items-center tw-gap-1.5 tw-py-0.5";

  if (userData?.thumbnailUrl) {
    const img = document.createElement("img");
    img.className = "tw-w-6 tw-h-6 tw-rounded-full tw-shrink-0";
    img.alt = userData.name || `User ${userId}`;
    img.src = userData.thumbnailUrl;
    chip.appendChild(img);
  } else {
    const ph = document.createElement("div");
    ph.className = "tw-w-6 tw-h-6 tw-rounded-full tw-shrink-0 tw-bg-gray-300 dark:tw-bg-gray-600 tw-flex tw-items-center tw-justify-center tw-text-xs";
    ph.textContent = "?";
    chip.appendChild(ph);
  }

  const link = document.createElement("a");
  link.href = `https://www.roblox.com/users/${userId}/profile`;
  link.target = "_blank";
  link.className = `tw-text-xs tw-font-medium hover:tw-underline ${isAdded ? "tw-text-green-600 dark:tw-text-green-400" : "tw-text-red-600 dark:tw-text-red-400"}`;
  link.textContent = userData?.name || `User ${userId}`;
  chip.appendChild(link);

  return chip;
}

async function createHistoryItem(entry) {
  const item = document.createElement("div");
  item.setAttribute("data-history-item", "true");
  item.className =
    "tw-bg-white dark:tw-bg-[#353840] tw-border tw-border-[#e5e5e5] dark:tw-border-transparent tw-p-2 tw-rounded-lg hover:tw-bg-[#f5f5f5] dark:hover:tw-bg-[#404650] tw-transition-colors";

  const allIds = [...(entry.added || []), ...(entry.removed || [])];
  const userMap = {};
  if (allIds.length > 0) {
    for (const u of await fetchUserData(allIds)) {
      if (u?.id) userMap[String(u.id)] = u;
    }
  }

  // Top row
  const top = document.createElement("div");
  top.className = "tw-flex tw-items-center tw-justify-between tw-mb-1.5";
  const ts = document.createElement("span");
  ts.className = "tw-text-xs tw-text-gray-500 dark:tw-text-gray-400";
  ts.textContent = formatTimestamp(entry.timestamp);
  const cnt = document.createElement("span");
  cnt.className = "tw-text-xs tw-text-gray-600 dark:tw-text-gray-300";
  cnt.textContent = `${entry.currentCount} (was ${entry.previousCount})`;
  top.appendChild(ts);
  top.appendChild(cnt);
  item.appendChild(top);

  const changes = document.createElement("div");
  changes.className = "tw-space-y-1";

  for (const [ids, isAdded, symbol] of [
    [entry.added, true, "+"],
    [entry.removed, false, "-"],
  ]) {
    if (!ids?.length) continue;
    const row = document.createElement("div");
    row.className = "tw-flex tw-items-center tw-gap-2 tw-flex-wrap";
    const label = document.createElement("span");
    label.className = `tw-text-xs tw-font-semibold ${isAdded ? "tw-text-green-600 dark:tw-text-green-400" : "tw-text-red-600 dark:tw-text-red-400"}`;
    label.textContent = `${symbol}${ids.length}:`;
    row.appendChild(label);
    for (const id of ids) row.appendChild(createFriendChip(id, userMap[String(id)], isAdded));
    changes.appendChild(row);
  }

  item.appendChild(changes);
  return item;
}

// ── Public entry point ──────────────────────────────────────────────

let messageListenerSetup = false;

function setupMessageListener() {
  if (messageListenerSetup) return;
  messageListenerSetup = true;

  chrome.runtime.onMessage.addListener((message) => {
    if (message.type === "FRIEND_TRACKING_CHANGED") {
      const uid = getUserID();
      if (uid && String(message.userId) === String(uid)) {
        refreshHistoryWidget();
      }
    }
  });

  document.addEventListener("friendTrackingStarted", (event) => {
    const uid = getUserID();
    if (uid && String(event.detail?.userId) === String(uid)) {
      refreshHistoryWidget();
    }
  });
}

async function refreshHistoryWidget() {
  const selectors = await getProfileSelectors();
  let root = null;
  for (const sel of selectors.profileRoot || []) {
    root = document.querySelector(sel);
    if (root) break;
  }
  if (root) addFriendTrackingHistory(root);
}

export async function addFriendTrackingHistory(element) {
  const userId = getUserID();
  if (!userId) return;

  setupMessageListener();

  const data = await chrome.storage.local.get(["betterblox_friend_tracking"]);
  const tracking = data["betterblox_friend_tracking"] || {};
  const isActive = tracking[String(userId)]?.isTracking === true;

  // Remove any existing widget
  const existing = document.querySelector("[data-betterblox-friend-tracking-history]");
  if (existing) existing.remove();

  if (!isActive) return;

  chrome.runtime.sendMessage(
    { type: "GET_FRIEND_TRACKING_HISTORY", userId: String(userId) },
    (response) => {
      if (!response?.success) return;

      const widget = createHistoryWidget(response.history || []);
      widget.setAttribute("data-betterblox-friend-tracking-history", "true");

      // Insert inside the existing BetterBLOX Time Statistics container
      const statsContainer = document.querySelector(".bblox-stats-container");
      if (statsContainer) {
        statsContainer.appendChild(widget);
        return;
      }

      // Fallback: insert after profile header (for users without presence data)
      getProfileSelectors().then((selectors) => {
        const insertSel = selectors.profileHeaderInsert;
        const headerInner =
          (insertSel && (element.querySelector(insertSel) || document.querySelector(insertSel))) || null;
        const headerContainer = headerInner?.parentNode;
        if (headerContainer?.id === "user-profile-header-bg") {
          headerContainer.parentNode.insertBefore(widget, headerContainer.nextSibling);
          return;
        }
        if (headerInner) {
          headerInner.appendChild(widget);
          return;
        }
        const fallbacks = selectors.profileHeaderInsertFallback || [];
        for (const sel of fallbacks) {
          const header = element.querySelector(sel) || document.querySelector(sel);
          if (header) {
            header.parentNode.insertBefore(widget, header.nextSibling);
            return;
          }
        }
      });
    }
  );
}
