import { browserAPI } from "./browserAPI.js";

class StorageManager {
  constructor() {
    this.listeners = new Map();
    this.PREFIX = "betterblox_";
  }

  getPrefixedKey(key) {
    return key.startsWith(this.PREFIX) ? key : `${this.PREFIX}${key}`;
  }

  async initialize() {
    browserAPI.storage.onChanged.addListener((changes, namespace) => {
      // Data is written to storage.local (see get()/set()), so cross-context
      // change notifications must watch the 'local' namespace, not 'sync'.
      if (namespace === "local") {
        Object.entries(changes).forEach(([key, { newValue }]) => {
          this.notifyListeners(key, newValue);
        });
      }
    });
  }

  async get(key, defaultValue = null, force = false) {
    const prefixedKey = this.getPrefixedKey(key);

    try {
      // Try to get with prefixed key
      const result = await browserAPI.storage.local.get(prefixedKey);
      if (result[prefixedKey] !== undefined) {
        return result[prefixedKey];
      }

      // If not found, try without prefix (for backward compatibility)
      if (force) return defaultValue;

      const fallbackResult = await browserAPI.storage.local.get(key);

      if (fallbackResult[key] !== undefined) {
        console.warn("Fallback Result Considered for", key, fallbackResult);
        const value = fallbackResult[key];
        return value;
      }

      return defaultValue;
    } catch (error) {
      console.error("Error getting setting:", error);
      return defaultValue;
    }
  }

  async set(key, value) {
    const prefixedKey = this.getPrefixedKey(key);
    try {
      await browserAPI.storage.local.set({ [prefixedKey]: value });
      this.notifyListeners(prefixedKey, value);
    } catch (error) {
      console.error("Error setting setting:", error);
    }
  }

  addListener(key, callback) {
    const prefixedKey = this.getPrefixedKey(key);
    if (!this.listeners.has(prefixedKey)) {
      this.listeners.set(prefixedKey, new Set());
    }
    this.listeners.get(prefixedKey).add(callback);
  }

  removeListener(key, callback) {
    const prefixedKey = this.getPrefixedKey(key);
    if (this.listeners.has(prefixedKey)) {
      this.listeners.get(prefixedKey).delete(callback);
    }
  }

  notifyListeners(key, value) {
    if (this.listeners.has(key)) {
      this.listeners.get(key).forEach((callback) => callback(value));
    }
  }

  async getSettings(key, defaultValue = null) {
    const value = await this.get(`settings_${key}`, defaultValue, true);
    if (value === undefined && defaultValue) {
      this.set(`settings_${key}`, defaultValue);
      return defaultValue;
    }

    return value;
  }
  async setSettings(key, value) {
    await this.set(`settings_${key}`, value);
  }
}

export const storageManager = new StorageManager();
