import { getProfileSelectors } from "../../../../core/profileSelectors.js";
import { storageManager } from "../../../../core/storageManager.js";

function getUserID() {
  try {
    const url = window.location.href;
    const match = url.match(/\/users\/(\d+)\/profile/);
    if (match && match[1]) return match[1];
    return null;
  } catch (error) {
    console.error("Profile track option: Error getting user ID from URL:", error);
    return null;
  }
}

function idInList(list, userId) {
  const s = String(userId);
  return list.some((id) => String(id) === s);
}

function getAuthentificatedUserID() {
  try {
    const metaTag = document.querySelector('meta[name="user-data"]');
    if (metaTag && metaTag.getAttribute("data-userid")) {
      const id = parseInt(metaTag.getAttribute("data-userid"), 10);
      if (!isNaN(id)) return id;
    }
    return null;
  } catch (_) {
    return null;
  }
}

/** Same source as presence/ui_cardProfile.js — friends are auto-tracked for presence. */
async function isUserInFriendsList(profileUserId) {
  const authId = getAuthentificatedUserID();
  if (authId == null) return false;
  const friendsListRaw = await storageManager.get("betterblox_friends_list", {});
  const friendsList = friendsListRaw[authId] || { friendIds: [] };
  return idInList(friendsList.friendIds || [], profileUserId);
}

function profileMenuAlreadyInjected(container) {
  return (
    container.querySelector("[data-betterblox-profile-menu-item]") != null ||
    container.getAttribute("data-betterblox-profile-menu-done") === "true"
  );
}

async function checkNotifyOnlineStatus(userId) {
  const notifyOnline = await storageManager.get("notifyOnline", []);
  return idInList(notifyOnline, userId);
}

async function toggleNotifyOnline(userId) {
  const notifyOnline = await storageManager.get("notifyOnline", []);
  const s = String(userId);
  let next;
  if (idInList(notifyOnline, userId)) {
    next = notifyOnline.filter((id) => String(id) !== s);
  } else {
    next = [...notifyOnline, s];
  }
  await storageManager.set("notifyOnline", next);
  return idInList(next, userId);
}

async function checkAutoJoinStatus(userId) {
  const autoJoin = await storageManager.get("autoJoin", []);
  return idInList(autoJoin, userId);
}

async function toggleAutoJoin(userId) {
  const autoJoin = await storageManager.get("autoJoin", []);
  const s = String(userId);
  let next;
  if (idInList(autoJoin, userId)) {
    next = autoJoin.filter((id) => String(id) !== s);
  } else {
    next = [...autoJoin, s];
  }
  await storageManager.set("autoJoin", next);
  return idInList(next, userId);
}

async function checkFriendTrackingStatus(userId) {
  const data = await chrome.storage.local.get(["betterblox_friend_tracking"]);
  const tracking = data["betterblox_friend_tracking"] || {};
  return tracking[String(userId)]?.isTracking === true;
}

function sendTrackingMessage(type, userId) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ type, userId: String(userId) }, (res) => {
      resolve(res || { success: false });
    });
  });
}

function showFriendsPrivateAlert() {
  const existing = document.getElementById("bblox-friends-private-alert");
  if (existing) existing.remove();

  const overlay = document.createElement("div");
  overlay.id = "bblox-friends-private-alert";
  overlay.className =
    "tw-fixed tw-inset-0 tw-z-[99999] tw-flex tw-items-center tw-justify-center tw-bg-black/40";

  const card = document.createElement("div");
  card.className =
    "tw-bg-white dark:tw-bg-[#2a2d30] tw-rounded-xl tw-border tw-border-[#e5e5e5] dark:tw-border-[#3a3d40] tw-shadow-lg tw-p-6 tw-max-w-sm tw-mx-4 tw-text-center";
  card.innerHTML = `
    <div class="tw-text-4xl tw-mb-3">🔒</div>
    <h3 class="tw-text-base tw-font-semibold tw-text-[#1c1c1c] dark:tw-text-gray-200 tw-mb-2">Friend List is Private</h3>
    <p class="tw-text-sm tw-text-[#666] dark:tw-text-gray-400 tw-mb-4">This user has their friend list hidden on Roblox. BetterBLOX cannot track friend changes for users with private friend lists.</p>
    <button type="button" class="tw-px-4 tw-py-2 tw-bg-[#0095ff] hover:tw-bg-[#0080e0] tw-text-white tw-rounded-lg tw-text-sm tw-font-medium tw-transition-colors">Got it</button>
  `;
  card.querySelector("button").addEventListener("click", () => overlay.remove());
  overlay.addEventListener("click", (e) => { if (e.target === overlay) overlay.remove(); });

  overlay.appendChild(card);
  document.body.appendChild(overlay);
}

function isProfileDropdownContainer(el) {
  if (!el || typeof el.textContent !== "string") return false;
  const t = el.textContent;
  return t.includes("Inventory") && t.includes("Favorites");
}

async function findProfileMenuContainer(target = document) {
  const selectors = await getProfileSelectors();
  const popupList = selectors.profilePopup || [];
  for (const sel of popupList) {
    try {
      const candidates = target.querySelectorAll(sel);
      for (const el of candidates) {
        if (!isProfileDropdownContainer(el) || profileMenuAlreadyInjected(el)) continue;
        if (el.closest("#user-profile-header-bg")) return el;
      }
      for (const el of candidates) {
        if (isProfileDropdownContainer(el) && !profileMenuAlreadyInjected(el)) return el;
      }
    } catch (_) {}
  }
  const menus = target.querySelectorAll('ul[role="menu"]');
  for (const menu of menus) {
    if (!profileMenuAlreadyInjected(menu) && isProfileDropdownContainer(menu)) return menu;
  }
  return null;
}

const processingMenus = new WeakSet();

/** Single body observer shared across invocations — disconnect any prior one so observers don't stack on profile re-renders. */
let profileMenuObserver = null;

/** Profile "…" menu: Track first, then optional Notify when Online & Game Join Notifications. */
export async function addProfileTrackUserOptions(element) {
  const userId = getUserID();
  if (!userId) return;

  const menuButtonSelectors = [
    'button[aria-label*="More"]',
    'button[aria-label*="more"]',
    'button[aria-label*="Menu"]',
    'button[aria-label*="menu"]',
    '[data-testid*="menu"]',
    '[data-testid*="Menu"]',
    '[class*="icon-more"]',
    '[class*="IconMore"]',
    '[class*="more-button"]',
    '[class*="MoreButton"]',
    '[class*="menu-button"]',
    '[class*="MenuButton"]',
  ];

  let menuButton = null;
  for (const selector of menuButtonSelectors) {
    menuButton = element.querySelector(selector) || document.querySelector(selector);
    if (menuButton) break;
  }

  // Tear down any observer from a prior invocation before creating a new one,
  // otherwise repeated calls (profile header re-renders) stack body-wide observers.
  if (profileMenuObserver) profileMenuObserver.disconnect();

  let observerTimeout = null;
  profileMenuObserver = new MutationObserver(() => {
    if (observerTimeout) clearTimeout(observerTimeout);
    observerTimeout = setTimeout(() => {
      findProfileMenuContainer(document).then((container) => {
        if (container && !processingMenus.has(container) && !profileMenuAlreadyInjected(container)) {
          processingMenus.add(container);
          addMenuItemsToContainer(container, userId).then(() => processingMenus.delete(container));
        }
      });
    }, 100);
  });

  profileMenuObserver.observe(document.body, { childList: true, subtree: true });

  if (menuButton) {
    const clickHandler = () => {
      setTimeout(() => {
        findProfileMenuContainer(document).then((container) => {
          if (container && !processingMenus.has(container) && !profileMenuAlreadyInjected(container)) {
            processingMenus.add(container);
            addMenuItemsToContainer(container, userId).then(() => processingMenus.delete(container));
          }
        });
      }, 150);
    };
    menuButton.addEventListener("click", clickHandler, { once: false });
  }

  findProfileMenuContainer(document).then((existingContainer) => {
    if (existingContainer && !processingMenus.has(existingContainer) && !profileMenuAlreadyInjected(existingContainer)) {
      processingMenus.add(existingContainer);
      addMenuItemsToContainer(existingContainer, userId).then(() => processingMenus.delete(existingContainer));
    }
  });

  element.setAttribute("data-betterblox-track-user-profile", "true");
}

const TW_RADIX_MENU_BTN =
  "tw-block tw-w-full tw-py-2 tw-px-3 tw-text-left tw-text-sm tw-bg-transparent tw-border-0 tw-rounded-md tw-cursor-pointer tw-font-inherit tw-transition-colors hover:tw-bg-[#f0f0f0] dark:hover:tw-bg-[#353840] tw-text-[#1c1c1c] dark:tw-text-gray-200";

const TW_LI_MENU_ROW =
  "tw-flex tw-items-center tw-px-3 tw-py-2 tw-cursor-pointer tw-rounded-md tw-transition-colors hover:tw-bg-[#f0f0f0] dark:hover:tw-bg-[#353840] tw-outline-none";

function setRowLabelText(rootEl, isRadix, text) {
  const el = isRadix ? rootEl : rootEl.querySelector(".profile-header-dropdown-label") || rootEl;
  el.textContent = text;
}

async function addMenuItemsToContainer(container, userId) {
  if (profileMenuAlreadyInjected(container)) return Promise.resolve();

  const isUlMenu = container.tagName === "UL" && container.getAttribute("role") === "menu";
  const isDiv = container.tagName === "DIV";
  if (!isUlMenu && !isDiv) return Promise.resolve();

  const [betterBloxTracking, friendsOnlineNotifyEnabled, autoJoinEnabled, isFriend] =
    await Promise.all([
      storageManager.get("betterblox_tracking_list_v2", []),
      storageManager.getSettings("friends-online-notify", true),
      storageManager.getSettings("auto-join", true),
      isUserInFriendsList(userId),
    ]);

  const [isTracking, notifyOn, autoJoinOn, friendTrackingOn] = await Promise.all([
    Promise.resolve(idInList(betterBloxTracking, userId)),
    friendsOnlineNotifyEnabled ? checkNotifyOnlineStatus(userId) : Promise.resolve(false),
    autoJoinEnabled ? checkAutoJoinStatus(userId) : Promise.resolve(false),
    checkFriendTrackingStatus(userId),
  ]);

  const createItem = (label, activeLabel, active, attr, onClick) =>
    createMenuItem(label, activeLabel, active, attr, onClick, isDiv);

  const items = [];

  if (!isFriend) {
    const trackMenuItem = createItem(
      "Track",
      "Untrack",
      isTracking,
      "[data-betterblox-track]",
      async () => {
        const currentTracking = await storageManager.get("betterblox_tracking_list_v2", []);
        const currentlyTracking = idInList(currentTracking, userId);
        const newIsTracking = !currentlyTracking;
        const uid = String(userId);

        if (newIsTracking) {
          await storageManager.set("betterblox_tracking_list_v2", [...currentTracking, uid]);
        } else {
          await storageManager.set(
            "betterblox_tracking_list_v2",
            currentTracking.filter((id) => String(id) !== uid)
          );
        }

        setRowLabelText(trackMenuItem, isDiv, newIsTracking ? "Untrack" : "Track");
      }
    );
    items.push(trackMenuItem);
  }

  if (friendsOnlineNotifyEnabled) {
    const off = "Notify when Online";
    const on = "Disable Online Notification";
    const notifyRow = createItem(
      off,
      on,
      notifyOn,
      "[data-betterblox-profile-notify-online]",
      async () => {
        const next = await toggleNotifyOnline(userId);
        setRowLabelText(notifyRow, isDiv, next ? on : off);
      }
    );
    items.push(notifyRow);
  }

  if (autoJoinEnabled) {
    const off = "Game Join Notifications";
    const on = "Disable Join Notifications";
    const joinRow = createItem(
      off,
      on,
      autoJoinOn,
      "[data-betterblox-profile-game-join]",
      async () => {
        const next = await toggleAutoJoin(userId);
        setRowLabelText(joinRow, isDiv, next ? on : off);
      }
    );
    items.push(joinRow);
  }

  {
    const off = "Track Friend Changes";
    const on = "Stop Tracking Friends";
    const ftRow = createItem(
      off,
      on,
      friendTrackingOn,
      "[data-betterblox-profile-friend-tracking]",
      async () => {
        const wasOn = await checkFriendTrackingStatus(userId);
        const msgType = wasOn ? "STOP_FRIEND_TRACKING" : "START_FRIEND_TRACKING";
        const res = await sendTrackingMessage(msgType, userId);
        if (!res.success) {
          if (res.error === "FRIENDS_PRIVATE") {
            showFriendsPrivateAlert();
          }
          return;
        }
        setRowLabelText(ftRow, isDiv, wasOn ? off : on);
        if (!wasOn) {
          setTimeout(() => {
            document.dispatchEvent(
              new CustomEvent("friendTrackingStarted", { detail: { userId } })
            );
          }, 1000);
        } else {
          const hist = document.querySelector("[data-betterblox-friend-tracking-history]");
          if (hist) hist.remove();
        }
      }
    );
    items.push(ftRow);
  }

  if (items.length === 0) {
    container.setAttribute("data-betterblox-profile-menu-done", "true");
    return Promise.resolve();
  }

  /** Insert in array order so Track stays first when present (each row is inserted before the first native menu item). */
  if (isDiv) {
    const anchor = container.firstChild;
    for (let i = 0; i < items.length; i++) {
      container.insertBefore(items[i], anchor);
    }
  } else {
    let firstMenuItem = null;
    for (let i = 0; i < container.children.length; i++) {
      const child = container.children[i];
      if (child.tagName === "LI" && child.getAttribute("role") === "menuitem") {
        firstMenuItem = child;
        break;
      }
    }
    const anchor = firstMenuItem || container.firstChild;
    for (let i = 0; i < items.length; i++) {
      container.insertBefore(items[i], anchor);
    }
  }

  return Promise.resolve();
}

function createMenuItem(labelText, activeLabelText, isActive, dataAttribute, onClickHandler, isRadix = false) {
  const attrName = dataAttribute.replace(/[\[\]]/g, "");

  if (isRadix) {
    const menuItem = document.createElement("button");
    menuItem.setAttribute("data-betterblox-profile-menu-item", "true");
    menuItem.setAttribute(attrName, "true");
    menuItem.setAttribute("type", "button");
    menuItem.setAttribute("role", "menuitem");
    menuItem.className = TW_RADIX_MENU_BTN;
    menuItem.textContent = isActive ? activeLabelText : labelText;
    menuItem.addEventListener("click", async (e) => {
      e.stopPropagation();
      e.preventDefault();
      try {
        await onClickHandler();
      } catch (err) {
        console.error("Profile menu: click error:", err);
      }
      setTimeout(() => document.body.click(), 100);
    });
    return menuItem;
  }

  const menuItem = document.createElement("li");
  menuItem.setAttribute("data-betterblox-profile-menu-item", "true");
  menuItem.setAttribute(attrName, "true");
  menuItem.setAttribute("role", "menuitem");
  menuItem.setAttribute("tabindex", "-1");
  menuItem.className = TW_LI_MENU_ROW;

  const labelSpan = document.createElement("span");
  labelSpan.className =
    "profile-header-dropdown-label tw-text-sm tw-text-[#1c1c1c] dark:tw-text-gray-200";
  labelSpan.textContent = isActive ? activeLabelText : labelText;

  menuItem.appendChild(labelSpan);

  menuItem.addEventListener("click", async (e) => {
    e.stopPropagation();
    e.preventDefault();
    try {
      await onClickHandler();
    } catch (error) {
      console.error("Profile menu: click error:", error);
    }
  });

  return menuItem;
}
