import { addPresenceStatusFriendList, addPresenceStatusFriendListInitial } from "./ui_friendlist.js";
import { addPresenceStatusProfile, addPresenceStatusProfileInitial } from "./ui_friendprofile.js";
import { addPresenceStatus, addPresenceStatusInitial } from "./ui_home.js";

import { addPresenceStatusCardProfile, addTimeContainer } from "./ui_cardProfile.js";

import { getProfileSelectors } from "../../../../core/profileSelectors.js";
import { addProfileTrackUserOptions } from "../friendTracking/profile.js";
import { addFriendTrackingHistory } from "../friendTracking/history.js";

/** Run profile handlers only on the first matching root (avoids cloning Edit Profile / Edit Avatar area). */
async function runProfileHandlersOnce(element, currentPage) {
  if (currentPage !== "profile") return;
  const selectors = await getProfileSelectors();
  let firstRoot = null;
  for (const sel of selectors.profileRoot) {
    try {
      firstRoot = document.querySelector(sel);
      if (firstRoot) break;
    } catch (_) {}
  }
  if (!firstRoot || element !== firstRoot) return;
  await addTimeContainer(element);
  addProfileTrackUserOptions(element);
  addFriendTrackingHistory(element);
}

const presenceModule = {
  pages: ["home", "profile", "friends"],
  selectors: [
    {
      selector: "a.friends-carousel-tile-labels",
      handler: (element, currentPage) => {
        if (currentPage != "home") return;
        addPresenceStatusInitial(element);
      },
    },
    {
      selector: "li.avatar-card",
      handler: (element, currentPage) => {
        if (currentPage != "friends") return;
        addPresenceStatusFriendListInitial(element);
      },
    },
    {
      selector: "#user-profile-header-bg",
      handler: (element, currentPage) => runProfileHandlersOnce(element, currentPage),
    },
    {
      selector: "#treatment-redesigned-header",
      handler: (element, currentPage) => runProfileHandlersOnce(element, currentPage),
    },
    {
      selector: "#profile-header-container",
      handler: (element, currentPage) => runProfileHandlersOnce(element, currentPage),
    },
  ],

  handlePresenceUpdate(presenceData) {
    const subLabels = document.querySelectorAll("a.friends-carousel-tile-labels");
    subLabels.forEach((subLabel) => {
      addPresenceStatus(subLabel, presenceData);
    });

    const friendListItems = document.querySelectorAll("li.avatar-card");
    friendListItems.forEach((friendListItem) => {
      addPresenceStatusFriendList(friendListItem, presenceData);
    });

    getProfileSelectors().then((selectors) => {
      let cardProfileContainer = null;
      for (const sel of selectors.profileRoot) {
        try {
          cardProfileContainer = document.querySelector(sel);
          if (cardProfileContainer) break;
        } catch (_) {}
      }
      if (cardProfileContainer) {
        addPresenceStatusCardProfile(cardProfileContainer, presenceData);
      }
    });
  },

  async initialize() {
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.type === "PRESENCE_TRACKER_UPDATED") {
        this.handlePresenceUpdate(message.data);
      }
    });
  },
};

export default presenceModule;
