// Use Chrome extension storage API
// No need to initialize a store instance as we'll use chrome.storage directly

/**
 * Gets data from storage by key
 * @param {string} key - The key to retrieve data for
 * @returns {Promise<any>} The stored data or null if not found
 */
export async function getData(key) {
  return new Promise((resolve) => {
    try {
      chrome.storage.local.get(key, (result) => {
        const data = result[key];
        resolve(data !== undefined ? data : null);
      });
    } catch (error) {
      console.error(`Failed to get data for key ${key}:`, error);
      resolve(null);
    }
  });
}

/**
 * Sets data in storage
 * @param {string} key - The key to store data under
 * @param {any} data - The data to store
 * @returns {Promise<boolean>} Success status
 */
export async function setData(key, data) {
  return new Promise((resolve) => {
    try {
      const item = {};
      item[key] = data;
      chrome.storage.local.set(item, () => {
        console.log(`Data saved for key: ${key}`);
        resolve(true);
      });
    } catch (error) {
      console.error(`Failed to set data for key ${key}:`, error);
      resolve(false);
    }
  });
}

/**
 * Deletes data from storage
 * @param {string} key - The key to delete
 * @returns {Promise<boolean>} Success status
 */
export async function deleteData(key) {
  return new Promise((resolve) => {
    try {
      chrome.storage.local.remove(key, () => {
        console.log(`Data deleted for key: ${key}`);
        resolve(true);
      });
    } catch (error) {
      console.error(`Failed to delete data for key ${key}:`, error);
      resolve(false);
    }
  });
}
