import { getPNGIcon } from "../../utils/iconManager.js";
import { injectTailwindStyles } from "../../utils/injectTailwind.js";
import { API_BASE_URL } from "../../../betterblox-background/constants.js";

const remotePopupModule = {
  async initialize() {
    try {
      // Get installation status and seen popups
      const { installedBefore, seenRemotePopups = [] } = await chrome.storage.local.get(["installedBefore", "seenRemotePopups"]);

      // Only show remote popups if user has already seen welcome popup
      if (installedBefore) {
        // Check for new remote popups
        await this.checkForRemotePopups(seenRemotePopups);
      }
    } catch (error) {
      console.error("Error checking remote popups:", error);
    }
  },

  async checkForRemotePopups(seenRemotePopups) {
    try {
      // Fetch popups from API
      const response = await fetch(`${API_BASE_URL}/api/popup/remote`);

      if (!response.ok) {
        throw new Error(`API request failed: ${response.status}`);
      }

      const apiResponse = await response.json();

      if (!apiResponse.success) {
        throw new Error(`API returned error: ${apiResponse.error}`);
      }

      // Get extension version for filtering
      const manifest = chrome.runtime.getManifest();
      const currentVersion = manifest.version;

      // Filter popups that should be shown
      const eligiblePopups = apiResponse.popups.filter((popup) => {
        // Check if already seen
        if (popup.showOnce && seenRemotePopups.includes(popup.id)) {
          return false;
        }

        // Check date range
        const now = new Date();
        const currentDate = now.toISOString().split("T")[0]; // YYYY-MM-DD format

        if (popup.startDate && currentDate < popup.startDate) {
          return false;
        }

        if (popup.endDate && currentDate > popup.endDate) {
          return false;
        }

        // Check version constraints
        if (popup.minVersion && this.compareVersions(currentVersion, popup.minVersion) < 0) {
          return false;
        }

        if (popup.maxVersion && this.compareVersions(currentVersion, popup.maxVersion) > 0) {
          return false;
        }

        return true;
      });

      // Sort by priority (lower number = higher priority)
      eligiblePopups.sort((a, b) => a.priority - b.priority);

      // Show the highest priority popup
      if (eligiblePopups.length > 0) {
        const popupToShow = eligiblePopups[0];

        // Wait for DOM to be ready
        if (document.readyState === "loading") {
          document.addEventListener("DOMContentLoaded", () => this.showRemotePopup(popupToShow, seenRemotePopups));
        } else {
          this.showRemotePopup(popupToShow, seenRemotePopups);
        }
      }
    } catch (error) {
      console.error("Error fetching remote popups:", error);
    }
  },

  compareVersions(version1, version2) {
    const v1parts = version1.split(".").map(Number);
    const v2parts = version2.split(".").map(Number);

    for (let i = 0; i < Math.max(v1parts.length, v2parts.length); i++) {
      const v1part = v1parts[i] || 0;
      const v2part = v2parts[i] || 0;

      if (v1part < v2part) return -1;
      if (v1part > v2part) return 1;
    }

    return 0;
  },

  async showRemotePopup(popupData, seenRemotePopups) {
    injectTailwindStyles();

    try {
      const popup = document.createElement("div");
      popup.id = "remote-popup-modal";
      popup.setAttribute("tabindex", "-1");
      popup.setAttribute("aria-hidden", "false");
      popup.className = "tw-overflow-y-auto tw-overflow-x-hidden tw-fixed tw-top-0 tw-right-0 tw-left-0 tw-z-50 tw-flex tw-justify-center tw-items-center tw-w-full md:tw-inset-0 tw-h-full tw-max-h-full tw-bg-gray-900/50";

      popup.innerHTML = `
        <div class="tw-relative tw-p-4 tw-w-full tw-max-w-4xl tw-max-h-full">
          <div class="tw-relative tw-bg-white tw-rounded-lg tw-shadow dark:tw-bg-gray-700">
            <!-- Modal header -->
            <div class="tw-flex tw-items-center tw-justify-between tw-p-4 md:tw-p-5 tw-rounded-t dark:tw-border-gray-600 tw-bg-gray-50 dark:tw-bg-gray-700" style="border-bottom: solid">
              <h3 class="tw-text-xl tw-font-semibold tw-text-gray-900 dark:tw-text-white tw-flex tw-items-center tw-gap-2">
                <img src="${getPNGIcon("logo32")}" alt="BetterBLOX Logo" class="tw-w-5 tw-h-5" />
                ${popupData.title}
              </h3>
              <button type="button" id="closeRemotePopup" class="tw-border-none tw-text-gray-400 tw-bg-transparent hover:tw-bg-gray-200 hover:tw-text-gray-900 tw-rounded-lg tw-text-sm tw-w-8 tw-h-8 tw-ms-auto tw-inline-flex tw-justify-center tw-items-center dark:hover:tw-bg-gray-600 dark:hover:tw-text-white tw-transition-colors tw-duration-200">
                <svg class="tw-w-3 tw-h-3" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 14 14">
                  <path stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m1 1 6 6m0 0 6 6M7 7l6-6M7 7l-6 6" />
                </svg>
                <span class="tw-sr-only">Close modal</span>
              </button>
            </div>
            <!-- Modal body -->
            <div class="tw-p-4 md:tw-p-5">
              <div class="tw-mb-4">
                <iframe 
                  src="${popupData.url}" 
                  class="tw-w-full tw-h-[70vh] tw-border-0 tw-rounded-lg"
                  title="${popupData.title}"
                  sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox"
                  loading="lazy">
                </iframe>
              </div>
               <div class="tw-flex tw-justify-end">
                 <button id="closeRemoteButton" class="tw-border-none tw-text-white tw-inline-flex tw-justify-center tw-items-center tw-bg-blue-700 hover:tw-bg-blue-800 focus:tw-ring-4 focus:tw-outline-none focus:tw-ring-blue-300 tw-font-medium tw-rounded-lg tw-text-sm tw-px-5 tw-py-2.5 tw-text-center dark:tw-bg-blue-600 dark:hover:tw-bg-blue-700 dark:focus:tw-ring-blue-800 tw-transition-colors tw-duration-200">
                   Close
                 </button>
               </div>
            </div>
          </div>
        </div>
      `;

      document.body.appendChild(popup);

      // Add click handlers
      const closePopup = async () => {
        // Mark this popup as seen
        const updatedSeenPopups = [...seenRemotePopups, popupData.id];
        await chrome.storage.local.set({ seenRemotePopups: updatedSeenPopups });
        popup.remove();
      };

      document.getElementById("closeRemotePopup").onclick = () => closePopup();
      document.getElementById("closeRemoteButton").onclick = () => closePopup();
    } catch (error) {
      console.error("Error showing remote popup:", error);
    }
  },
};

export default remotePopupModule;
