import { eventService } from "../../../core/eventService.js";
import { addServerContainer, cleanupServerContainer } from "./bblox_ui.js";
import { storageManager } from "../../../core/storageManager.js";

const CONTAINER_ID = "betterblox-server-filter";

let teardownObserver = null;

/**
 * Roblox is an SPA: leaving a /games/{id} page does not unload the content
 * script, so the globe viewer's timers/WebGL context and the container's
 * document-level click listeners would leak. Watch for our container leaving
 * the DOM and run bbloxUI.cleanup() (which tears down the globe + listeners)
 * before it can be re-created on the next game page.
 */
function watchForContainerRemoval() {
  if (teardownObserver) return; // already watching

  teardownObserver = new MutationObserver(() => {
    if (!document.getElementById(CONTAINER_ID)) {
      teardownObserver.disconnect();
      teardownObserver = null;
      cleanupServerContainer();
    }
  });

  teardownObserver.observe(document.body, { childList: true, subtree: true });
}

const serverCardModule = {
  pages: ["game"],
  selectors: [
    {
      selector: "#running-game-instances-container #rbx-friends-running-games",
      handler: async (element, currentPage) => {
        const betterServers = await storageManager.getSettings(
          "better-servers-list",
          true
        );
        if (!betterServers) return;
        addServerContainer(element);
        watchForContainerRemoval();
      },
    },
    {
      selector: "#roseal-running-game-instances-container #rbx-friends-running-games",
      handler: async (element, currentPage) => {
        const betterServers = await storageManager.getSettings(
          "better-servers-list",
          true
        );
        if (!betterServers) return;
        console.log("Adding server container 16 - testing cache");
        addServerContainer(element);
        watchForContainerRemoval();
      },
    },
  ],
};

export default serverCardModule;
