function formatTimeDifference(timestamp) {
  const now = new Date().getTime();
  const diff = now - timestamp;

  const minutes = Math.floor(diff / (1000 * 60));
  const hours = Math.floor(diff / (1000 * 60 * 60));
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (minutes < 60) return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
  if (hours < 24) return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
  return `${days} day${days !== 1 ? "s" : ""} ago`;
}

function formatPlayTime(ms) {
  if (!ms || ms < 0) return "0m";
  const minutes = Math.floor(ms / (1000 * 60));
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    const remainingMinutes = minutes % 60;
    return `${hours}h${remainingMinutes > 0 ? ` ${remainingMinutes}m` : ""}`;
  }
  return `${minutes}m`;
}

function getUserID() {
  try {
    // Extract user ID from URL like https://www.roblox.com/users/3593578349/profile
    const url = window.location.href;
    const match = url.match(/\/users\/(\d+)\/profile/);

    if (match && match[1]) {
      return parseInt(match[1]);
    }

    console.error("Card Profile: Could not extract user ID from URL:", url);
    return null;
  } catch (error) {
    console.error("Card Profile: Error getting user ID from URL:", error);
    return null;
  }
}

function getAuthentificatedUserID() {
  try {
    // Extract user ID from meta tag: <meta name="user-data" data-userid="7983700857" ...>
    const metaTag = document.querySelector('meta[name="user-data"]');
    if (metaTag && metaTag.getAttribute("data-userid")) {
      const userId = parseInt(metaTag.getAttribute("data-userid"));
      if (!isNaN(userId)) {
        return userId;
      }
    }

    console.error(
      "Card Profile: Could not extract authenticated user ID from meta tag",
    );
    return null;
  } catch (error) {
    console.error(
      "Card Profile: Error getting authenticated user ID from meta tag:",
      error,
    );
    return null;
  }
}

function calculateTimeStatsByPeriod(
  presenceData,
  period,
  customStartTime = null,
  customEndTime = null,
) {
  const now = new Date().getTime();
  let startTime = 0;
  let endTime = now;
  let isCustomRange = false;

  switch (period) {
    case "day":
      return {
        website: presenceData.timeStats.daily.website || 0,
        game: presenceData.timeStats.daily.game || 0,
        studio: presenceData.timeStats.daily.studio || 0,
      };
    case "week":
      startTime = now - 7 * 24 * 60 * 60 * 1000;
      break;
    case "month":
      startTime = now - 30 * 24 * 60 * 60 * 1000;
      break;
    case "custom":
      if (customStartTime && customEndTime) {
        startTime = customStartTime;
        endTime = customEndTime;
        isCustomRange = true;
      } else {
        return { website: 0, game: 0, studio: 0 };
      }
      break;
    case "total":
      return {
        website: presenceData.timeStats.total.website || 0,
        game: presenceData.timeStats.total.game || 0,
        studio: presenceData.timeStats.total.studio || 0,
      };
    default:
      return { website: 0, game: 0, studio: 0 };
  }

  // Calculate from game sessions for week/month/custom
  const stats = { website: 0, game: 0, studio: 0 };

  // Calculate game time from sessions (for week/month/custom)
  if (presenceData.gameHistory && presenceData.gameHistory.games) {
    for (const [placeId, game] of Object.entries(
      presenceData.gameHistory.games,
    )) {
      if (game.sessions && Array.isArray(game.sessions)) {
        // Calculate total wall-clock duration of all sessions for this game
        let totalSessionDuration = 0;
        const validSessions = [];

        for (const session of game.sessions) {
          // Only process sessions with valid startTime and endTime
          if (!session.startTime || !session.endTime) {
            continue;
          }

          const sessionStart = session.startTime;
          const sessionEnd = session.endTime;

          // Check if session overlaps with the date range
          if (sessionStart < endTime && sessionEnd > startTime) {
            // Calculate the portion of the session within the range
            const rangeStart = Math.max(sessionStart, startTime);
            const rangeEnd = Math.min(sessionEnd, endTime);
            const durationInRange = rangeEnd - rangeStart;
            if (durationInRange > 0) {
              validSessions.push({
                session,
                durationInRange,
                fullDuration: sessionEnd - sessionStart,
              });
              totalSessionDuration += sessionEnd - sessionStart;
            }
          }
        }

        // Calculate scaling factor if total session duration exceeds game's totalTime
        // This handles cases where sessions span long periods but actual tracked time is less
        // (e.g., user was offline for periods, so wall-clock time > tracked time)
        const gameTotalTime = game.totalTime || 0;

        // Add session durations, scaling proportionally if needed
        for (const { durationInRange, fullDuration } of validSessions) {
          if (
            totalSessionDuration > 0 &&
            gameTotalTime > 0 &&
            totalSessionDuration > gameTotalTime
          ) {
            // Scale down proportionally: each session contributes its share of totalTime
            // based on what portion of totalSessionDuration it represents
            const sessionContribution =
              (fullDuration / totalSessionDuration) * gameTotalTime;
            // Then scale the durationInRange by the same proportion
            const scaledDuration =
              (durationInRange / fullDuration) * sessionContribution;
            stats.game += scaledDuration;
          } else {
            // No scaling needed - use actual duration in range
            stats.game += durationInRange;
          }
        }
      }
    }

    // Include current game session if active and within range
    if (
      presenceData.gameHistory.currentGame &&
      presenceData.gameHistory.gameStartTime
    ) {
      const sessionStart = presenceData.gameHistory.gameStartTime;
      if (sessionStart < endTime) {
        const rangeStart = Math.max(sessionStart, startTime);
        const rangeEnd = Math.min(now, endTime);
        const durationInRange = rangeEnd - rangeStart;
        if (durationInRange > 0) {
          const currentGame =
            presenceData.gameHistory.games[
              presenceData.gameHistory.currentGame
            ];
          if (currentGame) {
            // Calculate total wall-clock duration including current session
            let totalSessionDuration = 0;
            if (currentGame.sessions && Array.isArray(currentGame.sessions)) {
              for (const session of currentGame.sessions) {
                if (session.startTime && session.endTime) {
                  totalSessionDuration += session.endTime - session.startTime;
                }
              }
            }
            const currentSessionDuration = now - sessionStart;
            totalSessionDuration += currentSessionDuration;

            const gameTotalTime = currentGame.totalTime || 0;
            // Scale current session if total duration exceeds tracked time
            if (
              totalSessionDuration > 0 &&
              gameTotalTime > 0 &&
              totalSessionDuration > gameTotalTime
            ) {
              const sessionContribution =
                (currentSessionDuration / totalSessionDuration) * gameTotalTime;
              const scaledDuration =
                (durationInRange / currentSessionDuration) *
                sessionContribution;
              stats.game += scaledDuration;
            } else {
              stats.game += durationInRange;
            }
          } else {
            stats.game += durationInRange;
          }
        }
      }
    }
  }

  // Calculate website and studio time from sessions (for week/month/custom)
  // Use sessions if available, otherwise fall back to daily averages
  const hasWebsiteSessions =
    presenceData.websiteSessions &&
    Array.isArray(presenceData.websiteSessions) &&
    presenceData.websiteSessions.length > 0;
  const hasStudioSessions =
    presenceData.studioSessions &&
    Array.isArray(presenceData.studioSessions) &&
    presenceData.studioSessions.length > 0;

  if (hasWebsiteSessions) {
    // Calculate website time from sessions
    for (const session of presenceData.websiteSessions) {
      // Only process sessions with valid startTime and endTime
      if (!session.startTime || !session.endTime) {
        continue;
      }

      const sessionStart = session.startTime;
      const sessionEnd = session.endTime;

      // Check if session overlaps with the date range
      if (sessionStart < endTime && sessionEnd > startTime) {
        const rangeStart = Math.max(sessionStart, startTime);
        const rangeEnd = Math.min(sessionEnd, endTime);
        const durationInRange = rangeEnd - rangeStart;
        if (durationInRange > 0) {
          stats.website += durationInRange;
        }
      }
    }

    // Include current website session if active and within range
    if (presenceData.presenceType === 1 && presenceData.websiteStartTime) {
      const sessionStart = presenceData.websiteStartTime;
      if (sessionStart < endTime) {
        const rangeStart = Math.max(sessionStart, startTime);
        const rangeEnd = Math.min(now, endTime);
        const durationInRange = rangeEnd - rangeStart;
        if (durationInRange > 0) {
          stats.website += durationInRange;
        }
      }
    }
  } else {
    // Fall back to daily average estimation for week/month
    if (!isCustomRange) {
      const days = period === "week" ? 7 : 30;
      const dailyWebsite = presenceData.timeStats.daily.website || 0;
      stats.website = Math.min(
        dailyWebsite * days,
        presenceData.timeStats.total.website || 0,
      );
    }
  }

  if (hasStudioSessions) {
    // Calculate studio time from sessions
    for (const session of presenceData.studioSessions) {
      // Only process sessions with valid startTime and endTime
      if (!session.startTime || !session.endTime) {
        continue;
      }

      const sessionStart = session.startTime;
      const sessionEnd = session.endTime;

      // Check if session overlaps with the date range
      if (sessionStart < endTime && sessionEnd > startTime) {
        const rangeStart = Math.max(sessionStart, startTime);
        const rangeEnd = Math.min(sessionEnd, endTime);
        const durationInRange = rangeEnd - rangeStart;
        if (durationInRange > 0) {
          stats.studio += durationInRange;
        }
      }
    }

    // Include current studio session if active and within range
    if (presenceData.presenceType === 3 && presenceData.studioStartTime) {
      const sessionStart = presenceData.studioStartTime;
      if (sessionStart < endTime) {
        const rangeStart = Math.max(sessionStart, startTime);
        const rangeEnd = Math.min(now, endTime);
        const durationInRange = rangeEnd - rangeStart;
        if (durationInRange > 0) {
          stats.studio += durationInRange;
        }
      }
    }
  } else {
    // Fall back to daily average estimation for week/month
    if (!isCustomRange) {
      const days = period === "week" ? 7 : 30;
      const dailyStudio = presenceData.timeStats.daily.studio || 0;
      stats.studio = Math.min(
        dailyStudio * days,
        presenceData.timeStats.total.studio || 0,
      );
    }
  }

  // Cap all stats at total (sanity check - should not be needed if calculations are correct)
  // Only cap if calculated value exceeds total, which indicates a bug
  const totalGame = presenceData.timeStats.total.game || 0;
  const totalWebsite = presenceData.timeStats.total.website || 0;
  const totalStudio = presenceData.timeStats.total.studio || 0;

  if (stats.game > totalGame) {
    console.warn(
      `[TimeStats] Calculated game time (${stats.game}ms) exceeds total (${totalGame}ms) for period ${period}`,
    );
    stats.game = totalGame;
  }
  if (stats.website > totalWebsite) {
    console.warn(
      `[TimeStats] Calculated website time (${stats.website}ms) exceeds total (${totalWebsite}ms) for period ${period}`,
    );
    stats.website = totalWebsite;
  }
  if (stats.studio > totalStudio) {
    console.warn(
      `[TimeStats] Calculated studio time (${stats.studio}ms) exceeds total (${totalStudio}ms) for period ${period}`,
    );
    stats.studio = totalStudio;
  }

  return stats;
}

