function formatTime(ms) {
  if (!ms) return "0m";
  const hours = Math.floor(ms / (1000 * 60 * 60));
  const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
  if (hours === 0) return `${minutes}m`;
  if (minutes === 0) return `${hours}h`;
  return `${hours}h ${minutes}m`;
}

function createGamesList(
  presenceData,
  period,
  customStartTime = null,
  customEndTime = null,
) {
  const games = presenceData.gameHistory?.games || {};
  const now = new Date().getTime();
  let startTime = 0;
  let endTime = now;

  // Determine time range based on period
  switch (period) {
    case "day":
      startTime = new Date().setHours(0, 0, 0, 0);
      break;
    case "week":
      startTime = now - 7 * 24 * 60 * 60 * 1000;
      break;
    case "month":
      startTime = now - 30 * 24 * 60 * 60 * 1000;
      break;
    case "custom":
      if (customStartTime && customEndTime) {
        startTime = customStartTime;
        endTime = customEndTime;
      } else {
        return '<div class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400 tw-text-center tw-py-2">Select date range to view games</div>';
      }
      break;
    case "total":
    default:
      // For total, we'll use totalTime directly
      break;
  }

  // Convert games object to array and calculate time for the period
  const gamesArray = Object.entries(games)
    .map(([id, data]) => {
      let periodTime = 0;

      if (period === "day") {
        periodTime = data.dailyTime || 0;
      } else if (period === "total") {
        periodTime = data.totalTime || 0;
      } else {
        // Calculate from sessions for week/month/custom
        if (data.sessions && Array.isArray(data.sessions)) {
          // Calculate total wall-clock duration of all sessions for this game
          let totalSessionDuration = 0;
          const validSessions = [];

          for (const session of data.sessions) {
            // Only process sessions with valid startTime and endTime
            if (!session.startTime || !session.endTime) {
              continue;
            }

            const sessionStart = session.startTime;
            const sessionEnd = session.endTime;

            // Check if session overlaps with the date range
            if (sessionStart < endTime && sessionEnd > startTime) {
              // Calculate the portion of the session within the range
              const rangeStart = Math.max(sessionStart, startTime);
              const rangeEnd = Math.min(sessionEnd, endTime);
              const durationInRange = rangeEnd - rangeStart;
              if (durationInRange > 0) {
                validSessions.push({
                  durationInRange,
                  fullDuration: sessionEnd - sessionStart,
                });
                totalSessionDuration += sessionEnd - sessionStart;
              }
            }
          }

          // Scale sessions proportionally if total duration exceeds game's totalTime
          const gameTotalTime = data.totalTime || 0;
          for (const { durationInRange, fullDuration } of validSessions) {
            if (
              totalSessionDuration > 0 &&
              gameTotalTime > 0 &&
              totalSessionDuration > gameTotalTime
            ) {
              // Scale down proportionally
              const sessionContribution =
                (fullDuration / totalSessionDuration) * gameTotalTime;
              const scaledDuration =
                (durationInRange / fullDuration) * sessionContribution;
              periodTime += scaledDuration;
            } else {
              periodTime += durationInRange;
            }
          }
        }

        // Include current game session if active and within range
        if (
          presenceData.gameHistory?.currentGame === id &&
          presenceData.gameHistory?.gameStartTime
        ) {
          const sessionStart = presenceData.gameHistory.gameStartTime;
          if (sessionStart < endTime) {
            const rangeStart = Math.max(sessionStart, startTime);
            const rangeEnd = Math.min(now, endTime);
            const durationInRange = rangeEnd - rangeStart;
            if (durationInRange > 0) {
              periodTime += durationInRange;
            }
          }
        }
      }

      return {
        id,
        name: data.name,
        periodTime: periodTime,
        totalTime: data.totalTime || 0,
        dailyTime: data.dailyTime || 0,
      };
    })
    .filter((game) => game.periodTime > 0) // Only show games with time in this period
    .sort((a, b) => b.periodTime - a.periodTime)
    .slice(0, 5); // Show top 5 games

  if (gamesArray.length === 0) {
    return '<div class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400 tw-text-center tw-py-2">No games played in this period</div>';
  }

  const periodLabel =
    period === "custom"
      ? "Range"
      : period.charAt(0).toUpperCase() + period.slice(1);

  return gamesArray
    .map(
      (game) => `
      <a href="https://www.roblox.com/games/${encodeURIComponent(game.id)}"
         class="tw-flex tw-items-center tw-justify-between tw-bg-gray-50 dark:tw-bg-[#353840] tw-p-1.5 tw-rounded-md hover:tw-bg-gray-100 dark:hover:tw-bg-[#404650] tw-transition-colors">
        <span class="tw-text-sm tw-text-gray-800 dark:tw-text-gray-200 tw-truncate">${escapeHtml(game.name)}</span>
        <div class="tw-flex tw-flex-col tw-items-end tw-ml-2">
          <span class="tw-text-xs tw-text-green-600 dark:tw-text-green-400">${periodLabel}: ${formatTime(game.periodTime)}</span>
          ${period !== "total" ? `<span class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">Total: ${formatTime(game.totalTime)}</span>` : ""}
        </div>
      </a>
    `,
    )
    .join("");
}

function queryMultipleSelectors(selectors, target = document) {
  for (const selector of selectors) {
    const element = target.querySelector(selector);
    if (element) return element;
  }
  return null;
}

/** Update "last seen / last online" text in profile header (profileLastOnlineContainer from profileSelectors). */
async function updateHeaderLastOnline(
  userPresence,
  isFriend,
  friendlistLength,
) {
  const presence = await storageManager.getSettings("friends-presence", true);
  if (!presence) return;
  const morePresenceDetails = await storageManager.getSettings(
    "more-presence-details",
    false,
  );
  const selectors = await getProfileSelectors();
  const sel = selectors.profileLastOnlineContainer;
  let container = sel ? document.querySelector(sel) : null;
  if (!container)
    container = document.querySelector(
      ".user-profile-header-info > div > div.flex.flex-col",
    );
  if (!container) return;
  let node = container.querySelector("[data-betterblox-last-online-header]");
  if (!node) {
    node = document.createElement("div");
    node.setAttribute("data-betterblox-last-online-header", "true");
    node.className = "tw-text-sm tw-text-[#666] dark:tw-text-gray-400 tw-mt-1";
    container.appendChild(node);
  }
  if (userPresence?.presenceType === 2) {
    const playingDuration =
      Date.now() - (userPresence.gameHistory?.gameStartTime || Date.now());
    node.textContent =
      playingDuration > 0
        ? `Currently playing (for ${formatPlayTime(playingDuration)})`
        : "Currently online";
  } else if (userPresence?.lastOnline) {
    let timestamp =
      typeof userPresence.lastOnline === "number"
        ? userPresence.lastOnline
        : userPresence.lastOnline?.timestamp;
    if (timestamp && timestamp > 0) {
      const timeText = formatTimeDifference(timestamp);
      const gamePart =
        morePresenceDetails && userPresence.lastOnline?.gameName
          ? ` playing ${userPresence.lastOnline.gameName.length > 12 ? userPresence.lastOnline.gameName.slice(0, 12) + "…" : userPresence.lastOnline.gameName}`
          : "";
      node.textContent = `Last seen: ${timeText}${gamePart}`;
    } else {
      node.textContent = "Last online: Unknown";
    }
  } else {
    if (friendlistLength < 1) node.textContent = "Last online: —";
    else if (isFriend)
      node.textContent =
        "Last online: No data yet (will appear when they go online)";
    else node.textContent = "Last online: Track this user to see activity";
  }
}

function addPresenceStatusElement(
  element,
  userPresence,
  isFriend,
  friendlistLength,
) {
  if (userPresence.presenceType === 2) {
    handleOnlinePlayer(element, userPresence);
  } else if (userPresence.presenceType === 0) {
    handleOfflinePlayer(element, userPresence, isFriend, friendlistLength);
  } else if (userPresence.presenceType > 0) {
    // Online-on-website (type 1) and in-Studio (type 3) also reach storage from
    // the background tracker; render a status for them instead of falling through.
    const statusText = userPresence.presenceType === 3 ? "In Studio" : "Currently online";
    handleGenericOnlinePlayer(element, statusText);
  }
}

function handleGenericOnlinePlayer(element, statusText) {
  const existingStatus = element.querySelectorAll(".presence-status");
  for (const status of existingStatus) {
    status.remove();
  }

  const div = document.createElement("div");
  div.className = "presence-status avatar-card-label";
  const inStatsCard =
    element.tagName === "DIV" && element.id === "presence-status-container";
  div.innerHTML = inStatsCard
    ? `<div class="tw-min-w-0">${statusText}</div>`
    : `<div style="font-size: 12px">${statusText}</div>`;

  // If element is a simple container div, append directly; otherwise find the header info
  if (
    element.tagName === "DIV" &&
    element.id === "presence-status-container"
  ) {
    element.appendChild(div);
  } else {
    const headerInfo = queryMultipleSelectors(
      [".user-profile-header-info > div > div.flex.flex-col"],
      element,
    );
    if (headerInfo) {
      headerInfo.appendChild(div);
    }
  }
}

function handleOnlinePlayer(element, userPresence) {
  const existingStatus = element.querySelectorAll(".presence-status");
  for (const status of existingStatus) {
    status.remove();
  }
  const playingDuration =
    Date.now() - (userPresence.gameHistory?.gameStartTime || Date.now());

  if (playingDuration > 0) {
    const div = document.createElement("div");
    div.className = "presence-status avatar-card-label";
    const inStatsCard =
      element.tagName === "DIV" && element.id === "presence-status-container";
    const inner =
      inStatsCard
        ? `<div class="tw-min-w-0">Currently playing (for ${formatPlayTime(playingDuration)})</div>`
        : `<div style="font-size: 12px">Currently playing (for ${formatPlayTime(playingDuration)})</div>`;
    div.innerHTML = inner;
    // If element is a simple container div, append directly; otherwise find the header info
    if (
      element.tagName === "DIV" &&
      element.id === "presence-status-container"
    ) {
      element.appendChild(div);
    } else {
      const headerInfo = queryMultipleSelectors(
        [".user-profile-header-info > div > div.flex.flex-col"],
        element,
      );
      if (headerInfo) {
        headerInfo.appendChild(div);
      }
    }
  }
}

async function handleOfflinePlayer(
  element,
  userPresence,
  isFriend,
  friendlistLength,
) {
  const existingStatus = element.querySelectorAll(".presence-status");
  for (const status of existingStatus) {
    status.remove();
  }

  // Handle both old (number) and new (object) lastOnline structure
  let lastOnline = userPresence.lastOnline;
  let timestamp = null;

  if (typeof lastOnline === "number") {
    timestamp = lastOnline;
  } else if (
    lastOnline &&
    typeof lastOnline === "object" &&
    lastOnline.timestamp
  ) {
    timestamp = lastOnline.timestamp;
  }

  if (timestamp && timestamp > 0) {
    const timeText = formatTimeDifference(timestamp);
    const morePresenceDetails = await storageManager.getSettings(
      "more-presence-details",
      false,
    );

    // Format exact date and time for tooltip
    const exactTime = new Date(timestamp).toLocaleString();

    // Build tooltip content
    let tooltipContent = `Last seen: ${exactTime}`;
    if (lastOnline && typeof lastOnline === "object" && lastOnline.gameName) {
      // gameName is attacker-controllable (presence lastLocation) and this
      // string is later assigned via innerHTML — escape before interpolation.
      tooltipContent += `\nPlaying: ${escapeHtml(lastOnline.gameName)}`;
      if (lastOnline.sessionDuration > 0) {
        tooltipContent += `\nDuration: ${formatPlayTime(lastOnline.sessionDuration)}`;
      }
    }

    // Build display text
    let displayText = timeText;
    if (
      morePresenceDetails &&
      lastOnline &&
      typeof lastOnline === "object" &&
      lastOnline.gameName
    ) {
      const gameName =
        lastOnline.gameName.length > 10
          ? lastOnline.gameName.slice(0, 10) + "..."
          : lastOnline.gameName;
      // displayText is assigned via innerHTML below — escape the (attacker-
      // controllable) game name to prevent DOM XSS.
      displayText += ` playing ${escapeHtml(gameName)}`;
      if (lastOnline.sessionDuration > 0) {
        displayText += ` (${formatPlayTime(lastOnline.sessionDuration)})`;
      }
    }

    const div = document.createElement("div");
    div.className = "presence-status avatar-card-label tw-group tw-relative";
    const inStatsCard =
      element.tagName === "DIV" && element.id === "presence-status-container";
    const textStyle = inStatsCard ? "" : ' style="font-size: 12px"';
    div.innerHTML = inStatsCard
      ? `<div${textStyle} class="tw-cursor-help tw-min-w-0">${displayText}
        <div class="tw-invisible group-hover:tw-visible tw-absolute tw-bottom-full tw-left-1/2 tw--translate-x-1/2 tw-px-2 tw-py-1 tw-bg-gray-800 tw-text-white tw-text-xs tw-rounded tw-whitespace-nowrap" style="white-space: pre-line;">
          ${tooltipContent}
        </div>
      </div>`
      : `
    <div class="tw-flex tw-flex-row tw-gap-2">
      <div${textStyle} class="tw-cursor-help">${displayText}
        <div class="tw-invisible group-hover:tw-visible tw-absolute tw-bottom-full tw-left-1/2 tw--translate-x-1/2 tw-px-2 tw-py-1 tw-bg-gray-800 tw-text-white tw-text-xs tw-rounded tw-whitespace-nowrap" style="white-space: pre-line;">
          ${tooltipContent}
        </div>
      </div>
    </div>
    `;

    // If element is a simple container div, append directly; otherwise find the header info
    if (
      element.tagName === "DIV" &&
      element.id === "presence-status-container"
    ) {
      element.appendChild(div);
    } else {
      const headerInfo = queryMultipleSelectors(
        [".user-profile-header-info > div > div.flex.flex-col"],
        element,
      );
      if (headerInfo) {
        headerInfo.appendChild(div);
      }
    }
  } else {
    await addPresenceUnknown(element, isFriend, friendlistLength);
  }
}

async function addPresenceUnknown(element, isFriend, friendlistLength) {
  const div = document.createElement("div");
  div.className = "presence-status avatar-card-label";
  if (isFriend) {
    div.innerHTML = `<div style="color: #666;font-size: 10px">Your friend has been offline since you installed the extension. Their activity data will appear once they come online while your browser is open. The 'Last Online' status will be recorded the next time your friend switches from online to offline.</div>`;
  } else {
    div.innerHTML = `<div style="color: #666;font-size: 10px">No data available for this stranger. Make sure you have clicked the 'Track' button. Their activity data will appear once they come online while your browser is open.</div>`;
  }
  if (friendlistLength < 1) {
    div.innerHTML = `<div style="color: #666;font-size: 10px">Friendlist is empty... Please wait 5-10 minutes for extension warmup.</div>`;
  }
  // If element is a simple container div, append directly; otherwise find the header info
  if (element.tagName === "DIV" && element.id === "presence-status-container") {
    element.appendChild(div);
  } else {
    const profileHeader = queryMultipleSelectors(
      [".user-profile-header-info > div > div.flex.flex-col"],
      element,
    );
    if (profileHeader) {
      profileHeader.appendChild(div);
    }
  }
}

async function addTrackingButton(userId, container) {
  // If container is already a div (from createStatsDisplay), use it directly
  // Otherwise, try to find the buttons container in the element
  let targetContainer = container;
  if (container && container.tagName !== "DIV") {
    targetContainer = queryMultipleSelectors(
      [".buttons-show-on-desktop"],
      container,
    );
  }

  if (!targetContainer) return;

  const betterBloxTracking = await storageManager.get(
    "betterblox_tracking_list_v2",
    [],
  );

  // Normalize ids to strings: friendTracking/profile.js stores this list as
  // String(userId), while getUserID() returns a Number. A type-strict
  // includes()/filter() would otherwise miss entries added by the other UI.
  const userIdStr = String(userId);
  let isTracking = betterBloxTracking.some((id) => String(id) === userIdStr);

  // If container is a div, create a button directly; otherwise create li
  let buttonElement;
  if (targetContainer.tagName === "DIV") {
    buttonElement = document.createElement("button");
    buttonElement.type = "button";
    buttonElement.className = isTracking ? "btn-alert-md" : "btn-control-md";
  } else {
    const li = document.createElement("li");
    li.className = "btn-friends";
    li.style.marginLeft = "9px";
    buttonElement = li;
  }

  const updateButton = () => {
    if (buttonElement.tagName === "BUTTON") {
      buttonElement.className = isTracking ? "btn-alert-md" : "btn-control-md";
      buttonElement.textContent = isTracking ? "Untrack" : "Track";
    } else {
      buttonElement.innerHTML = isTracking
        ? '<button type="button" class="tw-btn-alert-md">Untrack</button>'
        : '<button type="button" class="tw-btn-control-md">Track</button>';
    }
  };

  updateButton();

  const button =
    buttonElement.tagName === "BUTTON"
      ? buttonElement
      : buttonElement.querySelector("button");
  button.addEventListener("click", async () => {
    const currentTracking = await storageManager.get(
      "betterblox_tracking_list_v2",
      [],
    );
    if (isTracking) {
      const updatedTracking = currentTracking.filter(
        (id) => String(id) !== userIdStr,
      );
      await storageManager.set("betterblox_tracking_list_v2", updatedTracking);
    } else {
      const updatedTracking = [...currentTracking, userIdStr];
      await storageManager.set("betterblox_tracking_list_v2", updatedTracking);
    }

    isTracking = !isTracking;
    updateButton();
  });

  targetContainer.appendChild(buttonElement);
}

export async function addPresenceStatusCardProfile(element, presenceData) {
  const userId = getUserID();
  if (!userId) return;

  const presence = await storageManager.getSettings("friends-presence", true);
  if (!presence) return;

  // Get friends list to check if user is a friend
  const friendsListRaw = await storageManager.get(
    "betterblox_friends_list",
    {},
  );
  const authentificatedUserId = getAuthentificatedUserID();
  if (!authentificatedUserId)
    return console.error("Card Profile: Could not get authentificated user ID");

  const friendsList = friendsListRaw[authentificatedUserId] || {
    friendIds: [],
  };
  const isFriend = friendsList.friendIds.includes(userId);

  // Find the presence-status-container that was created in createStatsDisplay
  const presenceContainer = document.getElementById(
    "presence-status-container",
  );
  if (presenceContainer) {
    if (presenceData[userId]) {
      addPresenceStatusElement(
        presenceContainer,
        presenceData[userId],
        isFriend,
        friendsList.friendIds.length,
      );
    } else {
      presenceContainer.innerHTML = "";
      await addPresenceUnknown(
        presenceContainer,
        isFriend,
        friendsList.friendIds.length,
      );
    }
  } else {
    if (presenceData[userId]) {
      addPresenceStatusElement(
        element,
        presenceData[userId],
        isFriend,
        friendsList.friendIds.length,
      );
    }
  }
  await updateHeaderLastOnline(
    presenceData[userId] || null,
    isFriend,
    friendsList.friendIds.length,
  );
}

export async function addTimeContainer(element) {
  const userId = getUserID();
  if (!userId) return console.error("Card Profile: Could not get user ID");

  if (document.querySelector(".bblox-stats-container")) return;

  const selectors = await getProfileSelectors();
  const insertSel = selectors.profileHeaderInsert;
  const headerInner =
    (insertSel &&
      (element.querySelector(insertSel) ||
        document.querySelector(insertSel))) ||
    null;
  const headerContainer = headerInner?.parentNode;

  const authentificatedUserId = getAuthentificatedUserID();
  if (!authentificatedUserId)
    return console.error("Card Profile: Could not get authentificated user ID");

  const friendsListRaw = await storageManager.get(
    "betterblox_friends_list",
    {},
  );
  const friendsList = friendsListRaw[authentificatedUserId] || {
    friendIds: [],
  };
  const isFriend = friendsList.friendIds.includes(userId);

  const presenceData = await storageManager.get(
    "betterblox_presence_tracker_v2",
    {},
  );
  const userPresenceData = presenceData[userId] || null;

  const statsDisplay = await createStatsDisplay(
    userPresenceData,
    userId,
    element,
    isFriend,
    friendsList.friendIds.length,
  );

  await updateHeaderLastOnline(
    userPresenceData || null,
    isFriend,
    friendsList.friendIds.length,
  );

  if (headerContainer) {
    headerContainer.parentNode.insertBefore(
      statsDisplay,
      headerContainer.nextSibling,
    );
  } else {
    const header = element.querySelector(".user-profile-header");
    if (header) {
      header.parentNode.insertBefore(statsDisplay, header.nextSibling);
    } else {
      const fallbacks = selectors.profileHeaderInsertFallback || [];
      let inserted = false;
      for (const sel of fallbacks) {
        const fallbackHeader =
          element.querySelector(sel) || document.querySelector(sel);
        if (fallbackHeader) {
          fallbackHeader.parentNode.insertBefore(
            statsDisplay,
            fallbackHeader.nextSibling,
          );
          inserted = true;
          break;
        }
      }
      if (!inserted)
        console.error("Card Profile: Could not find profile header");
    }
  }
}
