export function getSVGIcon(name) {
  return chrome.runtime.getURL(`icons/svg/${name}.svg`);
}
export function getPNGIcon(name) {
  return chrome.runtime.getURL(`icons/png/${name}.png`);
}

export function createIconElement(name) {
  const img = document.createElement("img");
  img.src = getPNGIcon(name);
  return img;
}
