export class ServerPagination {
  constructor(mainClass) {
    this.mainClass = mainClass;
    this.globeViewer = null; // Reference to globe viewer
    this.resetToDefaults();
    this.setupLoadMoreButton();
  }

  resetToDefaults() {
    this.currentPage = 1;
    this.itemsPerPage = 8;
    this.elementList = [];
    this.filterSettings = {
      datacenters: new Set(), // Store selected datacenter locations
    };
    this.sortOrder = "Desc"; // Default sort order
    this.isBestConnection = false; // Track best connection state
    this.ageSort = null; // Age sorting: null (disabled), "Oldest", or "Newest"
    this.oldVersionSort = null; // Old version filter: null (disabled) or true (show only old versions)
    this.isShuffled2 = false; // Track second shuffle state
    this._previousSortOrder = null;
  }

  reset() {
    // Clear the element list first
    this.elementList = [];

    // Clear the server list container
    const serverListContainer = document.querySelector(
      "#betterblox-server-list",
    );
    if (serverListContainer) {
      serverListContainer.innerHTML = "";
    }

    // Reset all settings to defaults
    this.resetToDefaults();

    // Refresh the list with new settings
    this.handleServerListRefresh();
  }

  setupLoadMoreButton() {
    // Setup load more button click handler
    document.addEventListener("click", (e) => {
      if (e.target.id === "load-more-servers") {
        this.loadMoreServers();
      }
    });
  }

  async loadMoreServers() {
    this.currentPage++;
    await this.handleServerListRefresh();
    this.updateLoadMoreButton();
  }

  updateLoadMoreButton() {
    const loadMoreButton = document.querySelector("#load-more-servers");
    if (!loadMoreButton) return;

    const filteredServerList = this.getFilteredServerList();
    const totalServers = filteredServerList.length;
    const currentlyShowing = this.currentPage * this.itemsPerPage;

    if (currentlyShowing < totalServers) {
      loadMoreButton.classList.remove("tw-hidden");
    } else {
      loadMoreButton.classList.add("tw-hidden");
    }
  }

  async handleServerListRefresh() {
    const filteredServerList = this.getFilteredServerList();

    const serverListContainer = document.querySelector(
      "#betterblox-server-list",
    );

    if (!serverListContainer) {
      console.error("Server list container not found");
      return;
    }

    // Always respect pagination limits, but show servers progressively during loading
    const end = this.currentPage * this.itemsPerPage;

    const serversToShow = filteredServerList.slice(0, end);

    // Update elementList to match all shown servers
    const beforeFilterCount = this.elementList.length;
    this.elementList = this.elementList.filter((item) => {
      // Filter out invalid items
      if (!item || !item.id) {
        return false;
      }

      const serverStillExists = serversToShow.some(
        (server) => server.id === item.id,
      );

      // Remove element if server no longer exists
      if (!serverStillExists) {
        const element = serverListContainer.querySelector(
          `[betterblox-server-id="${item.id}"]`,
        );
        if (element) {
          element.remove();
        }
      }
      return serverStillExists;
    });

    // Add or update servers
    for (const server of serversToShow) {
      // Skip invalid servers
      if (!server || !server.id) {
        continue;
      }

      const existingIndex = this.elementList.findIndex(
        (item) => item && item.id === server.id,
      );
      if (existingIndex === -1) {
        // Add new server - pass the filtered server list for badge calculation
        this.elementList.push(server);
        await this.mainClass.createServerCard(server, filteredServerList);
      } else {
        // Update existing server if needed
        const existingServer = this.elementList[existingIndex];
        if (this.hasServerChanged(existingServer, server)) {
          // Replace old server card with new one
          const oldElement = serverListContainer.querySelector(
            `[betterblox-server-id="${server.id}"]`,
          );
          if (oldElement) {
            oldElement.remove();
            await this.mainClass.createServerCard(server, filteredServerList);
          }
          this.elementList[existingIndex] = server;
        }
      }
    }

    // Sort elements to match serverList order
    this.sortElementsToMatchList(serverListContainer, serversToShow);

    // Update load more button visibility
    this.updateLoadMoreButton();
  }

  hasServerChanged(oldServer, newServer) {
    // Compare relevant properties to determine if server needs updating
    return (
      oldServer.playing !== newServer.playing ||
      oldServer.ping !== newServer.ping ||
      oldServer.playerTokens.join(",") !== newServer.playerTokens.join(",") ||
      oldServer.placeVersion !== newServer.placeVersion ||
      oldServer.isOutdated !== newServer.isOutdated ||
      oldServer.joinDataPending !== newServer.joinDataPending ||
      oldServer.joinDataFailed !== newServer.joinDataFailed ||
      oldServer.joinFailedStuckInQueue !== newServer.joinFailedStuckInQueue ||
      oldServer.datacenterId !== newServer.datacenterId ||
      oldServer.ip !== newServer.ip ||
      oldServer.distance !== newServer.distance ||
      oldServer.isClosest !== newServer.isClosest ||
      oldServer.queuePosition !== newServer.queuePosition ||
      oldServer.serverAge !== newServer.serverAge ||
      oldServer.botPercentage !== newServer.botPercentage
    );
  }

  sortElementsToMatchList(container, serverList) {
    const elements = Array.from(container.children);

    // Sort elements based on serverList order
    elements.sort((a, b) => {
      const aIndex = serverList.findIndex(
        (server) => server.id === a.getAttribute("betterblox-server-id"),
      );
      const bIndex = serverList.findIndex(
        (server) => server.id === b.getAttribute("betterblox-server-id"),
      );
      return aIndex - bIndex;
    });

    // Reorder elements in DOM
    elements.forEach((element) => container.appendChild(element));
  }

  getCurrentPageItems() {
    const start = (this.currentPage - 1) * this.itemsPerPage;
    const end = start + this.itemsPerPage;
    return this.serverList.slice(start, end);
  }

  nextPage() {
    const maxPage = Math.ceil(this.serverList.length / this.itemsPerPage);
    if (this.currentPage < maxPage) {
      this.currentPage++;
      return true;
    }
    return false;
  }

  previousPage() {
    if (this.currentPage > 1) {
      this.currentPage--;
      return true;
    }
    return false;
  }

  getTotalPages() {
    return Math.ceil(this.serverList.length / this.itemsPerPage);
  }

  // New filtering methods

  setSortOrder(order) {
    // Save the new sort order
    this.sortOrder = order;

    // Reset all filters except sort order
    this.filterSettings.datacenters.clear();
    this.isBestConnection = false;
    this.ageSort = null;
    this.oldVersionSort = null;
    this.isShuffled2 = false;
    this.currentPage = 1;

    // Update UI indicators
    const regionFilterIndicator = document.querySelector(
      "#region-filter-indicator",
    );
    if (regionFilterIndicator) {
      regionFilterIndicator.classList.remove("tw-bg-blue-500");
      regionFilterIndicator.classList.add("tw-bg-gray-400");
    }

    // Restart the crawler with the new sort order
    this.mainClass.refreshServerListWithSortOrder(order);
  }

  setDatacenterFilter(location, selected) {
    if (selected) {
      this.filterSettings.datacenters.add(location);
    } else {
      this.filterSettings.datacenters.delete(location);
    }
    this.currentPage = 1; // Reset to first page when filter changes
    this.handleServerListRefresh();

    // Notify globe viewer if it exists
    if (this.globeViewer) {
      this.globeViewer.refresh();
    }
  }

  clearDatacenterFilters() {
    this.filterSettings.datacenters.clear();
    this.currentPage = 1;
    this.handleServerListRefresh();

    // Notify globe viewer if it exists
    if (this.globeViewer) {
      this.globeViewer.refresh();
    }
  }

  setAgeSort(order) {
    // Toggle behavior: if clicking the same option, disable it
    if (this.ageSort === order) {
      this.ageSort = null;
    } else {
      this.ageSort = order;
      // Disable other mutually exclusive filters
      this.isBestConnection = false;
    }
    this.currentPage = 1;
    this.handleServerListRefresh();
  }

  setOldVersionSort() {
    // Toggle behavior: if already enabled, disable it
    this.oldVersionSort = this.oldVersionSort ? null : true;
    this.currentPage = 1;
    this.handleServerListRefresh();
  }

  toggleShuffle2() {
    this.isShuffled2 = !this.isShuffled2;
    this.currentPage = 1;
    this.handleServerListRefresh();
  }

  async toggleBestConnection() {
    this.isBestConnection = !this.isBestConnection;
    if (this.isBestConnection) {
      // Disable other mutually exclusive filters
      this.ageSort = null;

      // Calculate distances and sort servers by best connection
      const sortedServers = await this.mainClass.calculateServerDistances();

      // Update the main server list with distance-sorted servers
      this.mainClass.serverList = sortedServers;
    }
    this.currentPage = 1;
    this.handleServerListRefresh();
  }

  getFilteredServerList() {
    let filteredList = [...this.mainClass.serverList];

    // Apply datacenter filter if any locations are selected
    if (this.filterSettings.datacenters.size > 0) {
      filteredList = filteredList.filter((server) => {
        const serverLocation = `${server.datacenter?.location?.city}, ${server.datacenter?.location?.country}`;
        return this.filterSettings.datacenters.has(serverLocation);
      });
    }

    const joinFirst = (a, b) => this.mainClass.compareJoinDataPriority(a, b);

    // Apply sorting based on current sort order
    if (this.isShuffled2) {
      const shuffleInPlace = (arr) => {
        for (let i = arr.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [arr[i], arr[j]] = [arr[j], arr[i]];
        }
      };
      const buckets = [[], [], []];
      filteredList.forEach((s) => {
        buckets[this.mainClass.joinDataPriority(s)].push(s);
      });
      buckets.forEach(shuffleInPlace);
      filteredList = buckets.flat();
    } else if (this.isBestConnection) {
      filteredList.sort((a, b) => {
        const jf = joinFirst(a, b);
        if (jf !== 0) return jf;
        const da = a.distance ?? Infinity;
        const db = b.distance ?? Infinity;
        return da - db;
      });
    } else {
      // Sort by player count based on current sort order
      filteredList.sort((a, b) => {
        const jf = joinFirst(a, b);
        if (jf !== 0) return jf;
        if (this.sortOrder === "Asc") {
          return a.playing - b.playing;
        } else {
          return b.playing - a.playing;
        }
      });
    }

    // Apply age sorting
    if (this.ageSort) {
      filteredList.sort((a, b) => {
        const jf = joinFirst(a, b);
        if (jf !== 0) return jf;
        // Sort by first seen timestamp directly (more accurate than parsing age strings)
        const getFirstSeenTimestamp = (server) => {
          // If we have cached server data with firstSeen, use that
          if (server.firstSeen) {
            return new Date(server.firstSeen).getTime();
          }

          // Otherwise, calculate from current age string
          if (!server.serverAge) return Date.now(); // Treat missing age as newest

          const match = server.serverAge.match(/(\d+)([mhd])/);
          if (!match) return Date.now();

          const value = parseInt(match[1]);
          const unit = match[2];
          let ageMs = 0;

          switch (unit) {
            case "m":
              ageMs = value * 60 * 1000;
              break; // minutes to ms
            case "h":
              ageMs = value * 60 * 60 * 1000;
              break; // hours to ms
            case "d":
              ageMs = value * 24 * 60 * 60 * 1000;
              break; // days to ms
            default:
              return Date.now();
          }

          // Calculate first seen timestamp: current time - age
          return Date.now() - ageMs;
        };

        const firstSeenA = getFirstSeenTimestamp(a);
        const firstSeenB = getFirstSeenTimestamp(b);

        if (this.ageSort === "Newest") {
          return firstSeenB - firstSeenA; // Newest first (more recent timestamps)
        } else if (this.ageSort === "Oldest") {
          return firstSeenA - firstSeenB; // Oldest first (older timestamps)
        }
      });
    }

    // Apply old version filtering
    if (this.oldVersionSort) {
      const latestVersion = this.mainClass.getLatestPlaceVersion();
      filteredList = filteredList.filter((server) => {
        // Check if server has isOutdated property set
        if (server.isOutdated !== undefined) {
          return server.isOutdated === true;
        }

        // Fallback: calculate on the fly if isOutdated isn't set yet
        return (
          latestVersion !== null &&
          server.placeVersion !== null &&
          parseInt(server.placeVersion) < latestVersion
        );
      });
    }

    return filteredList;
  }

  // Method to set globe viewer reference
  setGlobeViewer(globeViewer) {
    this.globeViewer = globeViewer;
  }
}
