/**
 * Escape a string for safe interpolation into an HTML template literal.
 *
 * Roblox-derived strings (experience/game names, presence lastLocation,
 * placeIds, etc.) are attacker-controllable and get injected into the
 * extension content-script context via innerHTML. Run every such value
 * through this helper before interpolation to prevent DOM-based XSS.
 *
 * @param {*} value - value to escape (coerced to string; null/undefined -> "")
 * @returns {string} HTML-escaped string
 */
export function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
