class EventService {
  constructor() {
    this.listeners = new Map();

    // Listen for custom events from the injected script
    document.addEventListener(
      "BETTERBLOX_XHR_RESPONSE",
      (event) => {
        if (!event.detail) return;
        const { url, data, status, contentType, isJson } = event.detail;
        this.notify(url, { url, data, status, contentType, isJson });
      },
      false
    );
  }

  // Subscribe to an endpoint pattern
  subscribe(urlPattern, callback) {
    if (!this.listeners.has(urlPattern)) {
      this.listeners.set(urlPattern, new Set());
    }
    this.listeners.get(urlPattern).add(callback);
  }

  // Unsubscribe from an endpoint pattern
  unsubscribe(urlPattern, callback) {
    if (this.listeners.has(urlPattern)) {
      this.listeners.get(urlPattern).delete(callback);
    }
  }

  // Notify all relevant listeners
  notify(url, data) {
    this.listeners.forEach((callbacks, pattern) => {
      if (url.match(new RegExp(pattern))) {
        callbacks.forEach((callback) => callback(data));
      }
    });
  }
}

export const eventService = new EventService();
export default eventService;
