import { storageManager } from "../../../../core/storageManager.js";

export async function addPresenceStatusInitial(element) {
  const friendsPresence = await storageManager.getSettings(
    "friends-presence",
    true
  );
  if (!friendsPresence) return;

  const userId = getUserIdFromElement(element);
  const presenceData = await storageManager.get(
    "betterblox_presence_tracker_v2",
    {}
  );

  const existingStatus = element.querySelector(".presence-status");
  if (existingStatus) existingStatus.remove();

  if (presenceData[userId]) {
    addPresenceStatusElement(element, presenceData[userId]);
  } else {
    // Add loading state
    const div = document.createElement("div");
    div.className = "presence-status";
    div.innerHTML = `<div style="color: #666;font-size: 12px">(BetterBLOX warming up please wait...)</div>`;
    element.appendChild(div);
  }
}

export async function addPresenceStatus(element, presenceData) {
  const userId = getUserIdFromElement(element);
  if (!userId) return;

  const presence = await storageManager.getSettings("friends-presence", true);
  if (!presence) return;
  if (presenceData[userId]) {
    addPresenceStatusElement(element, presenceData[userId]);
  }
}

function formatTimeDifference(timestamp) {
  const now = new Date().getTime();
  const diff = now - timestamp;

  const minutes = Math.floor(diff / (1000 * 60));
  const hours = Math.floor(diff / (1000 * 60 * 60));
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (minutes < 60) return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
  if (hours < 24) return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
  return `${days} day${days !== 1 ? "s" : ""} ago`;
}

function formatPlayTime(ms) {
  if (!ms || ms < 0) return "0m";
  const minutes = Math.floor(ms / (1000 * 60));
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    const remainingMinutes = minutes % 60;
    return `${hours}h${remainingMinutes > 0 ? ` ${remainingMinutes}m` : ""}`;
  }
  return `${minutes}m`;
}

function addPresenceStatusElement(element, userPresence) {
  if (userPresence.presenceType === 2) {
    handleOnlinePlayer(element, userPresence);
  } else if (userPresence.presenceType === 0) {
    handleOfflinePlayer(element, userPresence);
  }
}

function handleOnlinePlayer(element, userPresence) {
  const existingStatus =
    element.parentElement.querySelectorAll(".presence-status");
  for (const status of existingStatus) {
    status.remove();
  }

  const playingDuration =
    Date.now() - (userPresence.gameHistory?.gameStartTime || Date.now());
  if (playingDuration > 0) {
    const div = document.createElement("div");
    div.className = "presence-status";
    div.innerHTML = `<div style="color: #666;font-size: 10px">(for ${formatPlayTime(
      playingDuration
    )})</div>`;
    element.appendChild(div);
  }
}

async function handleOfflinePlayer(element, userPresence) {
  const existingStatus =
    element.parentElement.querySelectorAll(".presence-status");
  for (const status of existingStatus) {
    status.remove();
  }

  // Handle both old (number) and new (object) lastOnline structure
  let lastOnline = userPresence.lastOnline;
  let timestamp = null;
  
  if (typeof lastOnline === 'number') {
    timestamp = lastOnline;
  } else if (lastOnline && typeof lastOnline === 'object' && lastOnline.timestamp) {
    timestamp = lastOnline.timestamp;
  }

  if (timestamp && timestamp > 0) {
    const timeText = formatTimeDifference(timestamp);
    const morePresenceDetails = await storageManager.getSettings(
      "more-presence-details",
      false,
    );

    // Format exact date and time for tooltip
    const exactTime = new Date(timestamp).toLocaleString();
    
    // Build tooltip content
    let tooltipContent = `Last seen: ${exactTime}`;
    if (lastOnline && typeof lastOnline === 'object' && lastOnline.gameName) {
      tooltipContent += `\nPlaying: ${lastOnline.gameName}`;
      if (lastOnline.sessionDuration > 0) {
        tooltipContent += `\nDuration: ${formatPlayTime(lastOnline.sessionDuration)}`;
      }
    }

    // Build display text
    let displayText = timeText;
    if (
      morePresenceDetails &&
      lastOnline &&
      typeof lastOnline === 'object' &&
      lastOnline.gameName
    ) {
      const gameName = lastOnline.gameName.length > 10 
        ? lastOnline.gameName.slice(0, 10) + '...' 
        : lastOnline.gameName;
      displayText += ` playing ${gameName}`;
      if (lastOnline.sessionDuration > 0) {
        displayText += ` (${formatPlayTime(lastOnline.sessionDuration)})`;
      }
    }

    const div = document.createElement("div");
    div.className = "presence-status tw-group tw-relative";
    div.innerHTML = `
      <div style="font-size: 12px" class="tw-cursor-help">${displayText}
        <div class="tw-invisible group-hover:tw-visible tw-absolute tw-bottom-full tw-left-1/2 tw--translate-x-1/2 tw-px-2 tw-py-1 tw-bg-gray-800 tw-text-white tw-text-xs tw-rounded tw-whitespace-nowrap" style="white-space: pre-line;">
          ${tooltipContent}
        </div>
      </div>
    `;
    element.appendChild(div);
  }
}

function getUserIdFromElement(element) {
  try {
    return element.href.split("/")[4];
  } catch (error) {
    console.error("Presence Homepage: Error getting user ID from element");
    return null;
  }
}
