import { addGearIconSettingsButton, handleSidebarSettingButton } from "./components.js";

// The legacy in-page settings UI (which rendered BetterBLOX settings into
// Roblox's own account-page DOM and broke whenever Roblox changed its markup)
// has been removed in favor of the standalone options page (betterblox-options/).
//
// This module now only injects the two entry points that open that page:
//   - the "BetterBLOX Settings" item in the navbar gear popover
//   - the "BetterBLOX Settings" button in the account-page sidebar
// Both are plain links to the web-accessible options.html (see components.js).
const settingsModule = {
  pages: ["all"],
  selectors: [
    {
      selector: "#settings-popover-menu",
      handler: (element) => {
        addGearIconSettingsButton(element);
      },
    },
  ],

  async initialize() {
    handleSidebarSettingButton();
  },
};

export default settingsModule;
