import { browserAPI } from "../../../core/browserAPI.js";

/** Temporary: hide the “Custom Roblox website theme engine” sidebar widget. Set to true to hide. */
const DISABLE_THEME_PROMO_WIDGET = false;

const STORAGE_KEYS = {
  themeEnabled: "themeEnabled",
  themeWidgetDismissedUntil: "betterblox_theme_widget_dismissed_until",
};
const WIDGET_DISMISS_HOURS = 24;

function createThemeButton(parentElement) {
  const container = document.createElement("div");
  container.setAttribute("data-betterblox-theme-widget", "true");
  container.style.cssText =
    "background:linear-gradient(135deg,#f5f3ff 0%,#ede9fe 100%);border:1px solid #8b5cf6;border-radius:6px;padding:8px;margin-bottom:14px;display:flex;flex-direction:column;gap:6px;position:relative;";

  const closeBtn = document.createElement("button");
  closeBtn.innerHTML = "×";
  closeBtn.setAttribute("aria-label", "Close for 24 hours");
  closeBtn.style.cssText =
    "position:absolute;top:4px;right:6px;background:none;border:none;font-size:16px;cursor:pointer;color:#6b7280;line-height:1;padding:0;width:20px;height:20px;";
  closeBtn.onclick = () => {
    const until = Date.now() + WIDGET_DISMISS_HOURS * 60 * 60 * 1000;
    browserAPI.storage.local.set({
      [STORAGE_KEYS.themeWidgetDismissedUntil]: until,
    });
    container.remove();
  };

  const textContent = document.createElement("div");
  textContent.style.cssText = "display:flex;align-items:center;gap:6px;";

  const icon = document.createElement("div");
  icon.innerHTML = "🎨";
  icon.style.fontSize = "12px";

  const title = document.createElement("div");
  title.textContent = "BetterBLOX V2 Theme";
  title.style.cssText = "font-weight:700;color:#5b21b6;font-size:11px;";

  textContent.appendChild(icon);
  textContent.appendChild(title);

  const description = document.createElement("div");
  description.textContent = "Custom Roblox website theme engine";
  description.style.cssText =
    "font-size:9px;color:#6d28d9;line-height:1.2;text-align:center;";

  const enableButton = document.createElement("button");
  enableButton.textContent = "Enable";
  enableButton.style.cssText =
    "background:#7c3aed;color:white;border:none;border-radius:4px;padding:0px 8px;font-size:10px;font-weight:700;cursor:pointer;transition:background 0.2s;width:100%;";
  enableButton.onmouseover = () => (enableButton.style.background = "#6d28d9");
  enableButton.onmouseout = () => (enableButton.style.background = "#7c3aed");
  enableButton.onclick = async () => {
    await browserAPI.storage.local.set({ [STORAGE_KEYS.themeEnabled]: true });
    window.location.reload();
  };

  container.appendChild(closeBtn);
  container.appendChild(textContent);
  container.appendChild(description);
  container.appendChild(enableButton);

  return container;
}

function addTheme(element) {
  if (DISABLE_THEME_PROMO_WIDGET) return;
  (async () => {
    const [themeEnabled, dismissedUntil] = await Promise.all([
      browserAPI.storage.local
        .get([STORAGE_KEYS.themeEnabled])
        .then((d) => d.themeEnabled),
      browserAPI.storage.local
        .get([STORAGE_KEYS.themeWidgetDismissedUntil])
        .then((d) => d[STORAGE_KEYS.themeWidgetDismissedUntil]),
    ]);

    // Don't show widget if theme is already enabled (V2 overwrites the page)
    if (themeEnabled) return;
    // Don't show if user closed it within the last 24h
    if (dismissedUntil && Date.now() < dismissedUntil) return;

    const widget = createThemeButton(element);
    element.insertBefore(widget, element.firstChild);
  })();
}

const themeModule = {
  pages: ["all"],
  selectors: [
    {
      id: "Theme",
      selector: ".simplebar-content > ul > li.rbx-upgrade-now",
      handler: (element, currentPage) => {
        addTheme(element);
      },
    },
    {
      id: "Theme2",
      selector: "li > a.foundation-web-button",
      handler: (element, currentPage) => {
        addTheme(element.parentElement);
      },
    },
  ],
};

export default themeModule;
