import { getPNGIcon } from "../../../utils/iconManager.js";

function addSurveyPrompt(parentElement) {
  // Create container
  const surveyContainer = document.createElement("div");
  surveyContainer.style.background = "#f3f4f6"; // light gray
  surveyContainer.style.border = "1px solid #d1d5db";
  surveyContainer.style.borderRadius = "8px";
  surveyContainer.style.padding = "10px 12px";
  surveyContainer.style.marginBottom = "14px";
  surveyContainer.style.display = "block";
  surveyContainer.style.textAlign = "center";
  surveyContainer.title = "This widget will disappear on July 22, 2025";

  // Logo
  const logo = document.createElement("img");
  logo.src = getPNGIcon("logo32");
  logo.alt = "BetterBLOX Logo";
  logo.style.width = "20px";
  logo.style.height = "20px";
  logo.style.display = "block";
  logo.style.margin = "0 auto 6px auto";

  // Text
  const text = document.createElement("div");
  text.textContent =
    "Help us improve BetterBLOX! Please take our quick survey.";
  text.style.fontSize = "12px";
  text.style.color = "#111827";
  text.style.marginBottom = "7px";

  // Link Button
  const link = document.createElement("a");
  link.href = "https://forms.gle/Dq3pRtZBrwRjGf626";
  link.textContent = "Take Survey";
  link.target = "_blank";
  link.style.background = "#2563eb";
  link.style.color = "white";
  link.style.padding = "6px 14px";
  link.style.borderRadius = "6px";
  link.style.textDecoration = "none";
  link.style.fontWeight = "bold";
  link.style.transition = "background 0.2s";
  link.style.fontSize = "12px";
  link.style.display = "inline-block";
  link.onmouseover = () => (link.style.background = "#1d4ed8");
  link.onmouseout = () => (link.style.background = "#2563eb");

  surveyContainer.appendChild(logo);
  surveyContainer.appendChild(text);
  surveyContainer.appendChild(link);

  // Insert at the top of the parent element
  parentElement.insertBefore(surveyContainer, parentElement.firstChild);
}

function addPools(element) {
  // Only show the survey prompt if today is before 22.07.2025
  const now = new Date();
  const cutoff = new Date(2025, 6, 22); // July is month 6 (0-indexed)
  if (now < cutoff) {
    addSurveyPrompt(element);
  }
}

const poolsModule = {
  pages: ["all"],
  selectors: [
    {
      id: "Pools",
      selector: "li.rbx-upgrade-now",
      handler: async (element, currentPage) => {
        addPools(element);
      },
    },
  ],
};

export default poolsModule;
