import { storageManager } from "../../../../core/storageManager.js";
import { escapeHtml } from "../../../../core/htmlUtils.js";

// Track the MutationObserver per friend-tile-dropdown so we can disconnect a
// prior observer before creating a new one (prevents accumulating permanent
// observers when addGameHistory re-runs for the same dropdown).
const dropdownObservers = new WeakMap();

export async function addGameHistory(element) {
  const userId = getUserIdFromElement(element);
  if (!userId) return;

  const gameHistory = await storageManager.getSettings("game-history", true);
  if (!gameHistory) return;

  const data = await storageManager.get("betterblox_presence_tracker_v2", {});

  const userPresence = data[userId];
  if (!userPresence?.gameHistory) return;

  // Remove existing game history if present
  const existingHistory = element.querySelector(".game-history-container");
  if (existingHistory) existingHistory.remove();

  const container = document.createElement("div");
  container.className = "game-history-container";
  container.style.cssText = "min-width: 320px; width: 100%;";

  // Add current game if playing
  if (userPresence.presenceType === 2 && userPresence.gameHistory.currentGame) {
    const playingDuration = Date.now() - (userPresence.gameHistory.gameStartTime || Date.now());
    const currentGameCard = document.createElement("div");
    currentGameCard.className = "tw-px-3 tw-py-2.5 tw-mb-2 tw-bg-blue-50 dark:tw-bg-blue-900/20 tw-border-l-2 tw-border-blue-500 tw-rounded";
    currentGameCard.innerHTML = `
      <a href="https://www.roblox.com/games/${
        userPresence.gameHistory.currentGame
      }" target="_blank" rel="noopener" class="tw-block">
        <div class="tw-flex tw-items-center tw-justify-between">
          <div class="tw-flex-1 tw-min-w-0">
            <div class="tw-text-sm tw-font-semibold tw-text-blue-700 dark:tw-text-blue-300 tw-truncate">${
              userPresence.gameHistory.currentGameName
            }</div>
            <div class="tw-text-xs tw-text-blue-600 dark:tw-text-blue-400 tw-mt-0.5">Currently playing</div>
          </div>
          <div class="tw-text-sm tw-font-medium tw-text-blue-600 dark:tw-text-blue-400 tw-ml-2">${formatPlayTime(
            playingDuration
          )}</div>
        </div>
      </a>
    `;
    container.appendChild(currentGameCard);
  }

  // Get all games (excluding current)
  const allGames = Object.entries(userPresence.gameHistory.games)
    .filter(
      ([placeId]) =>
        placeId !== userPresence.gameHistory.currentGame?.toString()
    )
    .map(([placeId, game]) => ({
      placeId,
      ...game,
      lastPlayed: game.lastPlayed || 0
    }));

  if (allGames.length > 0) {
    // Create header with compact sort buttons
    const headerContainer = document.createElement("div");
    headerContainer.className = "tw-px-3 tw-py-2 tw-border-b tw-border-gray-200 dark:tw-border-gray-700";
    headerContainer.innerHTML = `
      <div class="tw-flex tw-flex-col tw-gap-2">
        <div class="tw-text-sm tw-font-semibold tw-text-gray-700 dark:tw-text-gray-200">Game History</div>
        <div class="tw-flex tw-items-center tw-gap-1 tw-flex-wrap" id="sort-buttons-${userId}">
          <button type="button" data-sort="totalTime" class="sort-btn active tw-px-2 tw-py-1 tw-text-xs tw-rounded hover:tw-bg-gray-100 dark:hover:tw-bg-gray-700 tw-text-gray-700 dark:tw-text-gray-300 tw-font-medium tw-transition-colors tw-whitespace-nowrap" title="Total Time">
            Total
          </button>
          <button type="button" data-sort="lastPlayed" class="sort-btn tw-px-2 tw-py-1 tw-text-xs tw-rounded hover:tw-bg-gray-100 dark:hover:tw-bg-gray-700 tw-text-gray-600 dark:tw-text-gray-400 tw-transition-colors tw-whitespace-nowrap" title="Last Played">
            Recent
          </button>
          <button type="button" data-sort="dailyTime" class="sort-btn tw-px-2 tw-py-1 tw-text-xs tw-rounded hover:tw-bg-gray-100 dark:hover:tw-bg-gray-700 tw-text-gray-600 dark:tw-text-gray-400 tw-transition-colors tw-whitespace-nowrap" title="Today">
            Today
          </button>
          <button type="button" data-sort="name" class="sort-btn tw-px-2 tw-py-1 tw-text-xs tw-rounded hover:tw-bg-gray-100 dark:hover:tw-bg-gray-700 tw-text-gray-600 dark:tw-text-gray-400 tw-transition-colors tw-whitespace-nowrap" title="Name">
            A-Z
          </button>
        </div>
      </div>
    `;

    // Create games list container
    const gamesList = document.createElement("div");
    gamesList.id = `games-list-${userId}`;
    gamesList.className = "tw-max-h-64 tw-overflow-y-auto";

    // Initial render with default sort (totalTime)
    renderGamesList(gamesList, allGames, "totalTime", userId);

    // Add sort button handlers
    const sortButtons = headerContainer.querySelectorAll(`#sort-buttons-${userId} .sort-btn`);
    sortButtons.forEach(btn => {
      btn.addEventListener("click", (e) => {
        // Prevent dropdown from closing when clicking sort buttons
        e.stopPropagation();
        e.preventDefault();
        
        const sortBy = e.currentTarget.dataset.sort;
        
        // Update active state
        sortButtons.forEach(b => {
          b.classList.remove("active", "tw-text-gray-700", "dark:tw-text-gray-300", "tw-font-medium");
          b.classList.add("tw-text-gray-600", "dark:tw-text-gray-400");
        });
        e.currentTarget.classList.add("active", "tw-text-gray-700", "dark:tw-text-gray-300", "tw-font-medium");
        e.currentTarget.classList.remove("tw-text-gray-600", "dark:tw-text-gray-400");
        
        // Re-render list
        renderGamesList(gamesList, allGames, sortBy, userId);
      });
    });

    container.appendChild(headerContainer);
    container.appendChild(gamesList);
  }

  element.appendChild(container);
  
  // Fix dropdown hover behavior - keep it open when hovering over dropdown content
  fixDropdownHoverBehavior(element, container);
}

function fixDropdownHoverBehavior(dropdownElement, gameHistoryContainer) {
  // Find the parent friend-tile-dropdown element
  let friendTileDropdown = dropdownElement.closest('.friend-tile-dropdown');
  if (!friendTileDropdown) {
    // Try to find it by looking for the ul element that contains the dropdown
    friendTileDropdown = dropdownElement.closest('ul')?.parentElement;
  }
  
  if (!friendTileDropdown) return;
  
  // Find the friend tile trigger element (the avatar/card that triggers the dropdown)
  const findFriendTile = () => {
    // Look for common friend tile selectors
    const selectors = [
      '.avatar-card',
      '.friend-tile',
      '[class*="friend"]',
      'a[href*="/users/"]'
    ];
    
    for (const selector of selectors) {
      const tile = friendTileDropdown.querySelector(selector);
      if (tile) return tile;
    }
    
    // Fallback: find the first anchor or clickable element
    return friendTileDropdown.querySelector('a') || friendTileDropdown;
  };
  
  // Find the dropdown menu container
  const findDropdownMenu = () => {
    // Look for the menu container that appears on hover
    let parent = gameHistoryContainer.parentElement;
    while (parent && parent !== document.body) {
      // Check if this is likely the dropdown menu container
      if (parent.classList.contains('MuiPaper-root') || 
          parent.getAttribute('role') === 'menu' ||
          parent.style.position === 'absolute' ||
          parent.style.position === 'fixed') {
        return parent;
      }
      parent = parent.parentElement;
    }
    return null;
  };
  
  // Set minimum width on dropdown menu
  const setDropdownWidth = () => {
    const dropdownMenu = findDropdownMenu();
    if (dropdownMenu) {
      // Ensure dropdown has minimum width to fit content
      if (!dropdownMenu.style.minWidth) {
        dropdownMenu.style.minWidth = '320px';
      }
      // Also check the ul element if it exists
      const ulElement = dropdownMenu.querySelector('ul') || dropdownMenu;
      if (ulElement && !ulElement.style.minWidth) {
        ulElement.style.minWidth = '320px';
      }
    }
  };
  
  // Add mouse event handlers to keep dropdown open
  const setupHoverFix = () => {
    const friendTile = findFriendTile();
    const dropdownMenu = findDropdownMenu();
    
    // Set dropdown width first
    setDropdownWidth();
    
    if (!friendTile || !dropdownMenu) return;
    
    // Create a bridge area between the friend tile and dropdown to prevent closing
    const createHoverBridge = () => {
      // Check if bridge already exists
      if (friendTileDropdown.querySelector('.betterblox-hover-bridge')) return;
      
      const bridge = document.createElement('div');
      bridge.className = 'betterblox-hover-bridge';
      bridge.style.cssText = 'position: absolute; pointer-events: auto; z-index: 1000;';
      
      // Position bridge between friend tile and dropdown
      const friendRect = friendTile.getBoundingClientRect();
      const menuRect = dropdownMenu.getBoundingClientRect();
      
      // Calculate bridge position and size
      const gap = 10; // Gap between tile and menu
      bridge.style.width = `${Math.max(friendRect.width, menuRect.width)}px`;
      bridge.style.height = `${gap}px`;
      bridge.style.top = `${friendRect.bottom}px`;
      bridge.style.left = `${Math.min(friendRect.left, menuRect.left)}px`;
      
      friendTileDropdown.style.position = 'relative';
      friendTileDropdown.appendChild(bridge);
    };
    
    // Prevent dropdown from closing when mouse is over game history or dropdown menu
    const preventClose = (e) => {
      e.stopPropagation();
      e.preventDefault();
    };
    
    gameHistoryContainer.addEventListener('mouseenter', preventClose);
    gameHistoryContainer.addEventListener('mouseleave', (e) => {
      const relatedTarget = e.relatedTarget;
      // If moving to dropdown menu or friend tile, prevent close
      if (relatedTarget && (dropdownMenu.contains(relatedTarget) || friendTileDropdown.contains(relatedTarget))) {
        preventClose(e);
      }
    });
    
    dropdownMenu.addEventListener('mouseenter', preventClose);
    dropdownMenu.addEventListener('mouseleave', (e) => {
      const relatedTarget = e.relatedTarget;
      // If moving to game history or friend tile, prevent close
      if (relatedTarget && (gameHistoryContainer.contains(relatedTarget) || friendTileDropdown.contains(relatedTarget))) {
        preventClose(e);
      }
    });
    
    // Create hover bridge
    createHoverBridge();
  };
  
  // Try to setup immediately
  setupHoverFix();
  setDropdownWidth();
  
  // Also try after delays in case structure isn't ready
  setTimeout(() => {
    setupHoverFix();
    setDropdownWidth();
  }, 100);
  setTimeout(() => {
    setupHoverFix();
    setDropdownWidth();
  }, 500);
  
  // Disconnect any observer left over from a previous addGameHistory run on
  // this same dropdown so observers don't accumulate.
  const previousObserver = dropdownObservers.get(friendTileDropdown);
  if (previousObserver) previousObserver.disconnect();

  // Use MutationObserver to watch for dropdown menu creation
  const observer = new MutationObserver(() => {
    setupHoverFix();
    setDropdownWidth();
  });

  observer.observe(friendTileDropdown, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['style', 'class']
  });

  dropdownObservers.set(friendTileDropdown, observer);

  // Stop observing once the user leaves the dropdown entirely (not while
  // moving between the friend tile, the menu, or the game history). The
  // observer is re-created on the next addGameHistory run if needed.
  const disconnectOnLeave = (e) => {
    const relatedTarget = e.relatedTarget;
    if (relatedTarget && friendTileDropdown.contains(relatedTarget)) return;
    observer.disconnect();
    if (dropdownObservers.get(friendTileDropdown) === observer) {
      dropdownObservers.delete(friendTileDropdown);
    }
    friendTileDropdown.removeEventListener('mouseleave', disconnectOnLeave);
  };
  friendTileDropdown.addEventListener('mouseleave', disconnectOnLeave);
}

function renderGamesList(container, games, sortBy, userId) {
  let sortedGames = [...games];

  switch (sortBy) {
    case "lastPlayed":
      sortedGames.sort((a, b) => (b.lastPlayed || 0) - (a.lastPlayed || 0));
      break;
    case "dailyTime":
      sortedGames.sort((a, b) => (b.dailyTime || 0) - (a.dailyTime || 0));
      break;
    case "name":
      sortedGames.sort((a, b) => {
        const nameA = (a.name || "Unknown Game").toLowerCase();
        const nameB = (b.name || "Unknown Game").toLowerCase();
        return nameA.localeCompare(nameB);
      });
      break;
    case "totalTime":
    default:
      sortedGames.sort((a, b) => (b.totalTime || 0) - (a.totalTime || 0));
      break;
  }

  // Limit to top 8 games for better UX
  sortedGames = sortedGames.slice(0, 8);

  if (sortedGames.length === 0) {
    container.innerHTML = '<div class="tw-px-3 tw-py-4 tw-text-center tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">No games found</div>';
    return;
  }

  container.innerHTML = sortedGames
    .map(
      (game, index) => {
        const isLast = index === sortedGames.length - 1;
        const hasRecentSession = game.sessions && game.sessions.length > 0;
        const latestSession = hasRecentSession 
          ? game.sessions.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0))[0]
          : null;
        
        return `
        <div class="tw-px-3 tw-py-2 ${!isLast ? 'tw-border-b tw-border-gray-100 dark:tw-border-gray-800' : ''} hover:tw-bg-gray-50 dark:hover:tw-bg-gray-800/50 tw-transition-colors">
          <a href="https://www.roblox.com/games/${encodeURIComponent(game.placeId)}" target="_blank" rel="noopener" class="tw-block">
            <div class="tw-flex tw-items-start tw-justify-between tw-gap-2">
              <div class="tw-flex-1 tw-min-w-0">
                <div class="tw-text-sm tw-font-medium tw-text-gray-800 dark:tw-text-gray-200 tw-truncate tw-mb-0.5">${escapeHtml(game.name)}</div>
                <div class="tw-flex tw-items-center tw-gap-2 tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">
                  ${game.lastPlayed ? `<span>${formatTimeDifference(game.lastPlayed)}</span>` : ''}
                  ${game.dailyTime > 0 ? `<span class="tw-text-blue-600 dark:tw-text-blue-400">${formatPlayTime(game.dailyTime)} today</span>` : ''}
                </div>
                ${latestSession ? `
                  <div class="tw-mt-1 tw-text-xs tw-text-gray-400 dark:tw-text-gray-500">
                    Last session: ${new Date(latestSession.timestamp).toLocaleDateString()} at ${new Date(latestSession.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} (${formatPlayTime(latestSession.duration)})
                  </div>
                ` : ''}
              </div>
              <div class="tw-flex tw-flex-col tw-items-end tw-gap-0.5 tw-flex-shrink-0">
                <div class="tw-text-sm tw-font-semibold tw-text-gray-700 dark:tw-text-gray-300">${formatPlayTime(game.totalTime)}</div>
                <div class="tw-text-xs tw-text-gray-400 dark:tw-text-gray-500">total</div>
              </div>
            </div>
          </a>
        </div>
      `;
      }
    )
    .join("");
}


function formatTimeDifference(timestamp) {
  const now = new Date().getTime();
  const diff = now - timestamp;

  const minutes = Math.floor(diff / (1000 * 60));
  const hours = Math.floor(diff / (1000 * 60 * 60));
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (minutes < 60) return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
  if (hours < 24) return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
  return `${days} day${days !== 1 ? "s" : ""} ago`;
}

function getUserIdFromElement(element) {
  try {
    const url =
      element.parentElement.parentElement.parentElement.querySelector("a").href;
    const userId = url.split("/")[4];
    return userId;
  } catch (error) {
    console.error("GameHistory: Error getting user ID from element");
    return null;
  }
}

function formatPlayTime(ms) {
  if (!ms || ms < 0) return "0m";
  const minutes = Math.floor(ms / (1000 * 60));
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    const remainingMinutes = minutes % 60;
    return `${hours}h${remainingMinutes > 0 ? ` ${remainingMinutes}m` : ""}`;
  }
  return `${minutes}m`;
}
