import { getData, setData } from "./storageManager.js";

// `setActive` defaults to true so the initial detection (loader.js) still
// auto-activates the currently logged-in Roblox account. Read paths pass
// `setActive: false` so merely listing accounts never overrides who is active
// (otherwise an explicit logout/switch is instantly resurrected from the cookie).
export async function loadAccount({ setActive = true } = {}) {
  const account = await getRobloxAccount();

  if (!account) {
    return null;
  }
  account.userId = account.id; //for backward compatibility
  // Save account to storage if it doesn't exist
  await saveAccountIfNew(account);
  if (setActive) {
    await setData("activeAccount", account);
  }

  return account;
}

async function saveAccountIfNew(account) {
  if (!account || !account.id) {
    console.log("Invalid account data, not saving");
    return false;
  }

  // Get existing accounts array
  let accounts = (await getData("roblox-accounts")) || [];

  // Check if account already exists
  const accountExists = accounts.some(
    (existingAccount) => existingAccount.id === account.id,
  );

  if (accountExists) {
    // Only persist when the cookie actually changed. Without this guard every
    // read (e.g. the 5s account-switch poll) rewrites storage in a tight loop.
    if (account.cookie) {
      const existing = accounts.find((a) => a.id === account.id);
      if (existing && existing.cookie !== account.cookie) {
        accounts = accounts.map((existingAccount) => {
          if (existingAccount.id === account.id) {
            return {
              ...existingAccount,
              cookie: account.cookie,
              lastUpdated: new Date().toISOString(),
            };
          }
          return existingAccount;
        });

        await setData("roblox-accounts", accounts);
        console.log(`Updated cookie for account ${account.name}`);
      }
    }

    return false;
  }

  // Add new account with timestamp
  const accountToSave = {
    ...account,
    lastUpdated: new Date().toISOString(),
    addedAt: new Date().toISOString(),
  };

  accounts.push(accountToSave);

  // Save updated accounts array
  await setData("roblox-accounts", accounts);
  console.log(`Added new account ${account.name} (${account.id}) to storage`);

  return true;
}

/**
 * Gets the current active account with cookie
 * @returns {Promise<Object|null>} The active account or null if not available
 */
export async function getActiveAccount() {
  // Return only the stored active account. Do NOT auto-detect from the live
  // cookie here: after an explicit logout (activeAccount cleared) that would
  // immediately resurrect the previous account and trap the user in a loop.
  // Initial auto-activation is handled once by loader.js -> loadAccount().
  return (await getData("activeAccount")) || null;
}

/**
 * Gets all saved Roblox accounts
 * @returns {Promise<Array>} Array of saved accounts
 */
export async function getAllAccounts() {
  // Detect/add a newly logged-in Roblox account (e.g. after "Add via Roblox
  // login") but never steal the active account from an explicit logout/switch.
  await loadAccount({ setActive: false });
  const accounts = (await getData("roblox-accounts")) || [];
  return accounts;
}

export async function setActiveAccount(accountId) {
  if (!accountId) return;
  const accounts = await getAllAccounts();
  const account = accounts.find((account) => account.id === accountId);

  if (!account || !account.cookie) return;
  await setData("activeAccount", account);
  await setRobloxSecurityCookie(account.cookie);
  return account;
}

/**
 * Removes an account from storage
 * @param {string} id - The user ID to remove
 * @returns {Promise<boolean>} Success status
 */
export async function removeAccount(id) {
  if (!id) return false;

  const accounts = (await getData("roblox-accounts")) || [];
  const filteredAccounts = accounts.filter((account) => account.id !== id);

  if (filteredAccounts.length === accounts.length) {
    console.log(`Account ${id} not found in storage`);
    return false;
  }

  await setData("roblox-accounts", filteredAccounts);
  console.log(`Removed account ${id} from storage`);

  // If this was the active account, clear it
  const activeAccount = await getData("activeAccount");
  if (activeAccount && activeAccount.id === id) {
    await setData("activeAccount", null);
    console.log("Cleared active account as it was removed");
  }

  return true;
}

/**
 * Gets the .ROBLOSECURITY cookie by requesting it from the background script
 * @returns {Promise<Object|null>} The cookie object or null if not found
 */
function getRobloxAccount() {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage({ type: "GET_RBLX_ACC" }, (response) => {
      if (chrome.runtime.lastError) {
        reject(chrome.runtime.lastError);
      } else if (response && response.error) {
        reject(new Error(response.error));
      } else {
        resolve(response);
      }
    });
  });
}

function setRobloxSecurityCookie(cookie) {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(
      { type: "SET_ROBLOSECURITY_COOKIE", data: cookie },
      (response) => {
        if (chrome.runtime.lastError) {
          reject(chrome.runtime.lastError);
        } else if (response && response.error) {
          reject(new Error(response.error));
        } else {
          resolve(response.success);
        }
      },
    );
  });
}
