// Import all modules
import userCardModule from "../pages/home/users/index.js";
import serverCardModule from "../pages/game/servers/index.js";
import installPopupModule from "../ui/install/index.js";
import updatePopupModule from "../ui/update/index.js";
import remotePopupModule from "../ui/remote-popup/index.js";
import settingsModule from "../ui/settings/index.js";
import presenceModule from "../pages/home/users/presence/index.js";
import poolsModule from "../pages/home/pools/index.js";
import fptModule from "../pages/fpt/index.js";
import appearanceModule from "../pages/appearance/index.js";
import themeModule from "../pages/home/theme/index.js";

import themeLoader from "../../betterroblox-theme/loader.js";
import { injectTailwindStyles } from "../utils/injectTailwind.js";

// Collection of all modules
const MODULES = [
  settingsModule,
  appearanceModule,
  userCardModule,
  serverCardModule,
  installPopupModule,
  updatePopupModule,
  remotePopupModule,
  presenceModule,
  themeLoader,
  poolsModule,
  fptModule,
  themeModule,
];

export class PageObserver {
  constructor() {
    this.currentPage = null;
    this.activeModules = [];
    this.sweepScheduled = false;
    this.observer = new MutationObserver(this.handleMutations.bind(this));
    // No `attributes: true`: no module selector depends on attribute changes,
    // and checkForElements' own dataset writes generated attribute mutation
    // records that re-triggered a full-document sweep per processed element.
    this.observerConfig = {
      childList: true,
      subtree: true,
    };

    // Inject the settings entry points (gear menu + sidebar button).
    settingsModule.initialize();

    // Initialize all modules
    MODULES.forEach((module) => {
      if (module.initialize && module !== settingsModule) {
        module.initialize();
      }
    });
  }

  init() {
    this.currentPage = this.detectCurrentPage();

    if (document.body) {
      this.startObserving();
    } else {
      const observer = new MutationObserver((mutations, obs) => {
        if (document.body) {
          this.startObserving();
          obs.disconnect();
        }
      });

      observer.observe(document.documentElement, {
        childList: true,
        subtree: true,
      });
    }
  }

  detectCurrentPage() {
    const url = window.location.href;
    if (url.match(/roblox\.com(?:\/[a-z]{2})?\/home/)) return "home";
    if (url.match(/roblox\.com(?:\/[a-z]{2})?\/games\/\d+/)) return "game";
    if (url.match(/roblox\.com(?:\/[a-z]{2})?\/users\/\d+/)) return "profile";
    if (url.match(/roblox\.com(?:\/[a-z]{2})?\/users\/friends/))
      return "friends";
    return "other";
  }

  /** Modules whose `pages` gate matches the current page — computed once, not per sweep. */
  computeActiveModules() {
    this.activeModules = MODULES.filter(
      (module) =>
        module.pages &&
        (module.pages.includes("all") || module.pages.includes(this.currentPage)),
    );
  }

  checkForElements() {
    this.activeModules.forEach((module) => {
      module.selectors.forEach(({ selector, handler, id }) => {
        const elements = document.querySelectorAll(selector);
        elements.forEach((element) => {
          const datasetKey = id
            ? `betterblox${id}Processed`
            : "betterbloxProcessed";
          if (!element.dataset[datasetKey]) {
            element.dataset[datasetKey] = "true";
            handler(element, this.currentPage);
          }
        });
      });
    });
  }

  startObserving() {
    if (this.currentPage != "other") {
      injectTailwindStyles();
    }

    this.computeActiveModules();
    this.observer.observe(document.body, this.observerConfig);
    this.checkForElements();
  }

  // Roblox's React UI mutates the DOM near-continuously; coalesce bursts into
  // one trailing full sweep instead of sweeping per mutation batch.
  handleMutations() {
    if (this.sweepScheduled) return;
    this.sweepScheduled = true;
    setTimeout(() => {
      this.sweepScheduled = false;
      this.checkForElements();
    }, 100);
  }
}
