import { storageManager } from "../../core/storageManager.js";

const appearanceModule = {
    pages: ["all"],
    selectors: [
        {
            selector: "body",
            handler: async (element, currentPage) => {
                // Apply appearance settings when page loads
                await applyAppearanceSettings();

                // Listen for setting changes
                document.addEventListener("betterblox-setting-changed", async (event) => {
                    if (event.detail.id === "show-robux") {
                        await applyRobuxVisibility();
                    }
                });
            },
        },
    ],
};

async function applyAppearanceSettings() {
    await applyRobuxVisibility();
}

async function applyRobuxVisibility() {
    const showRobux = await storageManager.getSettings("show-robux", true);

    // Remove existing style if it exists
    const existingStyle = document.getElementById("betterblox-hide-robux");
    if (existingStyle) {
        existingStyle.remove();
    }

    if (!showRobux) {
        // Create and inject CSS to hide Robux elements
        const style = document.createElement("style");
        style.id = "betterblox-hide-robux";
        style.textContent = `
      /* Hide Robux balance in navigation */
      .rbx-navbar .navbar-nav .navbar-right .navbar-robux,
      .rbx-navbar .navbar-nav .navbar-robux,
      .navbar-robux,
      [data-testid="navigation-robux"],
      [data-testid="nav-robux"],
      [data-testid="robux-balance"],
      .nav-robux-amount,
      .nav-robux,
      .robux-container,
      .currency-container .robux,
      .currency-robux,
      .nav-menu-robux,
      .rbx-navbar-right-robux,
      .navbar-icon-robux,
      .icon-robux-28x28,
      .text-robux-tile,
      .amount-robux,
      /* Modern React component selectors */
      [class*="robux-balance"],
      [class*="RobuxBalance"],
      [class*="currency-robux"],
      [class*="CurrencyRobux"],
      /* Legacy selectors */
      #nav-robux,
      #navbar-robux,
      .navbar-right .nav-robux-amount,
      .navbar-right .robux-container {
        display: none !important;
      }
      
      /* Hide Robux in user menu dropdown */
      .dropdown-menu .nav-robux-amount,
      .dropdown-menu .robux-container,
      .dropdown-menu [data-testid="nav-robux"],
      .dropdown-menu [class*="robux-balance"] {
        display: none !important;
      }
      
      /* Hide Robux in mobile navigation */
      .navbar-collapse .nav-robux-amount,
      .navbar-collapse .robux-container,
      .navbar-collapse [data-testid="nav-robux"] {
        display: none !important;
      }
      
      /* Hide Robux in header currency display */
      .header-menu .nav-robux,
      .header-menu .robux-container,
      .header-menu [data-testid="nav-robux"] {
        display: none !important;
      }
    `;

        document.head.appendChild(style);
        console.log("[BetterBLOX] Robux display hidden");

        // Also hide any existing Robux elements immediately
        hideRobuxElements();

        // Set up observer to hide dynamically loaded Robux elements
        setupRobuxObserver();
    } else {
        console.log("[BetterBLOX] Robux display shown");

        // Remove observer if it exists
        if (window.betterbloxRobuxObserver) {
            window.betterbloxRobuxObserver.disconnect();
            window.betterbloxRobuxObserver = null;
        }
    }
}

function hideRobuxElements() {
    const robuxSelectors = [
        '.navbar-robux',
        '[data-testid="navigation-robux"]',
        '[data-testid="nav-robux"]',
        '[data-testid="robux-balance"]',
        '.nav-robux-amount',
        '.nav-robux',
        '.robux-container',
        '.currency-robux',
        '[class*="robux-balance"]',
        '[class*="RobuxBalance"]',
        '[class*="currency-robux"]',
        '[class*="CurrencyRobux"]'
    ];

    robuxSelectors.forEach(selector => {
        const elements = document.querySelectorAll(selector);
        elements.forEach(element => {
            element.style.display = 'none';
            element.setAttribute('data-betterblox-hidden', 'true');
        });
    });
}

function setupRobuxObserver() {
    if (window.betterbloxRobuxObserver) {
        window.betterbloxRobuxObserver.disconnect();
    }

    window.betterbloxRobuxObserver = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
                if (node.nodeType === Node.ELEMENT_NODE) {
                    // Check if the added node or its children contain Robux elements
                    const robuxElements = node.querySelectorAll ? node.querySelectorAll('[data-testid*="robux"], [class*="robux"], [class*="Robux"]') : [];
                    robuxElements.forEach(element => {
                        element.style.display = 'none';
                        element.setAttribute('data-betterblox-hidden', 'true');
                    });

                    // Also check if the node itself is a Robux element
                    if (node.matches && node.matches('[data-testid*="robux"], [class*="robux"], [class*="Robux"]')) {
                        node.style.display = 'none';
                        node.setAttribute('data-betterblox-hidden', 'true');
                    }
                }
            });
        });
    });

    window.betterbloxRobuxObserver.observe(document.body, {
        childList: true,
        subtree: true
    });
}

export default appearanceModule;
