/**
 * Centralized profile page selectors for BetterBLOX.
 * Fetches selectors from API when configured; falls back to built-in defaults on failure.
 * Use this module so we never target the wrong container (e.g. search bar radix popup).
 */
import { browserAPI } from "./browserAPI.js";

/**
 * API URL for selector config. Set to a string to enable; null/empty to use fallbacks only.
 * You can also set at runtime via chrome.storage.local: key "betterblox_selectors_api_url", value = URL string.
 * API JSON shape: { profileRoot, profilePopup, profileHeaderInsert, profileHeaderInsertFallback?, profileLastOnlineContainer? }
 */
const SELECTORS_API_URL =
  "https://api.betterroblox.com/betterblox/selectors.json"; // e.g. "https://your-api.com/betterblox/selectors.json"

/** Cache: { profileRoot, profilePopupList, profileHeaderInsert } */
let cache = null;

/** Default selectors (used when API is disabled or fails). Scoped to profile only – no search bar. */
const DEFAULTS = {
  /** Single root for profile page – first match is used so we run handlers only once (no cloning). */
  profileRoot: [
    "#user-profile-header-bg",
    "#treatment-redesigned-header",
    "#profile-header-container",
  ],
  /** Popup for "..." menu (Track, etc.). Scoped first; unscoped fallback when popup is portaled to body. We only inject when container has "Inventory" + "Favorites" (isProfileDropdownContainer) so search bar dropdown is never used. */
  profilePopup: [
    "#user-profile-header-bg [id^='radix-'] > div > div",
    "[id^='radix-'] > div > div",
  ],
  /** Container inside profile header where we insert user stats / friend history. */
  profileHeaderInsert: "#user-profile-header-bg > div",
  /** Fallback header for insertion when profileHeaderInsert not found (legacy layout). */
  profileHeaderInsertFallback: [".user-profile-header", ".profile-header-main"],
  /** Container in profile header where "last seen / last online" text is shown (e.g. next to name/connections). */
  profileLastOnlineContainer:
    "#user-profile-header-bg > div > div.user-profile-header-info.flex.justify-between.items-center > div.flex.gap-medium.items-center > div.flex.flex-col",
  /** Element(s) to hide – duplicate "big" Edit Profile / Edit Avatar / "..." that appear when extension is on. Inside header, above Last Online / Time Statistics. */
  profileDuplicateButtonsToHide:
    "#user-profile-header-bg > div > div:nth-child(4)",
};

/**
 * Fetch selectors from API. Expected JSON shape:
 * { profileRoot, profilePopup, profileHeaderInsert, profileHeaderInsertFallback?, profileLastOnlineContainer? }
 */
async function fetchFromApi() {
  const url =
    SELECTORS_API_URL ||
    (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local
      ? await new Promise((resolve) => {
          browserAPI.storage.local.get(["betterblox_selectors_api_url"], (r) =>
            resolve(r.betterblox_selectors_api_url || null),
          );
        })
      : null);
  if (!url || typeof url !== "string") return null;
  try {
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) return null;
    const data = await res.json();
    if (!data || typeof data !== "object") return null;
    return {
      profileRoot: Array.isArray(data.profileRoot)
        ? data.profileRoot
        : DEFAULTS.profileRoot,
      profilePopup: Array.isArray(data.profilePopup)
        ? data.profilePopup
        : DEFAULTS.profilePopup,
      profileHeaderInsert:
        typeof data.profileHeaderInsert === "string"
          ? data.profileHeaderInsert
          : DEFAULTS.profileHeaderInsert,
      profileHeaderInsertFallback: Array.isArray(
        data.profileHeaderInsertFallback,
      )
        ? data.profileHeaderInsertFallback
        : DEFAULTS.profileHeaderInsertFallback,
      profileLastOnlineContainer:
        typeof data.profileLastOnlineContainer === "string"
          ? data.profileLastOnlineContainer
          : DEFAULTS.profileLastOnlineContainer,
      profileDuplicateButtonsToHide:
        data.profileDuplicateButtonsToHide != null
          ? Array.isArray(data.profileDuplicateButtonsToHide)
            ? data.profileDuplicateButtonsToHide
            : [data.profileDuplicateButtonsToHide]
          : Array.isArray(DEFAULTS.profileDuplicateButtonsToHide)
            ? DEFAULTS.profileDuplicateButtonsToHide
            : [DEFAULTS.profileDuplicateButtonsToHide],
    };
  } catch (_) {
    return null;
  }
}

/**
 * Get profile selectors (from API or defaults). Returns same shape as DEFAULTS.
 * @returns {Promise<{ profileRoot: string[], profilePopup: string[], profileHeaderInsert: string, profileHeaderInsertFallback: string[] }>}
 */
export async function getProfileSelectors() {
  if (cache) return cache;
  const fromApi = await fetchFromApi();
  cache = fromApi || { ...DEFAULTS };
  if (!cache.profileLastOnlineContainer)
    cache.profileLastOnlineContainer = DEFAULTS.profileLastOnlineContainer;
  const hideList = cache.profileDuplicateButtonsToHide;
  cache.profileDuplicateButtonsToHide = Array.isArray(hideList)
    ? hideList
    : hideList
      ? [String(hideList)]
      : [];
  return cache;
}

/**
 * Get the single profile root selector string that should be used for the presence module.
 * Returns the first selector from profileRoot that exists on the page, or the first in list.
 */
export function getProfileRootSelector(selectors) {
  const list = selectors?.profileRoot || DEFAULTS.profileRoot;
  for (const sel of list) {
    try {
      if (document.querySelector(sel)) return sel;
    } catch (_) {}
  }
  return list[0] || "#user-profile-header-bg";
}

/**
 * Clear cached selectors (e.g. after API URL change or for tests).
 */
export function clearProfileSelectorsCache() {
  cache = null;
}

export { DEFAULTS };
