import { getPNGIcon } from "../../../../utils/iconManager.js";
import { GlobeViewer } from "./globe_viewer.js";

export default function ContainerComponent(paginationManager) {
  const getDatacenterStats = () => {
    const datacenters = paginationManager.mainClass.datacenters;
    const serverList = paginationManager.mainClass.serverList;

    if (!datacenters) return [];

    // Create a map using location as key (city + country)
    const locationStats = new Map();

    // Initialize stats with datacenter info
    Object.values(datacenters).forEach((dc) => {
      const locationKey = `${dc.location.city}, ${dc.location.country}`;

      if (!locationStats.has(locationKey)) {
        locationStats.set(locationKey, {
          city: dc.location.city,
          country: dc.location.country,
          region: dc.location.region,
          serverCount: 0,
          datacenterIds: new Set(), // Track unique datacenter IDs
        });
      }

      // Add datacenter ID to the set
      locationStats.get(locationKey).datacenterIds.add(dc.id);
    });

    // Count servers per location
    serverList.forEach((server) => {
      if (server.datacenter?.location) {
        const locationKey = `${server.datacenter.location.city}, ${server.datacenter.location.country}`;
        const locationStat = locationStats.get(locationKey);
        if (locationStat) {
          locationStat.serverCount++;
        }
      }
    });

    // Convert to array, filter locations with at least 1 server, and sort by region, then city
    return Array.from(locationStats.values())
      .filter((location) => location.serverCount > 0)
      .sort((a, b) => {
        if (a.region !== b.region) return a.region.localeCompare(b.region);
        return a.city.localeCompare(b.city);
      });
  };

  const generateDatacenterList = (stats) => {
    return stats
      .map(
        (location) => `
        <button 
          class="tw-w-full tw-text-left tw-px-4 tw-py-2 tw-rounded-lg tw-flex tw-flex-col datacenter-button ${paginationManager.filterSettings.datacenters.has(`${location.city}, ${location.country}`) ? "tw-bg-blue-200 dark:tw-bg-blue-800 hover:tw-bg-blue-300 dark:hover:tw-bg-blue-700" : "hover:tw-bg-gray-100 dark:tw-bg-gray-700 dark:hover:tw-bg-gray-600"}"
          data-location="${location.city}, ${location.country}"
        >
          <div class="tw-flex tw-items-center tw-gap-2 tw-justify-between">
            <span class="tw-font-medium">${location.city}, ${
              location.country
            }</span>
            <div class="tw-flex tw-items-center tw-gap-2">
              <span class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">
                ${location.serverCount} servers
              </span>
            </div>
          </div>
          <div class="tw-text-sm tw-text-gray-500 dark:tw-text-gray-400">
            <span>${location.region}</span>
          </div>
        </button>
      `,
      )
      .join("");
  };

  const datacenterListHtml = generateDatacenterList(getDatacenterStats());

  const template = /*html*/ `
    <div id="betterblox-server-filter" class="tw-w-full tw-min-w-0 tw-max-w-full tw-mx-auto tw-box-border tw-px-4 sm:tw-px-6 tw-flex tw-flex-col">
      <div class="tw-container-header tw-flex tw-w-full tw-min-w-0 tw-flex-col tw-gap-2">
        <!-- Title + first filter row on one line -->
        <div class="tw-flex tw-w-full tw-min-w-0 tw-flex-wrap tw-items-center tw-justify-between tw-gap-x-3 tw-gap-y-2">
          <h2 class="container-header-text tw-m-0 tw-flex tw-shrink-0 tw-items-center tw-justify-start tw-gap-2 tw-text-left">
        <img src="${getPNGIcon(
          "logo32",
        )}" alt="BetterBLOX Logo" class="tw-w-4 tw-h-4 tw-shrink-0" />
          BetterBLOX Servers
          </h2>
          <div class="tw-flex tw-min-w-0 tw-flex-1 tw-flex-row tw-flex-wrap tw-gap-2 tw-justify-end">
            <button type="button" id="sort-toggle" class="tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span id="sort-text">Descending</span>
            </button>
            
            <div class="tw-relative">
              <button id="region-filter-button" class="tw-relative tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
                <span>Region</span>
                <span id="region-filter-indicator" class="tw-w-2 tw-h-2 tw-rounded-full tw-bg-gray-400"></span>
                <span id="selected-regions-count" class="tw-absolute tw--top-2 tw--right-2 tw-h-5 tw-w-5 tw-text-xs tw-bg-blue-500 tw-text-white tw-rounded-full tw-flex tw-items-center tw-justify-center tw-hidden">
                  0
                </span>
              </button>
              <div id="region-filter-dropdown" class="tw-hidden tw-absolute tw-z-10 tw-bg-white dark:tw-bg-gray-800 tw-rounded-lg tw-shadow tw-w-[min(800px,90vw)] tw-max-w-[90vw] tw-p-2 tw-left-1/2 tw-transform tw--translate-x-1/2 tw-max-h-[600px]">
                <!-- View Toggle Buttons -->
                <div class="tw-flex tw-gap-2 tw-mb-3 tw-px-2">
                  <button id="globe-view-toggle" class="tw-flex-1 tw-px-4 tw-py-2 tw-bg-blue-500 tw-text-white tw-rounded-lg hover:tw-bg-blue-600 tw-transition-colors">
                    Globe View
                  </button>
                  <button id="list-view-toggle" class="tw-flex-1 tw-px-4 tw-py-2 tw-bg-gray-200 dark:tw-bg-gray-700 tw-text-gray-700 dark:tw-text-gray-300 tw-rounded-lg hover:tw-bg-gray-300 dark:hover:tw-bg-gray-600 tw-transition-colors">
                    List View
                  </button>
                </div>
                
                <!-- Globe View Container -->
                <div id="region-globe-container" class="tw-mb-3">
                  <div id="globe-viewer-wrapper"></div>
                </div>
                
                <!-- List View Container -->
                <div id="region-list-container" class="tw-hidden">
                  <div class="tw-text-sm tw-text-gray-600 dark:tw-text-gray-400 tw-flex tw-justify-between tw-items-center tw-border-b tw-mb-2 tw-pb-2 tw-border-gray-200 dark:tw-border-gray-700 tw-px-4">
                    <span id="region-stats">Loading regions...</span>
                    <span id="region-connection-stats"></span>
                  </div>
                  <button class="tw-w-full tw-text-left tw-px-4 tw-py-2 hover:tw-bg-gray-100 dark:tw-bg-gray-700 dark:hover:tw-bg-gray-600 tw-rounded-lg tw-mb-1">
                    All Regions
                  </button>
                  <div class="tw-border-t tw-border-gray-200 dark:tw-border-gray-700 tw-my-1"></div>
                  <div class="tw-overflow-y-auto tw-max-h-72">
                    <div id="datacenter-list" class="tw-space-y-1">
                      <div class="tw-animate-pulse tw-flex tw-flex-col tw-gap-2 tw-px-4">
                        <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
                        <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
                        <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <button type="button" id="best-connection" class="tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span>Best Connection</span>
              <span id="best-connection-indicator" class="tw-w-2 tw-h-2 tw-rounded-full tw-bg-gray-400"></span>
            </button>

            <button type="button" id="refresh-servers" class="tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span>Refresh</span>
              <span id="refresh-spinner" class="tw-hidden">
                <svg class="tw-animate-spin tw-h-4 tw-w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle class="tw-opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                  <path class="tw-opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </span>
            </button>
            <button type="button" id="reset-filters" class="tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span>Reset</span>
            </button>
          </div>
        </div>

        <div class="btn-more tw-flex tw-w-full tw-flex-row tw-flex-wrap tw-gap-2 tw-justify-end">
          <!-- Second row -->
            <div class="tw-relative">
              <button id="age-filter-button" class="tw-relative tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
                <span>Server Age</span>
                <span id="age-filter-indicator" class="tw-w-2 tw-h-2 tw-rounded-full tw-bg-gray-400"></span>
              </button>
              <div id="age-filter-dropdown" class="tw-hidden tw-absolute tw-z-10 tw-bg-white dark:tw-bg-gray-800 tw-rounded-lg tw-shadow tw-w-48 tw-p-2 tw-left-1/2 tw-transform tw--translate-x-1/2">
                <button class="tw-w-full tw-text-left tw-px-4 tw-py-2 hover:tw-bg-gray-100 dark:tw-bg-gray-700 dark:hover:tw-bg-gray-600 tw-rounded-lg tw-mb-1 tw-age-option" data-age="Oldest">
                  Oldest
                </button>
                <div class="tw-border-t tw-border-gray-200 dark:tw-border-gray-700 tw-my-1"></div>
                <button class="tw-w-full tw-text-left tw-px-4 tw-py-2 hover:tw-bg-gray-100 dark:tw-bg-gray-700 dark:hover:tw-bg-gray-600 tw-rounded-lg tw-age-option" data-age="Newest">
                  Newest
                </button>
              </div>
            </div>
            
            <button type="button" id="old-version-filter" class="tw-hidden tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span>Old Version</span>
              <span id="old-version-indicator" class="tw-w-2 tw-h-2 tw-rounded-full tw-bg-gray-400"></span>
            </button>
            
            <button type="button" id="shuffle-servers-2" class="tw-border-none hover:tw-underline tw-bg-[#ffffff] dark:tw-bg-[#121215] tw-flex tw-items-center tw-gap-1">
              <span>Shuffle</span>
            </button>
        </div>
      </div>
      <!-- <button class="tw-btn-secondary-md btn-more" style="margin-bottom:10px;">Join Fastest Server</button>
      <button class="tw-btn-secondary-md btn-more" style="margin-bottom:10px;">Join Fullest Server</button> -->
      <!-- Status Card -->
      <div id="betterblox-status-card" class="tw-container tw-mx-auto tw-my-4 tw-w-full tw-max-w-6xl tw-bg-white dark:tw-bg-[#393b3d] tw-border tw-border-gray-300 dark:tw-border-gray-700 tw-rounded-lg tw-p-3">
        <div class="tw-flex tw-items-center tw-justify-between">
          <div class="tw-flex tw-items-center tw-gap-3">
            <div id="crawler-status-indicator" class="tw-flex tw-items-center tw-gap-2">
              <div id="status-dot" class="tw-w-2 tw-h-2 tw-rounded-full tw-bg-yellow-500 tw-animate-pulse"></div>
              <span id="status-text" class="tw-text-sm tw-font-medium tw-text-gray-600 dark:tw-text-gray-300">Loading...</span>
            </div>
            <div class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">
              <span id="servers-loaded-count">0</span>/<span id="total-servers-count">0</span> servers • <span id="datacenters-count">0</span> datacenters
              <span id="page-info" class="tw-ml-2 tw-hidden">Page <span id="current-page">0</span></span>
              <span id="crawl-limit-info" class="tw-ml-2">Limit: <span id="crawl-limit-count" class="tw-cursor-pointer hover:tw-text-blue-500 dark:hover:tw-text-blue-400 tw-underline" title="Click to edit">1000</span></span>
            </div>
          </div>
          <div class="tw-flex tw-items-center tw-gap-2">
            <button id="stop-crawler-btn" class="tw-hidden tw-px-3 tw-py-1.5 tw-text-xs tw-font-medium tw-bg-red-500 tw-text-white tw-rounded-md hover:tw-bg-red-600 active:tw-bg-red-700 tw-transition-colors tw-shadow-sm tw-border-0 focus:tw-outline-none focus:tw-ring-2 focus:tw-ring-red-500 focus:tw-ring-opacity-50">
              Stop
            </button>
            <button id="skip-cache-btn" class="tw-hidden tw-px-3 tw-py-1.5 tw-text-xs tw-font-medium tw-bg-orange-500 tw-text-white tw-rounded-md hover:tw-bg-orange-600 active:tw-bg-orange-700 tw-transition-colors tw-shadow-sm tw-border-0 focus:tw-outline-none focus:tw-ring-2 focus:tw-ring-orange-500 focus:tw-ring-opacity-50">
              Skip Cache
            </button>
            <div class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">
              <div class="tw-w-16 tw-bg-gray-200 dark:tw-bg-gray-600 tw-rounded-full tw-h-1.5">
                <div id="progress-bar" class="tw-h-1.5 tw-rounded-full tw-bg-blue-500 tw-transition-all tw-duration-300" style="width: 0%"></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="tw-container tw-w-full tw-min-w-0 tw-max-w-full">
        <!-- Server List Container -->
        <div id="list-view-container" class="tw-w-full tw-min-w-0">
          <div class="tw-my-2 tw-text-sm tw-text-gray-600 dark:tw-text-gray-400 tw-flex tw-flex-wrap tw-gap-x-3 tw-gap-y-1 tw-justify-between tw-items-center tw-border-t tw-pt-2 tw-border-gray-200 dark:tw-border-gray-700">
            <span id="server-stats" class="tw-min-w-0 tw-flex-1">Loading servers...</span>
            <span id="datacenter-stats"></span>
          </div>
          <div id="betterblox-server-list" class="tw-grid sm:tw-grid-cols-2 md:tw-grid-cols-3 xl:tw-grid-cols-4 tw-gap-2 tw-place-items-center">
          </div>
          <button type="button" id="load-more-servers" class="tw-mt-8 tw-box-border tw-block tw-w-full tw-max-w-full tw-rounded-lg tw-border tw-border-solid tw-border-gray-300 tw-bg-white tw-py-1.5 tw-text-center tw-text-sm tw-font-medium tw-text-gray-700 tw-outline-none tw-transition-colors hover:tw-bg-gray-50 focus:tw-outline-none focus:tw-ring-2 focus:tw-ring-blue-500 focus:tw-ring-offset-1 dark:tw-border-gray-700 dark:tw-bg-[#393b3d] dark:tw-text-gray-200 dark:hover:tw-bg-[#434547] dark:focus:tw-ring-offset-[#121215] tw-hidden">
            Load More
          </button>
        </div>
      </div>
    </div>
  `;
  const container = document.createRange().createContextualFragment(template);

  // View state management
  let currentView = "globe"; // Default to globe view
  let globeViewer = null;

  // At the top with other element queries
  const regionFilterIndicator = container.querySelector(
    "#region-filter-indicator",
  );

  // Region popup view toggle elements
  const globeViewToggle = container.querySelector("#globe-view-toggle");
  const listViewToggle = container.querySelector("#list-view-toggle");
  const regionGlobeContainer = container.querySelector(
    "#region-globe-container",
  );
  const regionListContainer = container.querySelector("#region-list-container");
  const globeViewerWrapper = container.querySelector("#globe-viewer-wrapper");

  // Region Dropdown
  const regionButton = container.querySelector("#region-filter-button");
  const regionDropdown = container.querySelector("#region-filter-dropdown");

  // Region popup view toggle functionality
  const toggleRegionView = (view) => {
    currentView = view;

    if (currentView === "globe") {
      // Update button styles
      globeViewToggle.classList.remove(
        "tw-bg-gray-200",
        "dark:tw-bg-gray-700",
        "tw-text-gray-700",
        "dark:tw-text-gray-300",
      );
      globeViewToggle.classList.add("tw-bg-blue-500", "tw-text-white");
      listViewToggle.classList.remove("tw-bg-blue-500", "tw-text-white");
      listViewToggle.classList.add(
        "tw-bg-gray-200",
        "dark:tw-bg-gray-700",
        "tw-text-gray-700",
        "dark:tw-text-gray-300",
      );

      // Show/hide containers
      regionGlobeContainer.classList.remove("tw-hidden");
      regionListContainer.classList.add("tw-hidden");

      // Initialize globe viewer if not already done
      if (!globeViewer) {
        globeViewer = new GlobeViewer(globeViewerWrapper, paginationManager);
        paginationManager.setGlobeViewer(globeViewer);
      } else {
        globeViewer.refresh();
      }
    } else {
      // Update button styles
      listViewToggle.classList.remove(
        "tw-bg-gray-200",
        "dark:tw-bg-gray-700",
        "tw-text-gray-700",
        "dark:tw-text-gray-300",
      );
      listViewToggle.classList.add("tw-bg-blue-500", "tw-text-white");
      globeViewToggle.classList.remove("tw-bg-blue-500", "tw-text-white");
      globeViewToggle.classList.add(
        "tw-bg-gray-200",
        "dark:tw-bg-gray-700",
        "tw-text-gray-700",
        "dark:tw-text-gray-300",
      );

      // Show/hide containers
      regionGlobeContainer.classList.add("tw-hidden");
      regionListContainer.classList.remove("tw-hidden");

      // Update the datacenter list to show current selection state
      const datacenterList = regionDropdown.querySelector("#datacenter-list");
      if (datacenterList) {
        datacenterList.innerHTML = generateDatacenterList(getDatacenterStats());
      }
    }
  };

  // View toggle event listeners
  if (globeViewToggle) {
    globeViewToggle.addEventListener("click", () => toggleRegionView("globe"));
  }
  if (listViewToggle) {
    listViewToggle.addEventListener("click", () => toggleRegionView("list"));
  }

  // Region Event Listeners
  if (regionButton) {
    regionButton.addEventListener("click", async (e) => {
      e.stopPropagation();
      regionDropdown.classList.toggle("tw-hidden");

      if (!regionDropdown.classList.contains("tw-hidden")) {
        // Initialize globe view by default when opening the popup
        toggleRegionView("globe");

        // Also prepare the list view data
        const datacenterList = regionDropdown.querySelector("#datacenter-list");
        if (datacenterList) {
          // Show loading state
          datacenterList.innerHTML = `
            <div class="tw-animate-pulse tw-flex tw-flex-col tw-gap-2 tw-px-4">
              <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
              <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
              <div class="tw-h-12 tw-bg-gray-200 dark:tw-bg-gray-700 tw-rounded"></div>
            </div>
          `;

          // Small delay to show loading state
          await new Promise((resolve) => setTimeout(resolve, 100));
          datacenterList.innerHTML =
            generateDatacenterList(getDatacenterStats());
        }
      }
    });
  }

  // Close dropdowns when clicking outside
  // Stored on a named reference so cleanup() can remove it (avoids leaking a
  // document-level listener on every SPA re-creation of the container).
  const handleRegionOutsideClick = (e) => {
    if (
      regionDropdown &&
      !regionButton?.contains(e.target) &&
      !regionDropdown.contains(e.target)
    ) {
      regionDropdown.classList.add("tw-hidden");
    }
  };
  document.addEventListener("click", handleRegionOutsideClick);

  // Sort toggle handler
  const sortToggle = container.querySelector("#sort-toggle");
  const sortText = container.querySelector("#sort-text");

  if (sortToggle) {
    sortToggle.addEventListener("click", async () => {
      // Toggle between Desc and Asc
      const newOrder = paginationManager.sortOrder === "Desc" ? "Asc" : "Desc";

      // Update button text
      sortText.textContent = newOrder === "Desc" ? "Descending" : "Ascending";

      // Update sort order and refresh
      paginationManager.setSortOrder(newOrder);
    });
  }

  // Refresh functionality
  const refreshButton = container.querySelector("#refresh-servers");
  const refreshSpinner = container.querySelector("#refresh-spinner");

  if (refreshButton) {
    refreshButton.addEventListener("click", async () => {
      // Show spinner
      refreshSpinner.classList.remove("tw-hidden");
      refreshButton.disabled = true;

      try {
        // Call the refresh method from BBloxUI
        await paginationManager.mainClass.refreshServerList();
      } catch (error) {
        console.error("Error refreshing server list:", error);
      } finally {
        // Hide spinner and re-enable button
        refreshSpinner.classList.add("tw-hidden");
        refreshButton.disabled = false;
      }
    });
  }

  // Stop crawler functionality
  const stopCrawlerButton = container.querySelector("#stop-crawler-btn");

  if (stopCrawlerButton) {
    stopCrawlerButton.addEventListener("click", async () => {
      await paginationManager.mainClass.stopCrawler(true);

      paginationManager.mainClass.updateStatus({
        isCrawling: false,
        error: "Crawling stopped by user",
      });
    });
  }

  // Skip cache functionality
  const skipCacheButton = container.querySelector("#skip-cache-btn");

  if (skipCacheButton) {
    skipCacheButton.addEventListener("click", () => {
      // Skip the cache loading
      paginationManager.mainClass.skipCacheLoading();

      // Update status
      paginationManager.mainClass.updateStatus({
        error: null,
      });
    });
  }

  // Editable crawl limit functionality
  const crawlLimitCount = container.querySelector("#crawl-limit-count");

  if (crawlLimitCount) {
    crawlLimitCount.addEventListener("click", () => {
      const currentLimit = paginationManager.mainClass.crawlLimit;
      const newLimit = prompt(
        `Enter new crawl limit (current: ${currentLimit}):`,
        currentLimit,
      );

      if (newLimit !== null) {
        const limit = parseInt(newLimit);
        if (!isNaN(limit) && limit > 0 && limit <= 10000) {
          paginationManager.mainClass.crawlLimit = limit;
          paginationManager.mainClass.status.crawlLimit = limit;
          paginationManager.mainClass.saveCrawlLimit(limit);
          paginationManager.mainClass.updateStatusCard();
        } else {
          alert("Please enter a valid number between 1 and 10000");
        }
      }
    });
  }

  // Best Connection button handler
  const bestConnectionButton = container.querySelector("#best-connection");
  const bestConnectionIndicator = container.querySelector(
    "#best-connection-indicator",
  );

  if (bestConnectionButton) {
    bestConnectionButton.addEventListener("click", async () => {
      // Show loading state
      bestConnectionButton.disabled = true;
      const originalText =
        bestConnectionButton.querySelector("span").textContent;
      bestConnectionButton.querySelector("span").textContent = "Calculating...";

      try {
        await paginationManager.toggleBestConnection();

        // Update visual state
        if (paginationManager.isBestConnection) {
          bestConnectionIndicator.classList.remove("tw-bg-gray-400");
          bestConnectionIndicator.classList.add("tw-bg-green-500");
        } else {
          bestConnectionIndicator.classList.remove("tw-bg-green-500");
          bestConnectionIndicator.classList.add("tw-bg-gray-400");
        }

        // Update other indicators if they were disabled due to mutual exclusivity
        updateMutuallyExclusiveIndicators();
      } catch (error) {
        // Handle error silently
      } finally {
        // Restore button state
        bestConnectionButton.disabled = false;
        bestConnectionButton.querySelector("span").textContent = originalText;
      }
    });
  }

  // Age filter dropdown handler
  const ageFilterButton = container.querySelector("#age-filter-button");
  const ageFilterDropdown = container.querySelector("#age-filter-dropdown");
  const ageFilterIndicator = container.querySelector("#age-filter-indicator");

  if (ageFilterButton) {
    ageFilterButton.addEventListener("click", (e) => {
      e.stopPropagation();
      ageFilterDropdown.classList.toggle("tw-hidden");

      // Update dropdown options to reflect current state when opening
      if (!ageFilterDropdown.classList.contains("tw-hidden")) {
        const ageOptions = ageFilterDropdown.querySelectorAll(".age-option");

        ageOptions.forEach((option) => {
          option.classList.remove(
            "tw-bg-blue-200",
            "dark:tw-bg-blue-800",
            "tw-bg-blue-300",
            "dark:tw-bg-blue-700",
            "hover:tw-bg-gray-100",
            "dark:tw-bg-gray-700",
            "dark:hover:tw-bg-gray-600",
          );
          if (option.dataset.age === paginationManager.ageSort) {
            option.classList.add("tw-bg-blue-200", "dark:tw-bg-blue-800");
          } else {
            option.classList.add(
              "hover:tw-bg-gray-100",
              "dark:tw-bg-gray-700",
              "dark:hover:tw-bg-gray-600",
            );
          }
        });
      }
    });
  }

  // Close age dropdown when clicking outside
  // Stored on a named reference so cleanup() can remove it (avoids leaking a
  // document-level listener on every SPA re-creation of the container).
  const handleAgeOutsideClick = (e) => {
    if (
      ageFilterDropdown &&
      !ageFilterButton?.contains(e.target) &&
      !ageFilterDropdown.contains(e.target)
    ) {
      ageFilterDropdown.classList.add("tw-hidden");
    }
  };
  document.addEventListener("click", handleAgeOutsideClick);

  // Age option click handler
  const handleAgeOptionClick = (e) => {
    e.preventDefault();
    e.stopPropagation();

    const button = e.target.closest(".age-option");
    if (!button) return;

    const ageValue = button.dataset.age;

    // Calculate what the new ageSort will be after the toggle
    let newAgeSort;
    if (paginationManager.ageSort === ageValue) {
      newAgeSort = null; // Will be disabled
    } else {
      newAgeSort = ageValue; // Will be set to this value
    }

    // Update pagination manager
    paginationManager.setAgeSort(ageValue);

    // Update visual state based on the new value
    const ageOptions = ageFilterDropdown.querySelectorAll(".age-option");

    ageOptions.forEach((option) => {
      option.classList.remove(
        "tw-bg-blue-200",
        "dark:tw-bg-blue-800",
        "tw-bg-blue-300",
        "dark:tw-bg-blue-700",
        "hover:tw-bg-gray-100",
        "dark:tw-bg-gray-700",
        "dark:hover:tw-bg-gray-600",
      );
    });

    // Only highlight if newAgeSort is not null (not disabled)
    if (newAgeSort) {
      button.classList.add("tw-bg-blue-200", "dark:tw-bg-blue-800");
    }

    // Restore hover classes for non-selected options
    ageOptions.forEach((option) => {
      if (!option.classList.contains("tw-bg-blue-200")) {
        option.classList.add(
          "hover:tw-bg-gray-100",
          "dark:tw-bg-gray-700",
          "dark:hover:tw-bg-gray-600",
        );
      }
    });

    // Update indicator based on the new value
    if (ageFilterIndicator) {
      if (newAgeSort) {
        ageFilterIndicator.classList.remove("tw-bg-gray-400");
        ageFilterIndicator.classList.add("tw-bg-teal-500");
      } else {
        ageFilterIndicator.classList.remove("tw-bg-teal-500");
        ageFilterIndicator.classList.add("tw-bg-gray-400");
      }
    }

    // Update other indicators if they were disabled due to mutual exclusivity
    updateMutuallyExclusiveIndicators();

    // Close dropdown after selection
    ageFilterDropdown.classList.add("tw-hidden");
  };

  // Add click handler for age options
  const ageOptions = ageFilterDropdown.querySelectorAll(".age-option");
  ageOptions.forEach((option) => {
    option.addEventListener("click", handleAgeOptionClick);
  });

  // Second shuffle button handler
  const shuffleButton2 = container.querySelector("#shuffle-servers-2");

  if (shuffleButton2) {
    shuffleButton2.addEventListener("click", () => {
      paginationManager.toggleShuffle2();
    });
  }

  // Old Version filter button handler
  const oldVersionFilterButton = container.querySelector("#old-version-filter");
  const oldVersionIndicator = container.querySelector("#old-version-indicator");

  if (oldVersionFilterButton) {
    oldVersionFilterButton.addEventListener("click", () => {
      paginationManager.setOldVersionSort();

      // Update visual state
      if (paginationManager.oldVersionSort) {
        oldVersionIndicator.classList.remove("tw-bg-gray-400");
        oldVersionIndicator.classList.add("tw-bg-orange-500");
      } else {
        oldVersionIndicator.classList.remove("tw-bg-orange-500");
        oldVersionIndicator.classList.add("tw-bg-gray-400");
      }
    });
  }

  const serverStats = container.querySelector("#server-stats");
  const datacenterStats = container.querySelector("#datacenter-stats");

  // Function to update stats
  const updateStats = () => {
    const stats = getDatacenterStats();
    const totalServers = paginationManager.mainClass.serverList.length;
    const loadedServers = paginationManager.elementList.length;
    const uniqueLocations = stats.length;
    const join = paginationManager.mainClass.getJoinDataBreakdown();

    // Update main stats (list view + join enrichment breakdown)
    let statsText = `Showing ${loadedServers} of ${totalServers} servers · Resolved ${join.successful} · In pool ${join.inPool} · Failed ${join.failed}`;
    if (join.unknown > 0) {
      statsText += ` · No region ${join.unknown}`;
    }
    serverStats.textContent = statsText;
    datacenterStats.textContent = `${uniqueLocations} locations`;

    // Check if there are old version servers and show/hide the filter
    const hasOldServers = paginationManager.mainClass.hasOldVersionServers();
    const oldVersionFilter = document.querySelector("#old-version-filter");

    if (oldVersionFilter) {
      if (hasOldServers) {
        oldVersionFilter.classList.remove("tw-hidden");
      } else {
        oldVersionFilter.classList.add("tw-hidden");
        // Reset the filter if no old servers are present
        if (paginationManager.oldVersionSort) {
          paginationManager.oldVersionSort = null;
          const oldVersionIndicator = container.querySelector(
            "#old-version-indicator",
          );
          if (oldVersionIndicator) {
            oldVersionIndicator.classList.remove("tw-bg-orange-500");
            oldVersionIndicator.classList.add("tw-bg-gray-400");
          }
        }
      }
    }

    // Update region dropdown stats if it exists
    const regionStats = document.querySelector("#region-stats");
    const regionConnectionStats = document.querySelector(
      "#region-connection-stats",
    );

    if (regionStats) {
      regionStats.textContent = `${uniqueLocations} locations available`;
    }

    if (regionConnectionStats) {
      regionConnectionStats.innerHTML = ""; // No connection stats to show anymore
    }

    // Update region dropdown if it's open
    if (regionDropdown && !regionDropdown.classList.contains("tw-hidden")) {
      const datacenterList = regionDropdown.querySelector("#datacenter-list");
      if (datacenterList) {
        datacenterList.innerHTML = generateDatacenterList(getDatacenterStats());
      }
    }
  };

  // Update stats when servers are loaded/refreshed
  const originalHandleServerListRefresh =
    paginationManager.handleServerListRefresh;
  paginationManager.handleServerListRefresh = async function () {
    await originalHandleServerListRefresh.call(this);
    updateStats();
    // Update status card
    paginationManager.mainClass.updateStatusCard();
  };

  // Update stats when new servers are added
  const originalCreateServerCard = paginationManager.mainClass.createServerCard;
  paginationManager.mainClass.createServerCard = async function (server) {
    await originalCreateServerCard.call(this, server);
    updateStats();
  };

  // Initial stats update
  updateStats();

  // Handle datacenter selection
  const handleDatacenterClick = (e) => {
    e.preventDefault();
    e.stopPropagation();

    const button = e.target.closest(".datacenter-button");
    if (!button) return;

    const location = button.dataset.location;
    const isSelected = !button.classList.contains("tw-bg-blue-200");

    // Update button appearance
    if (isSelected) {
      button.classList.add(
        "tw-bg-blue-200",
        "dark:tw-bg-blue-800",
        "hover:tw-bg-blue-300",
        "dark:hover:tw-bg-blue-700",
      );
    } else {
      button.classList.remove(
        "tw-bg-blue-200",
        "dark:tw-bg-blue-800",
        "hover:tw-bg-blue-300",
        "dark:hover:tw-bg-blue-700",
      );
    }

    paginationManager.setDatacenterFilter(location, isSelected);
    updateRegionCount();

    // Update region indicator immediately
    if (regionFilterIndicator) {
      if (paginationManager.filterSettings.datacenters.size > 0) {
        regionFilterIndicator.classList.remove("tw-bg-gray-400");
        regionFilterIndicator.classList.add("tw-bg-blue-500");
      } else {
        regionFilterIndicator.classList.remove("tw-bg-blue-500");
        regionFilterIndicator.classList.add("tw-bg-gray-400");
      }
    }
  };

  // Update All Regions button handler
  const allRegionsButton = container.querySelector(
    "#region-filter-dropdown button",
  );
  if (allRegionsButton) {
    allRegionsButton.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();

      // Clear all button backgrounds
      const buttons = container.querySelectorAll(".datacenter-button");
      buttons.forEach((button) => {
        button.classList.remove(
          "tw-bg-blue-200",
          "dark:tw-bg-blue-800",
          "hover:bg-blue-300",
          "dark:hover:tw-bg-blue-700",
        );
      });

      paginationManager.clearDatacenterFilters();
      updateRegionCount();

      // Update region indicator immediately
      if (regionFilterIndicator) {
        regionFilterIndicator.classList.remove("tw-bg-blue-500");
        regionFilterIndicator.classList.add("tw-bg-gray-400");
      }
    });
  }

  // Add click handler for datacenter list
  const datacenterList = container.querySelector("#datacenter-list");
  if (datacenterList) {
    datacenterList.addEventListener("click", handleDatacenterClick);
  }

  // Update the selected regions count badge
  const updateRegionCount = () => {
    const badge = container.querySelector("#selected-regions-count");
    if (!badge) return; // Early return if badge doesn't exist

    const selectedCount = paginationManager.filterSettings.datacenters.size;

    if (selectedCount > 0) {
      badge.textContent = selectedCount;
      badge.classList.remove("tw-hidden");
    } else {
      badge.classList.add("tw-hidden");
    }
  };

  // Add update functions for indicators
  const updateFilterIndicators = () => {
    // Update region filter indicator
    const regionFilterIndicator = container.querySelector(
      "#region-filter-indicator",
    );
    if (regionFilterIndicator) {
      if (paginationManager.filterSettings.datacenters.size > 0) {
        regionFilterIndicator.classList.remove("tw-bg-gray-400");
        regionFilterIndicator.classList.add("tw-bg-blue-500");
      } else {
        regionFilterIndicator.classList.remove("tw-bg-blue-500");
        regionFilterIndicator.classList.add("tw-bg-gray-400");
      }
    }
  };

  // Update mutually exclusive filter indicators
  const updateMutuallyExclusiveIndicators = () => {
    // Update age filter indicator
    if (ageFilterIndicator) {
      if (paginationManager.ageSort) {
        ageFilterIndicator.classList.remove("tw-bg-gray-400");
        ageFilterIndicator.classList.add("tw-bg-teal-500");
      } else {
        ageFilterIndicator.classList.remove("tw-bg-teal-500");
        ageFilterIndicator.classList.add("tw-bg-gray-400");
      }
    }

    // Update best connection indicator
    if (bestConnectionIndicator) {
      if (paginationManager.isBestConnection) {
        bestConnectionIndicator.classList.remove("tw-bg-gray-400");
        bestConnectionIndicator.classList.add("tw-bg-green-500");
      } else {
        bestConnectionIndicator.classList.remove("tw-bg-green-500");
        bestConnectionIndicator.classList.add("tw-bg-gray-400");
      }
    }
  };

  // Also ensure the initial call to updateRegionCount happens after the container is created
  const init = () => {
    updateRegionCount();
    updateStats();
    updateFilterIndicators();
    updateMutuallyExclusiveIndicators();
    // Initialize status card
    paginationManager.mainClass.updateStatusCard();
  };

  init();

  // Add reset handler
  const resetButton = container.querySelector("#reset-filters");
  if (resetButton) {
    resetButton.addEventListener("click", () => {
      // Reset pagination (this will also clear the server list)
      paginationManager.reset();

      // Reset UI elements

      // Reset region selection
      const datacenterButtons =
        container.querySelectorAll(".datacenter-button");
      datacenterButtons.forEach((button) => {
        button.classList.remove(
          "tw-bg-blue-200",
          "dark:tw-bg-blue-800",
          "hover:bg-blue-300",
          "dark:hover:tw-bg-blue-700",
        );
      });

      // Reset sort toggle
      if (sortToggle && sortText) {
        sortText.textContent = "Descending";
      }

      // Reset age filter
      if (ageFilterIndicator) {
        ageFilterIndicator.classList.remove("tw-bg-teal-500");
        ageFilterIndicator.classList.add("tw-bg-gray-400");
      }

      // Reset age options visual state
      const ageOptions = ageFilterDropdown.querySelectorAll(".age-option");
      ageOptions.forEach((option) => {
        option.classList.remove(
          "tw-bg-blue-200",
          "dark:tw-bg-blue-800",
          "tw-bg-blue-300",
          "dark:tw-bg-blue-700",
          "hover:tw-bg-gray-100",
          "dark:tw-bg-gray-700",
          "dark:hover:tw-bg-gray-600",
        );
        option.classList.add(
          "hover:tw-bg-gray-100",
          "dark:tw-bg-gray-700",
          "dark:hover:tw-bg-gray-600",
        );
      });

      // Reset age sort to null (disabled)
      paginationManager.ageSort = null;

      // Reset old version sort to null (disabled)
      paginationManager.oldVersionSort = null;

      // Reset old version indicator
      if (oldVersionIndicator) {
        oldVersionIndicator.classList.remove("tw-bg-orange-500");
        oldVersionIndicator.classList.add("tw-bg-gray-400");
      }

      // Reset all indicators
      const indicators = [regionFilterIndicator, bestConnectionIndicator];
      indicators.forEach((indicator) => {
        if (indicator) {
          indicator.classList.remove(
            "tw-bg-blue-500",
            "tw-bg-green-500",
            "tw-bg-teal-500",
            "tw-bg-purple-500",
            "tw-bg-orange-500",
          );
          indicator.classList.add("tw-bg-gray-400");
        }
      });

      // Reset region count badge
      const regionCountBadge = container.querySelector(
        "#selected-regions-count",
      );
      if (regionCountBadge) {
        regionCountBadge.classList.add("tw-hidden");
      }

      // Close any open dropdowns
      if (regionDropdown) regionDropdown.classList.add("tw-hidden");
    });
  }

  // Add cleanup function for when container is destroyed
  const cleanup = () => {
    if (globeViewer) {
      globeViewer.destroy();
      globeViewer = null;
    }

    // Remove document-level outside-click listeners so they don't accumulate
    // when the container is re-created (SPA navigation).
    document.removeEventListener("click", handleRegionOutsideClick);
    document.removeEventListener("click", handleAgeOutsideClick);
  };

  // Expose cleanup/update functions on the ROOT ELEMENT node, not the
  // DocumentFragment. A fragment's expando properties are NOT carried onto its
  // child nodes, and insertBefore() drains the fragment — so attaching them to
  // `container` made them undefined after insertion (dead updateStats/cleanup).
  // The caller re-queries #betterblox-server-filter from the DOM, so the
  // handles must live on that element.
  const rootElement = container.querySelector("#betterblox-server-filter");
  if (rootElement) {
    rootElement.cleanup = cleanup;
    rootElement.updateStats = updateStats;
    rootElement.updateFilterIndicators = updateFilterIndicators;
    rootElement.updateRegionCount = updateRegionCount;
  }

  return container;
}
