import { getPNGIcon } from "../../utils/iconManager.js";
import { injectTailwindStyles } from "../../utils/injectTailwind.js";

const updatePopupModule = {
  async initialize() {
    try {
      // Get both installation status and last seen version
      const { installedBefore, lastSeenVersion } = await chrome.storage.local.get(["installedBefore", "lastSeenVersion"]);

      // Only show update popup if user has already seen welcome popup
      if (installedBefore) {
        const currentVersion = chrome.runtime.getManifest().version;
        if (lastSeenVersion && lastSeenVersion !== currentVersion) {
          // Wait for DOM to be ready
          if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", () => showChangelogPopup(currentVersion));
          } else {
            showChangelogPopup(currentVersion);
          }
        }
        await chrome.storage.local.set({ lastSeenVersion: currentVersion });
      }
    } catch (error) {
      console.error("Error checking version status:", error);
    }
  },
};

async function showChangelogPopup(version) {
  injectTailwindStyles();

  try {
    // Fetch changelog
    const response = await fetch(chrome.runtime.getURL("changelog.json"));
    const changelog = await response.json();

    const popup = document.createElement("div");
    popup.id = "timeline-modal";
    popup.setAttribute("tabindex", "-1");
    popup.setAttribute("aria-hidden", "false");
    popup.className = "tw-overflow-y-auto tw-overflow-x-hidden tw-fixed tw-top-0 tw-right-0 tw-left-0 tw-z-50 tw-flex tw-justify-center tw-items-center tw-w-full md:tw-inset-0 tw-h-full tw-max-h-full tw-bg-gray-900/50";

    popup.innerHTML = `
      <div class="tw-relative tw-p-4 tw-w-full tw-max-w-md tw-max-h-full">
        <div class="tw-relative tw-bg-white tw-rounded-lg tw-shadow dark:tw-bg-gray-700">
          <!-- Modal header -->
          <div class="tw-flex tw-items-center tw-justify-between tw-p-4 md:tw-p-5 tw-rounded-t dark:tw-border-gray-600 tw-bg-gray-50 dark:tw-bg-gray-700" style="border-bottom: solid">
            <h3 class="tw-text-xl tw-font-semibold tw-text-gray-900 dark:tw-text-white tw-flex tw-items-center tw-gap-2">
              <img src="${getPNGIcon("logo32")}" alt="BetterBLOX Logo" class="tw-w-5 tw-h-5" />
              BetterBLOX Updated!
            </h3>
            <button type="button" id="closeChangelogPopup" class="tw-border-none tw-text-gray-400 tw-bg-transparent hover:tw-bg-gray-200 hover:tw-text-gray-900 tw-rounded-lg tw-text-sm tw-w-8 tw-h-8 tw-ms-auto tw-inline-flex tw-justify-center tw-items-center dark:hover:tw-bg-gray-600 dark:hover:tw-text-white tw-transition-colors tw-duration-200">
              <svg class="tw-w-3 tw-h-3" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 14 14">
                <path stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m1 1 6 6m0 0 6 6M7 7l6-6M7 7l-6 6" />
              </svg>
              <span class="tw-sr-only">Close modal</span>
            </button>
          </div>
          <!-- Modal body -->
          <div class="tw-p-4 md:tw-p-5">
            <div class="tw-max-h-[60vh] tw-overflow-y-auto tw-mb-4 [&::-webkit-scrollbar]:tw-w-2 [&::-webkit-scrollbar-track]:tw-bg-transparent [&::-webkit-scrollbar-thumb]:tw-bg-gray-300 [&::-webkit-scrollbar-thumb]:tw-rounded-full dark:[&::-webkit-scrollbar-thumb]:tw-bg-gray-500">
              <ol class="tw-relative tw-border-gray-200 dark:tw-border-gray-600 tw-ms-3.5 tw-space-y-10" style="border-left: solid">
                ${Object.entries(changelog)
                  .sort(([verA], [verB]) => {
                    // Sort versions in descending order
                    const partsA = verA.split(".").map(Number);
                    const partsB = verB.split(".").map(Number);
                    for (let i = 0; i < 3; i++) {
                      if (partsA[i] !== partsB[i]) return partsB[i] - partsA[i];
                    }
                    return 0;
                  })
                  .map(
                    ([ver, data]) => `
                    <li class="tw-ms-8">
                      <span class="tw-absolute tw-flex tw-items-center tw-justify-center tw-w-8 tw-h-8 tw-bg-blue-100 tw-rounded-full tw--start-4 tw-ring-4 tw-ring-white dark:tw-ring-gray-700 dark:tw-bg-blue-900">
                        <svg class="tw-w-3.5 tw-h-3.5 tw-text-blue-800 dark:tw-text-blue-300" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M20 4a2 2 0 0 0-2-2h-2V1a1 1 0 0 0-2 0v1h-3V1a1 1 0 0 0-2 0v1H6V1a1 1 0 0 0-2 0v1H2a2 2 0 0 0-2 2v2h20V4ZM0 18a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8H0v10Zm5-8h10a1 1 0 0 1 0 2H5a1 1 0 0 1 0-2Z" />
                        </svg>
                      </span>
                      <h3 class="tw-flex tw-items-start tw-mb-1 tw-text-lg tw-font-semibold tw-text-gray-900 dark:tw-text-white">
                        BetterBLOX v${ver} ${ver === version ? '<span class="tw-bg-blue-100 tw-text-blue-800 tw-text-sm tw-font-medium tw-mr-2 tw-px-2.5 tw-py-0.5 tw-rounded dark:tw-bg-blue-900 dark:tw-text-blue-300 tw-ms-3">Latest</span>' : ""}
                      </h3>
                      <time class="tw-block tw-mb-3 tw-text-sm tw-font-normal tw-leading-none tw-text-gray-600 dark:tw-text-gray-400">Released: ${data.date}</time>
                      <ul class="tw-space-y-1 tw-list-disc tw-list-inside tw-text-gray-700 dark:tw-text-gray-300">
                        ${data.changes
                          .map((change) => {
                            let type = "";
                            let color = "";

                            if (change.toLowerCase().includes("added")) {
                              type = "Added:";
                              color = "tw-text-green-600 dark:tw-text-green-400";
                            } else if (change.toLowerCase().includes("improved") || change.toLowerCase().includes("updated")) {
                              type = "Improved:";
                              color = "tw-text-blue-600 dark:tw-text-blue-400";
                            } else if (change.toLowerCase().includes("fixed")) {
                              type = "Fixed:";
                              color = "tw-text-red-600 dark:tw-text-red-400";
                            } else if (change.toLowerCase().includes("removed")) {
                              type = "Removed:";
                              color = "tw-text-red-600 dark:tw-text-red-400";
                            }

                            const changeText = change.replace(/^(Added|Improved|Fixed|Removed):?\s*/i, "");

                            return `
                            <li>
                              ${type ? `<span class="tw-font-medium ${color}">${type}</span> ` : ""}
                              ${changeText}
                            </li>
                          `;
                          })
                          .join("")}
                      </ul>
                    </li>
                  `
                  )
                  .join("")}
              </ol>
            </div>
            <div class="tw-mb-4 tw-p-4 tw-text-sm tw-text-blue-800 tw-rounded-lg tw-bg-blue-50 dark:tw-bg-gray-800 dark:tw-text-blue-400" role="alert">
              <span class="tw-font-medium">Need help or have suggestions?</span>
              Visit <a href="https://betterroblox.com/contact" target="_blank" rel="noopener noreferrer" class="tw-font-semibold tw-underline hover:tw-text-blue-600 dark:hover:tw-text-blue-300">BetterBLOX support</a>
              for problems, bugs, feedback, or suggestions.
            </div>
            <button id="closeChangelogButton" class="tw-border-none tw-text-white tw-inline-flex tw-w-full tw-justify-center tw-items-center tw-bg-blue-700 hover:tw-bg-blue-800 focus:tw-ring-4 focus:tw-outline-none focus:tw-ring-blue-300 tw-font-medium tw-rounded-lg tw-text-sm tw-px-5 tw-py-2.5 tw-text-center dark:tw-bg-blue-600 dark:hover:tw-bg-blue-700 dark:focus:tw-ring-blue-800 tw-transition-colors tw-duration-200 tw-gap-2">
              Got it!
            </button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(popup);

    // Add click handlers for both close buttons
    document.getElementById("closeChangelogPopup").onclick = () => popup.remove();
    document.getElementById("closeChangelogButton").onclick = () => popup.remove();
  } catch (error) {
    console.error("Error showing changelog:", error);
  }
}

export default updatePopupModule;
