import { PageObserver } from "./betterblox-frontend/core/pageManager.js";
import { storageManager } from "./betterblox-frontend/core/storageManager.js";
import { waitForSelector } from "./betterblox-frontend/utils/selectorManager.js";

// Initialize storage manager first
await storageManager.initialize();

// Initialize page observer
const pageObserver = new PageObserver();
pageObserver.init();

console.log("[BETTERBLOX] Betterblox is running");
const body = document.body;
if (body) {
  const hasDark = body.classList.contains("dark-theme");
  if (hasDark) {
    body.classList.add("tw-dark-theme");
  } else {
    body.classList.remove("tw-dark-theme");
  }
}
