import { getPNGIcon } from "../../utils/iconManager.js";
import { injectTailwindStyles } from "../../utils/injectTailwind.js";

const installPopupModule = {
  async initialize() {
    try {
      const result = await chrome.storage.local.get("installedBefore");

      if (!result.installedBefore) {
        // Wait for DOM to be ready
        if (document.readyState === "loading") {
          document.addEventListener("DOMContentLoaded", showWelcomePopup);
        } else {
          showWelcomePopup();
        }

        // Set the flag so it won't show again
        await chrome.storage.local.set({ installedBefore: true });
      }
    } catch (error) {
      console.error("Error checking installation status:", error);
    }
  },
};

function showWelcomePopup() {
  injectTailwindStyles();

  const popup = document.createElement("div");
  popup.id = "welcome-modal";
  popup.setAttribute("tabindex", "-1");
  popup.setAttribute("aria-hidden", "false");
  popup.className = "tw-overflow-y-auto tw-overflow-x-hidden tw-fixed tw-top-0 tw-right-0 tw-left-0 tw-z-50 tw-flex tw-justify-center tw-items-center tw-w-full md:tw-inset-0 tw-h-full tw-max-h-full tw-bg-gray-900/50";

  popup.innerHTML = `
    <div class="tw-relative tw-p-4 tw-w-full tw-max-w-md tw-max-h-full">
      <div class="tw-relative tw-bg-white tw-rounded-lg tw-shadow dark:tw-bg-gray-700">
        <!-- Modal header -->
        <div class="tw-flex tw-items-center tw-justify-between tw-p-4 md:tw-p-5 tw-rounded-t dark:tw-border-gray-600 tw-bg-gray-50 dark:tw-bg-gray-700" style="border-bottom: solid">
          <h3 class="tw-w-full tw-text-xl tw-font-semibold tw-text-gray-900 dark:tw-text-white tw-flex tw-items-center tw-justify-center tw-gap-2">
            <img src="${getPNGIcon("logo32")}" alt="BetterBLOX Logo" class="tw-w-6 tw-h-6" />
            Welcome to BetterBLOX!
          </h3>
        </div>
        <!-- Modal body -->
        <div class="tw-p-4 md:tw-p-5 tw-space-y-4">
          <!-- Important Notice Section -->
          <div class="tw-p-4 tw-text-sm tw-text-yellow-800 tw-rounded-lg tw-bg-yellow-50 dark:tw-bg-yellow-900/30 dark:tw-text-yellow-300 tw-border-l-4 tw-border-yellow-400" role="alert">
            <p class="tw-font-semibold tw-mb-2">Important Notice:</p>
            <ul class="tw-list-disc tw-ml-4 tw-space-y-1">
              <li>Please allow up to 5 minutes after installation for the extension to properly initialize and update its settings.</li>
              <li>Friends' last online presence data may take up to 24 hours to fully synchronize.</li>
              <li>If you experience any issues during this period, please contact support from betterroblox.com/contact.</li>
            </ul>
          </div>

          <!-- Main Info Section -->
          <div class="tw-p-4 tw-text-sm tw-text-blue-800 tw-rounded-lg tw-bg-blue-50 dark:tw-bg-blue-900/30 dark:tw-text-blue-300 tw-border-l-4 tw-border-blue-400">
            <p class="tw-mb-3">We're committed to enhancing your Roblox experience with powerful features and continuous improvements.</p>
            <p class="tw-mb-2">Use the BetterBLOX website to:</p>
            <ul class="tw-list-disc tw-ml-4 tw-mb-3">
              <li>Get support and troubleshooting help</li>
              <li>Report bugs and technical issues</li>
              <li>Suggest new features and improvements</li>
              <li>Read release notes and updates</li>
            </ul>
          </div>

          <a href="https://betterroblox.com/contact" target="_blank" class="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-bg-blue-700 hover:tw-bg-blue-800 tw-text-white tw-px-4 tw-py-2.5 tw-rounded-lg tw-transition-colors tw-duration-200">
            Contact Support
          </a>

          <!-- Close Button -->
          <button id="closeWelcomePopup" class="tw-w-full tw-border-none tw-text-white tw-inline-flex tw-justify-center tw-items-center tw-bg-blue-700 hover:tw-bg-blue-800 focus:tw-ring-4 focus:tw-outline-none focus:tw-ring-blue-300 tw-font-medium tw-rounded-lg tw-text-sm tw-px-5 tw-py-2.5 tw-text-center dark:tw-bg-blue-600 dark:hover:tw-bg-blue-700 dark:focus:tw-ring-blue-800 tw-transition-colors tw-duration-200">
            Got it!
          </button>

          <!-- Footer -->
          <div class="tw-text-xs tw-text-center tw-text-gray-500 dark:tw-text-gray-400">
            Created with ❤️ by <a href="https://github.com/AlloryDante" target="_blank" class="tw-text-blue-500 hover:tw-text-blue-600">Allory Dante</a>
          </div>
        </div>
      </div>
    </div>
  `;

  document.body.appendChild(popup);

  document.getElementById("closeWelcomePopup").onclick = () => {
    popup.remove();
  };
}

export default installPopupModule;
