import { storageManager } from "../../../../core/storageManager.js";
import { getSVGIcon } from "../../../../utils/iconManager.js";

export async function addNotifyOnlineEnhancements(element) {
  const uid = getUserIdFromElement(element);
  if (!uid) return;

  const notifyOnline = await storageManager.getSettings("friends-online-notify", true);
  if (!notifyOnline) return;

  const ulElement = element.querySelector("ul");
  if (!ulElement) return;

  addNotifyOnlineButton(ulElement, uid);
  // Future buttons can be added here
  // addOtherButton(ulElement, uid);
}

function addNotifyOnlineButton(ulElement, userId) {
  const liElement = document.createElement("li");
  const actionButton = createActionButton();
  const buttonContent = createButtonContent();
  const icon = createIcon();

  // Check initial state and setup button
  checkNotifyOnlineStatus(userId).then((isNotifyOnline) => {
    updateButtonState(buttonContent, icon, isNotifyOnline);
  });

  // Add click handler
  actionButton.addEventListener("click", async () => {
    const newStatus = await toggleNotifyOnline(userId);
    updateButtonState(buttonContent, icon, newStatus);
  });

  // Assemble the button
  buttonContent.appendChild(icon);
  actionButton.appendChild(buttonContent);
  liElement.appendChild(actionButton);
  ulElement.appendChild(liElement);
}

function createActionButton() {
  const button = document.createElement("button");
  button.className = "friend-tile-dropdown-button";
  return button;
}

function createButtonContent() {
  const content = document.createElement("div");
  content.style.display = "flex";
  content.style.alignItems = "center";
  content.style.gap = "5px";
  return content;
}

function createIcon() {
  const icon = document.createElement("img");
  icon.src = getSVGIcon("user-online");
  icon.style.width = "26px";
  icon.style.height = "26px";
  icon.className = "dark:tw-brightness-0 dark:tw-invert";
  return icon;
}

function getUserIdFromElement(element) {
  try {
    const url = element.parentElement.parentElement.parentElement.querySelector("a").href;
    const userId = url.split("/")[4];
    return userId;
  } catch (error) {
    console.error("OnlineNotify: Error getting user ID from element");
    return null;
  }
}

async function checkNotifyOnlineStatus(userId) {
  const notifyOnline = await storageManager.get("notifyOnline", []);
  return notifyOnline.includes(userId);
}

async function toggleNotifyOnline(userId) {
  const notifyOnline = await storageManager.get("notifyOnline", []);

  let newNotifyOnline;
  if (notifyOnline.includes(userId)) {
    newNotifyOnline = notifyOnline.filter((id) => id !== userId);
  } else {
    newNotifyOnline = [...notifyOnline, userId];
  }

  await storageManager.set("notifyOnline", newNotifyOnline);
  return newNotifyOnline.includes(userId);
}

function updateButtonState(buttonContent, icon, isNotifyOnline) {
  // Remove existing text node if it exists
  const existingText = buttonContent.querySelector(".button-text");
  if (existingText) {
    existingText.remove();
  }

  // Create new text node with a class for easier selection
  const textNode = document.createElement("span");
  textNode.className = `button-text ${isNotifyOnline ? "tw-text-[#0095ff] dark:tw-text-[#0095ff]" : ""}`;
  textNode.textContent = isNotifyOnline ? "Disable Online Notification" : "Notify when Online";
  buttonContent.appendChild(textNode);

  // Update icon color - blue in both light and dark mode when active
  if (isNotifyOnline) {
    icon.style.filter = "invert(46%) sepia(99%) saturate(1426%) hue-rotate(197deg) brightness(99%) contrast(96%)";
    icon.className = "";
  } else {
    icon.style.filter = "";
    icon.className = "dark:tw-brightness-0 dark:tw-invert";
  }
}
