import { loadAccount } from "./accountManager.js";
import { handleMessage, initMessageHandler } from "./messageHandler.js";

// Store original history function before any monkeypatching
const originalReplaceState = History.prototype.replaceState;

// Dynamic Origin detection - will be set by detectEnvironment()
let Origin = null;

let initialized = false;
let iframeRef;
let initialPageLoaded = false;
let routeConfigurations = null;
let lastConfigFetch = 0;
const CONFIG_CACHE_DURATION = 1000 * 60 * 60; // 1 hour

const themeLoader = {
  async initialize() {
    // Detect environment and set Origin if not already set

    // Check if theme is enabled (user-controlled toggle, free for everyone)
    const themeSettings = await new Promise((resolve) => {
      chrome.storage.local.get("themeEnabled", resolve);
    });

    // Default to disabled if setting doesn't exist yet
    const isThemeEnabled =
      themeSettings.themeEnabled !== undefined
        ? themeSettings.themeEnabled
        : false;

    // Return early if theme is disabled
    if (!isThemeEnabled) return;

    // Continue with normal initialization
    if (
      window.location.href.includes("login") ||
      window.location.href === "https://www.roblox.com"
    )
      return;

    Origin = await getEnvironmentOrigin();

    const smartPath = await getSmartRoutePath();
    console.log("Smart Path:", smartPath);

    // Only proceed if we have a valid path to route to
    if (!smartPath) {
      console.log("No matching route found, not loading iframe");
      return;
    }

    // Tolerate a transient background error here: loadAccount() rejects when
    // GET_RBLX_ACC hits chrome.runtime.lastError or returns an error. Since
    // initialize() runs fire-and-forget (pageManager MODULES.forEach), an
    // unhandled rejection would silently abort theme rendering before the
    // iframe is created. Proceed with no active account instead.
    try {
      await loadAccount();
    } catch (error) {
      console.warn("Theme init: failed to load Roblox account, continuing without active account:", error);
    }

    document.head.innerHTML = "";
    document.body.innerHTML = "";

    // Set up message handler before creating iframe
    await setupMessageHandlers();

    // Create theme iframe
    iframeRef = document.createElement("iframe");
    iframeRef.id = "bblox-theme-frame";

    // Add load listener before setting src
    iframeRef.addEventListener("load", () => {
      console.log("Iframe loaded, requesting initial path");
      // Request the current path from the iframe
      if (iframeRef.contentWindow) {
        iframeRef.contentWindow.postMessage({ type: "GET_CURRENT_PATH" }, "*");
      }
    });

    // Now set the src attribute
    iframeRef.src = smartPath;

    // Initialize with a default path
    const defaultPath = smartPath.replace(Origin, "").replace(/^\//, "");
    const initialUrl = window.location.href;

    // We need to ensure there's an initial state in the history
    // This uses replaceState to avoid adding a new entry
    originalReplaceState.call(
      window.history,
      { path: defaultPath },
      "",
      initialUrl,
    );
    document.title = `Roblox - ${formatPathForTitle(defaultPath)}`;

    // Style the iframe
    iframeRef.style.cssText = `
      border: none;
      width: 100%;
      height: 100vh;
      position: fixed;
      top: 0;
      left: 0;
      z-index: 9999;
      background: transparent;
    `;

    // Enhanced popstate event listener
    window.addEventListener("popstate", (event) => {
      console.log("Browser back/forward button pressed:", event.state);

      // Handle cases where the state might be null (initial page load)
      if (event.state && event.state.path) {
        navigateIframe(event.state.path);
      } else {
        // If state is missing, try to use the current URL path as fallback
        const currentPath = window.location.pathname.replace(/^\//, "");
        if (currentPath) {
          console.log("Using current path as fallback:", currentPath);
          navigateIframe(currentPath);
        }
      }
    });

    // Add iframe to the page
    document.body.appendChild(iframeRef);
  },
};

// Fetch route configurations from the remote server
async function fetchRouteConfigurations() {
  const now = Date.now();
  // Return cached configurations if they're still fresh
  if (routeConfigurations && now - lastConfigFetch < CONFIG_CACHE_DURATION) {
    console.log("Using cached route configurations");
    return routeConfigurations;
  }

  try {
    console.log("Fetching route configurations from server");
    const response = await fetch(Origin + "/routes.json");

    if (!response.ok) {
      throw new Error(`Failed to fetch routes: ${response.status}`);
    }

    const configs = await response.json();
    routeConfigurations = configs;
    lastConfigFetch = now;

    console.log("Route configurations updated:", configs);
    return configs;
  } catch (error) {
    console.error("Error fetching route configurations:", error);

    // Fall back to default configurations if we have them cached
    if (routeConfigurations) {
      console.log("Using last known configurations as fallback");
      return routeConfigurations;
    }

    // Otherwise, return default hardcoded configurations
    return getDefaultRouteConfigurations();
  }
}

// Default route configurations as fallback
function getDefaultRouteConfigurations() {
  return {
    socialRoutes: {
      friendRequests: {
        pattern: "users/friends",
        hash: "#!/friend-requests",
        target: "mySocial",
      },
      userFriends: {
        pattern: "users/(\\d+)/friends",
        hash: "#!/friends",
        target: "users/$1/social/friends",
      },
      userFollowing: {
        pattern: "users/(\\d+)/following",
        hash: "#!/following",
        target: "users/$1/social/following",
      },
      games: {
        pattern: "games/(\\d+)(/.*)?",
        hash: "",
        target: "games/$1",
        ignoreHash: true,
      },
      groups: {
        pattern: "communities/(\\d+)(/.*)?",
        hash: "",
        target: "groups/$1",
        ignoreHash: true,
      },
    },
    preserveRoutes: [
      "users/(\\d+)/social/friends",
      "home",
      "users/(\\d+)/profile",
    ],
  };
}

// Add this new function before getSmartRoutePath
async function getUniverseIdFromPlaceId(placeId) {
  try {
    const response = await fetch(
      `https://apis.roblox.com/universes/v1/places/${placeId}/universe`,
    );
    if (!response.ok) {
      console.error(`Failed to fetch universe ID: ${response.status}`);
      return null;
    }
    const data = await response.json();
    return data.universeId;
  } catch (error) {
    console.error("Error fetching universe ID:", error);
    return null;
  }
}
// Get environment origin based on user setting
async function getEnvironmentOrigin() {
  try {
    // Check environment setting in storage (can be "production", "beta", or "dev")
    const settings = await new Promise((resolve) => {
      chrome.storage.local.get(["themeEnvironment", "devModeEnabled"], resolve);
    });

    // Support legacy devModeEnabled setting for backward compatibility
    let environment = settings.themeEnvironment;
    if (!environment && settings.devModeEnabled === true) {
      environment = "dev";
    }
    if (!environment) {
      environment = "production"; // Default to production
    }

    switch (environment) {
      case "dev":
        return "http://localhost:5180";
      case "beta":
        return "https://beta.theme.betterroblox.com";
      case "production":
      default:
        return "https://theme.betterroblox.com";
    }
  } catch (error) {
    console.error("Error getting environment origin:", error);
    console.log("Falling back to production server");
    return "https://theme.betterroblox.com";
  }
}

// Modify the getSmartRoutePath function where it processes social routes
async function getSmartRoutePath() {
  const currentUrl = window.location.href;
  const currentPath = window.location.pathname;

  // Remove localization prefixes (like /en/)
  let cleanPath = currentPath.replace(/^\/[a-z]{2}(?:-[a-z]{2})?\//, "/");

  // Remove leading slash for consistency
  if (cleanPath.startsWith("/")) {
    cleanPath = cleanPath.substring(1);
  }

  // Apply routing rules
  const hash = window.location.hash;

  // Get route configurations (either from server or default)
  const configs = await fetchRouteConfigurations();

  // Process social routes
  if (configs.socialRoutes) {
    for (const [key, route] of Object.entries(configs.socialRoutes)) {
      const pattern = new RegExp(`^${route.pattern}$`);

      // Check if pattern matches and either hash matches or hash should be ignored
      if (
        pattern.test(cleanPath) &&
        (hash === route.hash || route.ignoreHash)
      ) {
        // Special handling for games - use placeId directly
        if (key === "games") {
          const matches = cleanPath.match(pattern);
          if (matches && matches.length > 1) {
            const placeId = matches[1];
            // Use placeId directly as rootPlaceId
            return `${Origin}/games/${placeId}`;
          }
        }

        // If the route has capture groups, replace them in the target
        if (route.pattern.includes("(")) {
          const matches = cleanPath.match(pattern);
          let target = route.target;

          // Replace $1, $2, etc. with the captured groups
          if (matches && matches.length > 1) {
            for (let i = 1; i < matches.length; i++) {
              target = target.replace(`$${i}`, matches[i]);
            }
          }

          return `${Origin}/${target}`;
        } else {
          return `${Origin}/${route.target}`;
        }
      }
    }
  }

  // Check preserve routes - paths that should be kept as is
  if (configs.preserveRoutes) {
    for (const pattern of configs.preserveRoutes) {
      const regex = new RegExp(`^${pattern}$`);
      if (regex.test(cleanPath)) {
        return `${Origin}/${cleanPath}`;
      }
    }
  }

  // If no routing rules match, return null to indicate iframe should not be loaded
  return null;
}

function sendToIframe(type, payload = {}, event = null) {
  if (!payload) {
    payload = {};
  }

  // Handle request ID tracking if event is provided
  if (
    event &&
    event.data &&
    event.data.payload &&
    typeof event.data.payload._requestId === "number"
  ) {
    payload._responseToId = event.data.payload._requestId;
  }

  if (iframeRef && iframeRef.contentWindow) {
    iframeRef.contentWindow.postMessage({ type, payload }, "*");
  } else {
    console.warn("Cannot send message: iframe not ready");
  }
}

// Navigate the iframe to a specific path
function navigateIframe(path) {
  if (!iframeRef || !iframeRef.contentWindow) return;
  console.log("Navigating to:", path);

  // Tell the iframe to navigate to the specified path
  iframeRef.contentWindow.postMessage(
    {
      type: "NAVIGATE_TO",
      payload: { path: path },
    },
    "*",
  );
}

// Format a path for the title
function formatPathForTitle(path) {
  let cleanPath = path;
  if (cleanPath.startsWith("/")) {
    cleanPath = cleanPath.substring(1);
  }
  if (!cleanPath) return "Home";
  return cleanPath.charAt(0).toUpperCase() + cleanPath.slice(1);
}

// Set up message handlers
async function setupMessageHandlers() {
  if (initialized) return;
  await initMessageHandler(sendToIframe);

  // Listen for all messages from the iframe
  window.addEventListener("message", (event) => {
    // Only process messages from our iframe - Security Check
    const win =
      iframeRef?.contentWindow || iframeRef?.contentDocument.defaultView;
    if (!event.source || event.source !== win) {
      return;
    }

    // Only process messages from the correct origin
    if (event.origin !== Origin) {
      return;
    }

    // Handle specific message types
    if (event.data) {
      if (event.data.type === "NAVIGATE") {
        // Iframe is telling us it has navigated
        const { path, title } = event.data.payload;
        updateUrlBar(path, title);
      } else if (event.data.type === "CURRENT_PATH") {
        // Iframe is telling us its current path
        const { path, title } = event.data.payload;
        console.log("Received current path from iframe:", path);

        if (!initialPageLoaded) {
          // This is the initial load
          updateUrlBar(path, title);
          initialPageLoaded = true;
        }
      }

      // Pass to general message handler
      handleMessage(event);
    }
  });

  initialized = true;
  console.log("Message handlers initialized");
}

// Update URL in address bar without page reload
function updateUrlBar(path, pageTitle = null) {
  if (!path) return;

  // Continue with normal URL update
  // Convert internal path to a roblox-like URL
  let robloxPath = path;
  if (robloxPath.startsWith("/")) {
    // Remove leading slash
    robloxPath = robloxPath.substring(1);
  }

  // Create a title if one wasn't provided
  const title = pageTitle || `Roblox - ${formatPathForTitle(robloxPath)}`;
  document.title = title;

  // Check if URL rewrites are disabled - if so, exit function
  chrome.storage.local.get("disableUrlRewrites", function (data) {
    if (data.disableUrlRewrites) {
      console.log("URL rewrites disabled, skipping URL bar update");
      return;
    }

    // Create the full URL that would appear in the address bar
    const baseUrl = window.location.origin;
    const newUrl = `${baseUrl}/${robloxPath}`;

    // Use History API to update URL without page reload (always use replaceState)
    try {
      const currentPath = window.location.pathname;
      const newPath = `/${robloxPath}`;

      // Only update if path is different
      if (currentPath !== newPath) {
        originalReplaceState.call(
          window.history,
          { path: robloxPath },
          "",
          newUrl,
        );
      } else {
        console.log("Skipping history update for same path:", newPath);
      }
    } catch (e) {
      console.error("Failed to update URL:", e);
    }
  });
}

export default themeLoader;
