export default function ServerComponent(
  ping,
  datacenter,
  playing,
  maxPlayers,
  avatars,
  placeId,
  gameInstanceId,
  inviteCallback,
  serverAge = null,
  distance = null,
  isClosest = false,
  queuePosition = null,
  placeVersion = null,
  isOutdated = false,
  fps = null,
  botPercentage = null,
  datacenters = null,
  clientLocation = null,
  joinDataPending = false,
  joinDataFailed = false,
  joinFailedStuckInQueue = false
) {
  const remainingPlayers = playing - 5;
  const fillPercentage = Math.round((playing / maxPlayers) * 100);

  // Calculate performance percentage based on 60 FPS
  const performancePercentage = fps ? Math.round((fps / 60) * 100) : null;

  // Calculate distance percentage relative to furthest datacenter
  const calculateDistancePercentage = () => {
    if (!distance || !datacenters || !clientLocation) return null;

    // Calculate distances to all datacenters from client location
    const distances = [];
    Object.values(datacenters).forEach((dc) => {
      if (dc.location?.latLong) {
        const [dcLat, dcLng] = dc.location.latLong;
        const dcDistance = calculateDistance(
          clientLocation.latitude,
          clientLocation.longitude,
          dcLat,
          dcLng
        );
        distances.push(dcDistance);
      }
    });

    if (distances.length === 0) return null;

    const maxDistance = Math.max(...distances);
    // Invert the percentage so higher values mean closer servers
    const percentage = Math.round(100 - (distance / maxDistance) * 100);
    return percentage;
  };

  // Haversine formula for distance calculation
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371; // Earth's radius in kilometers
    const dLat = toRadians(lat2 - lat1);
    const dLon = toRadians(lon2 - lon1);
    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(toRadians(lat1)) *
        Math.cos(toRadians(lat2)) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  };

  const toRadians = (degrees) => degrees * (Math.PI / 180);

  const distancePercentage = calculateDistancePercentage();
  const queuePos = queuePosition != null && Number(queuePosition) > 0 ? Number(queuePosition) : 0;

  const cardBorderClass = joinDataFailed
    ? "tw-border-amber-500/80 dark:tw-border-amber-500/70"
    : joinDataPending
      ? "tw-border-blue-400/70 dark:tw-border-blue-500/60"
      : "tw-border-gray-300 dark:tw-border-gray-700";

  const failDetail = joinFailedStuckInQueue
    ? "Join queue did not clear (gave up after several tries)"
    : "Could not load server details";

  const regionHeaderHtml = joinDataFailed
    ? `<div class="tw-flex tw-flex-col tw-gap-0.5">
         <p class="tw-font-semibold tw-text-amber-700 dark:tw-text-amber-400">Region unavailable</p>
         <p class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">${failDetail}</p>
       </div>`
    : joinDataPending
      ? `<div class="tw-flex tw-flex-col tw-gap-0.5 tw-text-gray-600 dark:tw-text-gray-300" aria-live="polite">
           <div class="tw-flex tw-items-center tw-gap-2">
             <span class="tw-inline-block tw-h-3.5 tw-w-3.5 tw-shrink-0 tw-rounded-full tw-border-2 tw-border-current tw-border-t-transparent tw-animate-spin" aria-hidden="true"></span>
             <span class="tw-text-sm tw-font-medium">${
               queuePos > 0 ? `Join queue #${queuePos}` : "Loading region…"
             }</span>
           </div>
           ${
             queuePos > 0
               ? `<p class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400 tw-ml-6">Polling for region…</p>`
               : ""
           }
         </div>`
      : `<p class="tw-font-semibold dark:tw-text-white">${
          datacenter?.location?.country || "Unknown"
        }</p>`;

  const statsLocationHtml = joinDataFailed
    ? `<p class="tw-text-center tw-text-sm tw-font-semibold tw-text-amber-700 dark:tw-text-amber-400">—</p>`
    : joinDataPending
      ? `<p class="tw-text-center tw-text-sm tw-text-gray-500 dark:tw-text-gray-400 tw-animate-pulse">${
          queuePos > 0 ? `In Roblox queue — retrying…` : "Resolving location…"
        }</p>`
      : `<p class="tw-text-center tw-text-md tw-font-semibold">${
          datacenter?.location?.city || "Unknown"
        } - ${datacenter?.location?.region || "Unknown"}</p>`;

  const remainingPlayersLabel =
    remainingPlayers > 0
      ? `<div class="tw-bg-gray-200 dark:tw-bg-gray-500 tw-w-14 tw-h-14 tw-rounded-full tw-flex tw-items-center tw-justify-center">
            <p class="tw-text-center tw-text-xl tw-font-semibold tw-text-gray-500 dark:tw-text-white">+${remainingPlayers}</p>
          </div>
          `
      : "";
  // Create avatar HTML elements using the provided avatar URLs
  const avatarElements = Object.values(avatars)
    .slice(0, 5)
    .map((url) =>
      url
        ? `<img src="${url}" class="tw-bg-gray-300 dark:tw-bg-gray-500 tw-w-14 tw-h-14 tw-object-cover tw-rounded-full" />`
        : `<span class="tw-thumbnail-2d-container tw-icon-blocked tw-avatar-card-image tw-rounded-full"></span>`
    )
    .join("");

  // Sanitize values interpolated into the inline onclick / attributes to block
  // page-context code injection via a malicious jobId/placeId. A real jobId is a
  // UUID and placeId is numeric, so stripping to those character sets is lossless.
  const safePlaceId = Number(placeId) || 0;
  const safeJobId = String(gameInstanceId).replace(/[^a-zA-Z0-9-]/g, "");

  const template = /*html*/ `
    <div id="server-card" betterblox-server-id="${safeJobId}" class="tw-bg-white dark:tw-bg-[#393b3d] tw-h-96 tw-w-56 tw-rounded-lg tw-p-2 tw-border-2 ${cardBorderClass} tw-shadow-md tw-flex tw-flex-col tw-relative" ${joinDataPending ? 'aria-busy="true"' : ""}>
        <div class="tw-flex tw-flex-row tw-justify-between tw-items-center tw-min-h-[2.25rem]">
          ${regionHeaderHtml}
        </div>
        
        ${
          isClosest
            ? `<div class="tw-absolute tw-top-2 tw-right-2 tw-bg-gradient-to-r tw-from-green-400/80 tw-to-green-500/60 tw-backdrop-blur-sm tw-text-white tw-text-xs tw-font-semibold tw-px-2 tw-py-1 tw-rounded-lg tw-shadow-lg tw-border tw-border-green-300/30">
                ⚡ Closest
              </div>`
            : ""
        }

        <div class="tw-grid tw-grid-cols-3 tw-gap-1 tw-w-full tw-mt-4 tw-h-32">
          ${avatarElements}
          ${remainingPlayersLabel}
        </div>
        
        <!-- Player count and progress bar -->
        <div class="tw-mt-2">
          <div class="tw-flex tw-justify-between tw-items-center tw-mb-1">
            <p class="tw-text-sm tw-font-medium dark:tw-text-white">${playing} of ${maxPlayers} people max</p>
            <p class="tw-text-xs tw-text-gray-500 dark:tw-text-gray-400">${fillPercentage}% full</p>
          </div>
          <div class="tw-w-full tw-bg-gray-200 dark:tw-bg-gray-600 tw-rounded-full tw-h-2">
            <div class="tw-h-2 tw-rounded-full tw-transition-all tw-duration-300 tw-bg-gray-400 dark:tw-bg-gray-300" style="width: ${fillPercentage}%"></div>
          </div>
        </div>
        
        <!-- Server Info Table -->
        <div class="tw-mt-2 tw-bg-gray-50 dark:tw-bg-gray-700 tw-rounded-md tw-p-2">
          <table class="tw-w-full tw-text-xs">
            <tbody>
              <tr class="tw-border-b tw-border-gray-200 dark:tw-border-gray-600">
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300 tw-w-1/3">Ping</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white tw-w-1/3">${
                  ping || "N/A"
                }ms</td>
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300 tw-w-1/3 tw-pl-4">Speed</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white">${
                  performancePercentage !== null
                    ? performancePercentage + "%"
                    : "N/A"
                }</td>
              </tr>
              <tr class="tw-border-b tw-border-gray-200 dark:tw-border-gray-600">
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300">Version</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white ${isOutdated ? "tw-text-orange-500" : ""
                }">${placeVersion || "N/A"}${isOutdated ? " (Old)" : ""}</td>
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300 tw-pl-4">Age</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white">${
                  serverAge || "N/A"
                }</td>
              </tr>
              <tr>
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300">Closest</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white">${
                  distancePercentage !== null ? distancePercentage + "%" : "N/A"
                }</td>
                <td class="tw-py-1 tw-font-medium tw-text-gray-600 dark:tw-text-gray-300 tw-pl-4">Bots</td>
                <td class="tw-py-1 tw-text-right tw-text-gray-800 dark:tw-text-white">${
                  botPercentage !== null ? botPercentage + "%" : "N/A"
                }</td>
              </tr>
            </tbody>
          </table>
        </div>
        <div class="tw-stats tw-border-[1px] tw-border-gray-300 dark:tw-border-gray-500 tw-rounded-md tw-my-2 dark:tw-text-white">
          ${statsLocationHtml}
        </div>
        <div class="tw-mt-auto">
        <button class="tw-bg-transparent tw-border-[1px] tw-border-gray-400 dark:tw-border-gray-300 tw-text-black dark:tw-text-white tw-font-semibold hover:tw-bg-gray-200 hover:tw-border-gray-400 dark:hover:tw-bg-gray-600 dark:hover:tw-border-gray-600 tw-px-4 tw-rounded-md tw-text-xs tw-w-full" id="join-button" onclick="Roblox.GameLauncher.joinGameInstance(${safePlaceId}, '${safeJobId}')">
          Join${
            queuePosition && queuePosition > 0
              ? ` (${queuePosition} in queue)`
              : ""
          }
        </button>
           
          <!-- <div class="tw-grid tw-grid-cols-6 tw-gap-1">
            <button class="tw-col-span-4 tw-bg-transparent tw-border-[1px] tw-border-gray-400 dark:tw-border-gray-300 tw-text-black dark:tw-text-white tw-font-semibold hover:tw-bg-gray-200 hover:tw-border-gray-400 dark:hover:tw-bg-gray-600 dark:hover:tw-border-gray-600 tw-px-4 tw-rounded-md tw-text-xs tw-w-full" id="join-button" onclick="Roblox.GameLauncher.joinGameInstance(${safePlaceId}, '${safeJobId}')">Join</button>
            <button class="tw-col-span-2 tw-bg-transparent tw-border-[1px] tw-border-gray-400 dark:tw-border-gray-300 tw-text-black dark:tw-text-white tw-font-semibold hover:tw-bg-gray-200 hover:tw-border-gray-400 dark:hover:tw-bg-gray-600 dark:hover:tw-border-gray-600 tw-px-4 tw-rounded-md tw-text-xs" id="invite-button">Invite</button>
          </div> -->
        </div>
      </div>
    `;

  const container = document.createRange().createContextualFragment(template);

  // Add click event listener to the join button
  const joinButton = container.querySelector("#join-button");
  // joinButton.addEventListener("click", () => {
  //   console.log(placeId, gameInstanceId);
  //   window.Roblox.GameLauncher.joinGameInstance(placeId, gameInstanceId);
  // });

  const inviteButton = container.querySelector("#invite-button");
  if (inviteButton && typeof inviteCallback === "function") {
    inviteButton.addEventListener("click", inviteCallback);
  }

  return container;
}
